(window.COSMIC_I18N = window.COSMIC_I18N || {}).pt = Object.freeze({"moon":{"aries":"a Lua em Áries","taurus":"a Lua em Touro","gemini":"a Lua em Gêmeos","cancer":"a Lua em Câncer","leo":"a Lua em Leão","virgo":"a Lua em Virgem","libra":"a Lua em Libra","scorpio":"a Lua em Escorpião","sagittarius":"a Lua em Sagitário","capricorn":"a Lua em Capricórnio","aquarius":"a Lua em Aquário","pisces":"a Lua em Peixes"},"sky":{"classic":{"fire":["{moon} estimula o impulso de agir e convida você a escolher uma direção clara antes de avançar.","{moon} traz uma energia intensa, mais produtiva quando encontra um objetivo preciso.","{moon} desperta a vontade de seguir em frente sem esperar que tudo esteja perfeito.","{moon} favorece iniciativas sinceras e lembra o valor de agir com equilíbrio.","{moon} ilumina aquilo que merece sua coragem, e não sua pressa.","{moon} imprime ao céu um ritmo intenso, que pede discernimento."],"earth":["{moon} convida você a reencontrar referências simples e atitudes concretas.","{moon} valoriza a paciência e o prazer de avançar no seu próprio ritmo.","{moon} volta a atenção para o que se constrói com constância.","{moon} favorece a calma, a estabilidade e o cuidado com os detalhes.","{moon} inspira escolhas práticas sem sacrificar o que faz bem a você.","{moon} lembra que um progresso discreto pode ter bases profundamente sólidas."],"air":["{moon} estimula as trocas e faz circular novas ideias.","{moon} abre a mente para opiniões diferentes e perspectivas inesperadas.","{moon} incentiva a curiosidade, sem deixar que você perca o fio da meada.","{moon} dá às conversas um lugar especial no dia.","{moon} favorece a leveza e as descobertas que nascem de uma pergunta.","{moon} convida a organizar os pensamentos sem limitar a imaginação."],"water":["{moon} torna as emoções mais presentes e convida você a acolhê-las com delicadeza.","{moon} desperta lembranças que podem iluminar o presente.","{moon} incentiva a escuta interior e os momentos de proximidade sincera.","{moon} dá mais profundidade às impressões e aos silêncios.","{moon} favorece a intuição quando você lhe dá um pouco de espaço.","{moon} convida você a cuidar de seus vínculos sem esquecer suas necessidades."]},"funny":{"fire":["{moon} dá energia para você correr atrás do ônibus, mesmo já estando dentro dele.","{moon} transforma qualquer fila num teste de paciência sem reconhecimento oficial.","{moon} propõe começar cinco projetos antes de a chaleira terminar seu trabalho.","{moon} acende uma fogueira interior para uma decisão tão grave quanto escolher uma pizza.","{moon} sussurra para você clicar em « enviar » antes de reler a mensagem.","{moon} distribui coragem para todo mundo, menos para quem precisa esperar sua vez."],"earth":["{moon} decreta que um cobertor e uma agenda lotada podem conviver em paz.","{moon} transforma a lista de compras num documento de importância estratégica máxima.","{moon} lembra que dá para ter ambição sem sair da poltrona favorita.","{moon} eleva a arrumação de uma gaveta à categoria de grande vitória pessoal.","{moon} aconselha pensar com calma, principalmente se alguém ameaçar mudar o sofá de lugar.","{moon} transforma a pausa para o lanche num compromisso oficialmente prioritário."],"air":["{moon} abre doze conversas e esquece por que a primeira começou.","{moon} faz surgir três ideias geniais entre duas notificações sem importância.","{moon} incentiva você a contar uma história que acaba exigindo mapa e diagrama.","{moon} distribui opiniões mais rápido do que o grupo consegue acompanhar.","{moon} transforma um simples « oi » num debate sobre o sentido da vida.","{moon} ajuda você a encontrar as palavras e, depois, palavras demais."],"water":["{moon} coloca uma trilha sonora dramática na simples arrumação de uma caixa velha.","{moon} faz você sentir saudade de um domingo da infância cuja data nem lembra mais.","{moon} transforma uma foto borrada numa lembrança digna de museu particular.","{moon} torna emocionante o reencontro com uma xícara esquecida no armário.","{moon} leva você a perguntar se está tudo bem a uma planta meio inclinada.","{moon} acrescenta profundidade a uma mensagem que só dizia « ok »."]},"piquant":{"fire":["{moon} convence você de que urgência é um traço de personalidade, não um problema de organização.","{moon} provoca uma competição imaginária com alguém que só queria passar.","{moon} faz você disparar antes mesmo de saber o endereço.","{moon} instala um cronômetro invisível em cada conversa tranquila.","{moon} trata sua impaciência como um talento que o mundo deveria admirar.","{moon} autoriza você a declarar vitória antes de os outros entenderem as regras."],"earth":["{moon} transforma sua zona de conforto em território de vigilância máxima.","{moon} confirma que trocar uma almofada exige consulta pública.","{moon} veta cosmicamente qualquer proposta que atrapalhe seus hábitos.","{moon} lembra que, de tanto buscar algo sólido, você pode acabar se casando com seu móvel favorito.","{moon} transforma sua rotina em constituição impossível de reformar.","{moon} faz você considerar a espontaneidade um incidente que precisa ser comunicado."],"air":["{moon} oferece mil ideias e deixa para outra pessoa a tarefa de terminar uma.","{moon} abre um debate e depois outro para decidir se era preciso debater.","{moon} incentiva suas opiniões a mudarem mais rápido que a tela do celular.","{moon} multiplica os caminhos até fazer da chegada algo completamente opcional.","{moon} dá a você a última palavra, mais quatorze palavras finais de brinde.","{moon} coloca seus pensamentos numa reunião permanente, sem nomear um responsável."],"water":["{moon} transforma um silêncio comum num dossiê emocional de quatro páginas.","{moon} põe na pauta uma lembrança que todo mundo já tinha arquivado.","{moon} ajuda você a interpretar um ponto-final como um acontecimento histórico.","{moon} coloca nostalgia até na embalagem de um biscoito antigo.","{moon} organiza um comitê de crise por causa de um suspiro ouvido de longe.","{moon} faz você sentir o clima de um ambiente antes de entrar nele e depois escrever um romance inteiro a respeito."]}},"mercury":{"classic":["Mercúrio retrógrado convida a reler suas mensagens antes de enviá-las. Um detalhe pode evitar um mal-entendido.","Uma conversa antiga pode voltar à tona com Mercúrio retrógrado. Procure compreender o contexto.","Mercúrio retrógrado sugere conferir os detalhes em vez de presumir que todos entenderam a mesma coisa."],"funny":["Mercúrio retrógrado recomenda uma segunda leitura. Sua mensagem talvez pareça misteriosa só porque falta uma palavra.","Um assunto antigo voltou? Mercúrio retrógrado aparentemente achou a gaveta das conversas inacabadas.","Mercúrio retrógrado põe a comunicação à prova. Antes de culpar o cosmos, confira o destinatário da mensagem."],"piquant":["Mercúrio retrógrado não é licença cósmica para mandar mensagens ambíguas e desaparecer em seguida.","Às vezes o passado volta com Mercúrio retrógrado. Você não precisa reabrir todos os arquivos que ele traz.","Mercúrio retrógrado sugere reler suas palavras. A outra pessoa não tem obrigação de adivinhar as legendas dos seus pensamentos."]},"signs":{"aries":{"classic":{"career":["Sua iniciativa pode abrir caminhos interessantes no trabalho. Ainda assim, defina bem seu objetivo antes de mobilizar os outros.","Quando um projeto demora a começar, sua energia encontra espaço para agir. Diferencie o que depende de você do que exige uma decisão coletiva.","Um desafio profissional desperta seu instinto de conquista. Sua influência cresce quando as ideias alheias também têm voz.","A concorrência desperta sua determinação. Transforme-a em estímulo para evoluir, não numa medida constante do seu valor.","Diante de uma orientação vaga, seu impulso é agir imediatamente. Algumas perguntas objetivas podem evitar desvios desnecessários.","Essa vontade de obter resultados rápidos merece certa flexibilidade. Divida suas ambições em etapas visíveis e valorize cada conquista.","Se uma reunião se prolonga, sua franqueza pode movimentar as coisas. Escolha, porém, a hora certa de falar.","Tomar a frente combina com você. Compartilhe também seus métodos para que a equipe avance ao seu lado, não atrás de você."],"love":["Sua espontaneidade dá vitalidade às relações. Permita que a outra pessoa encontre o próprio ritmo.","Quando você gosta de alguém, demonstra isso sem rodeios. Ouvir com atenção pode dar tanta força ao seu carinho quanto agir.","Uma palavra dita depressa pode ir além da sua intenção. Reserve um tempo para reformular antes de transformar uma discordância em desafio.","A vontade de viver intensamente orienta seus impulsos do coração. Momentos tranquilos também alimentam a cumplicidade.","Diante de opiniões diferentes, sua sinceridade é valiosa quando aceita nuances. Procure compreender antes de convencer.","Essa necessidade de independência faz parte do seu equilíbrio. Expresse-a claramente sem esperar que a outra pessoa adivinhe o que você deseja.","Ao querer dar sempre o primeiro passo, você pode acabar assumindo toda a iniciativa. Abra espaço para as surpresas do outro.","Reconhecer um erro não diminui sua força. Um gesto simples às vezes acalma mais do que uma longa argumentação."],"wellbeing":["Sua energia intensa merece momentos de recuperação. Faça uma pausa de verdade entre um impulso e outro.","Quando a impaciência cresce, uma caminhada sem destino definido pode ajudar você a desacelerar.","Um dia cheio de desafios pode fazer você ignorar o cansaço comum. Respeite sua necessidade de descanso sem encará-la como obstáculo.","O gosto pela ação acompanha você a toda parte. Reserve um momento sem nenhuma obrigação de realizar algo.","Diante de um contratempo, respire antes de recomeçar. Esse pequeno intervalo pode ajudar você a recuperar a calma.","O hábito de fazer tudo depressa pode aparecer até nas refeições. Dê a si mesmo um momento tranquilo para saborear o que gosta.","Aprender a esperar não significa deixar de avançar. Experimente uma atividade que valorize o ritmo, não o resultado.","Se o sono fica em segundo plano diante dos seus projetos, devolva a ele um lugar na sua rotina."],"wisdom":["Sua coragem cresce quando aprende a escolher suas batalhas.","A força de um impulso depende também da direção que você lhe dá.","Um passo pensado pode levar mais longe que uma corrida precipitada.","Amadurecer é saber quando não entrar numa competição.","A impaciência aponta um desejo; a paciência abre o caminho até ele.","Avançar juntos às vezes exige diminuir o ritmo do primeiro passo.","Uma fala sincera ganha valor quando também deixa espaço para ouvir.","O verdadeiro começo vem antes do movimento, na clareza da intenção."],"roast":["Seu entusiasmo às vezes chega tão antes de você que ninguém teve tempo de entender seu plano.","Ao tentar resolver toda discordância imediatamente, você deixa pouco espaço para respostas que precisam de tempo.","Suas boas ideias perdem força quando você também impõe a velocidade da execução.","A vontade de ganhar pode transformar uma conversa simples numa competição sem necessidade.","A sinceridade continua valiosa quando vem acompanhada das palavras certas.","Aquilo que você chama de eficiência às vezes parece uma decisão tomada antes de ouvir a pergunta.","Quando algo resiste, você dobra a energia justamente quando uma pausa seria mais útil.","Você sabe iniciar projetos com convicção; acompanhar seu progresso com paciência exige bem mais esforço."]},"funny":{"career":["Seu relatório já está marcado como 'concluído'. O chefe acaba de abrir a reunião em que deveria explicar do que se trata.","Quando um colega anuncia uma « reunião rapidinha », você procura instintivamente a linha de chegada.","Uma tarefa marcada como « urgente » deixa você feliz. Finalmente um documento que entende seu estilo de vida.","A competição começa quando duas pessoas caminham até a copiadora. A outra ainda nem sabe que está participando.","Você criou uma planilha para acompanhar suas doze ideias. A coluna 'ler antes de começar' ficou só de enfeite.","Esse projeto deveria ser coletivo. Você já dividiu as tarefas, começou tudo e perguntou por que ninguém acompanha.","Se a chefia diz « vá com calma », você misteriosamente escuta « bata o recorde ».","Fazer uma pausa para o café parece razoável, desde que você chegue antes de todo o departamento.","A reunião era para dividir funções. Você chegou com três projetos iniciados e convites para a festa de encerramento.","Você adora projetos-piloto. Sobretudo quando o piloto, o avião e a pista aparecem com seu nome no cronograma.","Um colega escreveu 'ideia a desenvolver'. Você encomendou pás digitais e reservou o primeiro horário de apresentação.","Sua versão de trabalho em equipe: você diz 'vamos!' enquanto os outros ainda procuram os sapatos de escritório."],"love":["Sua ideia de encontro romântico inclui espontaneamente uma atividade em que alguém precisa chegar primeiro. Até o minigolfe vira Olimpíada.","Quando a outra pessoa demora a escolher o restaurante, você já consultou três cardápios e reservou mentalmente uma mesa.","Você se apaixona como quem abre um presente: arranca o laço, abre um sorrisão e fica com o embrulho na cabeça.","O carinho deixa você ousado. Você manda uma mensagem fofa e verifica a resposta antes mesmo de soltar o celular.","Diante de um « vamos ver », você pede imediatamente dia, horário e compromisso por escrito, tudo com um sorriso.","Esse jantar à luz de velas parece tranquilo até você transformar a escolha da sobremesa num debate apaixonado.","Assim que anunciam uma surpresa, você procura pistas nos armários. Esperar não faz parte da sua linguagem amorosa.","Se alguém provoca você de brincadeira, já prepara uma resposta afiada. Só depois lembra que aquilo era carinho.","Sua técnica de conquista tem três etapas: paixão instantânea, grande gesto e descobrir o nome do restaurante.","Você preparou uma surpresa romântica tão depressa que a vela nem teve tempo de sair da embalagem.","Bastou trocar olhares e você já sugere uma aventura a dois. A outra pessoa só queria escolher um doce.","Você promove reconciliações com tanta energia que as flores chegam antes do fim da conversa."],"wellbeing":["Seu descanso ideal parece uma corrida da qual você tirou o cronômetro, mas não a velocidade.","Quando tenta meditar, seu cérebro dá ordens a todos os pensamentos para que se acalmem mais rápido.","Uma caminhada tranquila vira expedição assim que você avista uma escadaria para subir.","A soneca parece suspeita: por que ficar parado quando tantas almofadas ainda precisam ser reorganizadas?","Diante do silêncio, você aguenta exatamente oito segundos antes de perguntar se todo mundo também está entediado.","Esse copo de água espera na mesa enquanto você termina três coisas « rapidinhas ». Ele não assinou contrato para tanto suspense.","Respirar com calma é uma ótima ideia, desde que você não transforme o exercício numa competição de fôlego.","Se sair para tomar um ar, avise os próximos: « uma voltinha » pode virar uma trilha com objetivo definido.","Você instalou um aplicativo de relaxamento. Ele mostra 'parabéns' porque você ficou um minuto sem trocar de tela.","Uma caminhada para tomar ar fresco termina com seu ranking pessoal das escadas do bairro.","Seu tapete de ioga mal conhece você. É usado principalmente como linha de largada.","Você tentou ficar sem fazer nada uma tarde. Oito minutos depois, classificava os móveis por velocidade de deslocamento."],"wisdom":["Sua coragem é enorme; o botão « esperar » continua desaparecido.","A velocidade abre portas, desde que você não confunda a entrada com a saída.","Às vezes, a maior coragem é ler a placa antes de passar pela barreira.","Escolher uma direção evita transformar cada desvio numa volta ao mundo.","O universo avança no seu ritmo, sem ler suas mensagens de cobrança.","Corra atrás dos sonhos, mas confira primeiro se a porta está aberta.","Um impulso extraordinário continua sendo impulso, ainda que ninguém tenha conferido o mapa.","O silêncio não é necessariamente uma provocação pessoal.","A primeira porta nem sempre é a certa. A parede ao lado pode confirmar.","A coragem sabe partir; o bom senso às vezes espera no vestiário para conferir o caminho.","Correr atrás de uma ideia não dispensa perguntar onde ela mora.","Um desvio não é fracasso. Às vezes é a única forma de enxergar a placa que você passou voando."],"roast":["Seu GPS não ousou dizer « recalculando » duas vezes. Ele conhece seu temperamento.","Você declarou guerra à máquina de biscoitos. No julgamento, a moeda que deveria entrar foi convocada como testemunha.","Você chama de « conversa construtiva » aquela em que todo mundo adota sua ideia só para poder ir para casa.","A campainha toca e você já está na porta antes do som terminar. Até o entregador fica surpreso.","O GPS aconselha virar. Você responde 'eu sei o caminho' com a confiança de um explorador diante da própria garagem.","O controle remoto não muda de canal na primeira tentativa. Você entrega uma notificação extrajudicial escrita num guardanapo.","A palavra « devagar » desperta em você a mesma desconfiança de um elevador que para em todos os andares.","Diante de uma notificação irritante, você fica furioso e logo a perdoa quando ela traz uma boa notícia.","O despertador toca. Você negocia tão firmemente que ele toca de novo para convocar uma testemunha.","Você acusou a escada rolante de falta de iniciativa. Ela seguia fazendo exatamente o trabalho dela.","A porta automática demora para abrir. Você apresenta seu plano de reforma das entradas públicas.","Um quebra-cabeça resiste. Você acusa a caixa de esconder de propósito a peça do canto superior esquerdo."]},"piquant":{"career":["Você iniciou uma obra sem ler as instruções. A equipe descobre a planta olhando para a demolição.","Sua agenda tem quatro colunas: urgente, urgentíssimo, ontem e 'por que ainda não acabou?'. A segunda-feira saiu do grupo.","O colega que diz « vamos pensar » acabou de ativar seu plano de ataque. O raciocínio se escondeu debaixo da mesa.","Quando surge um obstáculo, você avança para ensiná-lo a ter modos. O obstáculo era uma porta aberta.","Você transformou a distribuição dos documentos num campeonato interno. Os estagiários vieram buscar papéis, não medalhas.","Você tomou uma decisão histórica ignorando seis páginas de recomendações. O relatório final começa com 'Conforme a página um'.","A reunião de abertura nem começou e você já anuncia os resultados. A ata usa o condicional, em respeito aos fatos.","Sua autoridade natural chega à impressora: você lhe dá ordens. Ela responde com um atolamento diplomático.","Últimas notícias: você terminou um projeto antes de descobrir para que servia. O cliente queria um cartaz; você inaugurou uma rodovia.","Comunicado interno: toda instrução não lida passa a ser decoração de pasta. Você já assinou.","Seu escritório parece um centro de comando sem mapas: muitas ordens, nenhuma certeza sobre o destino da tropa.","Você pôs 'resultado imediato' na pauta. A ata registra: 'A realidade não compareceu'."],"love":["Sua franqueza romântica chega como um alarme sem botão de desligar. A delicadeza perdeu sua vez de falar.","Você transforma a escolha de um filme a dois num duelo de argumentos. Os créditos sobem antes da trégua.","Qualquer discordância faz você defender sua tese como num discurso histórico. O assunto era a cor de uma caneca.","Quando pedem que você espere a surpresa ficar pronta, já está abrindo a embalagem. O mistério pediu demissão.","Sua declaração carinhosa tem a precisão de um lançamento de foguete. A outra pessoa ainda procurava onde deixar o casaco.","Por trás das suas grandes declarações, uma vozinha exige resposta imediata. Nem o coração do calendário trabalha com esse prazo.","Mensagens sem resposta rápida inspiram quatro hipóteses e três intervenções. O celular pediu um mediador.","Você planeja um fim de semana romântico como uma expedição relâmpago. A surpresa é descobrir que ninguém consultou a outra pessoa.","Seu cortejo amoroso parece trailer de cinema: duas conversas, música épica e créditos do casamento imaginário.","Você chama de paixão à primeira vista. A agenda chama de tomada de controle do próximo mês.","Uma reconciliação com você parece fogos de artifício enquanto a outra pessoa ainda explica o problema. Lindo, péssimo timing.","Você organizou uma caça ao tesouro romântica. A única pista era 'ande logo'; até o tesouro desistiu de se esconder."],"wellbeing":["Seu programa de descanso inclui uma corrida até o banco mais próximo. O banco jamais imaginou tamanha responsabilidade.","Você sai para relaxar e ultrapassa cada caminhante imaginário. As árvores exigem um árbitro.","O sofá recebe você por cinco minutos; depois, é acusado de falta de ambição. As almofadas fundaram um sindicato.","Quando a fila anda devagar, você negocia com o espaço-tempo. O universo arquiva sua solicitação.","Uma pausa sem cronômetro parece suspeita. Você instala uma linha de chegada perto da chaleira.","Por trás da sua energia explosiva, uma rede tenta explicar o conceito de calma. Você a interrompe.","Momentos de silêncio despertam sua vontade de iniciar um debate. A planta se recusa a tomar partido.","Você transformou a arrumação de uma gaveta em prova de velocidade. As meias foram classificadas pela ordem de chegada.","Avaliação do cliente: 'O banco é confortável, mas não evolui'. Uma estrela, assinada pela sua panturrilha inquieta.","O relógio contou seus movimentos durante o descanso. Registrou uma corrida de mãos pelos braços da poltrona.","Você transformou o alongamento em fase classificatória. O tapete ganhou medalha por resistência passiva.","Previsão do tempo interior: agitação constante, com breves momentos de calma durante o carregamento de vídeos."],"wisdom":["Correr sem bússola não faz de você um pioneiro. Só faz você chegar bem cedo ao lugar errado.","Você não avança sem pensar: envia a reflexão como batedora depois da batalha.","A última palavra não é troféu. Você já encomendou o pedestal.","Quando dizem « devagar », você escuta « prove que consegue ser mais rápido ».","Coragem é como uma chave. Às vezes você a usa como martelo numa porta aberta.","Por trás da sua bravura, o bom senso pede um colete refletivo.","Nem todos os obstáculos provocam você. Alguns só estão tentando ser móveis.","Esperar sua vez não é capitulação. Sua bandeira branca ainda está na embalagem.","Valentia sem direção é um cartão-postal enviado da cidade errada.","Você às vezes confunde tomar a dianteira com sair antes de a história começar.","O atalho mais ousado pode levar de volta ao começo, acompanhado de uma conta da sapataria.","Saber aonde ir é uma qualidade. Descobrir depois de três partidas espetaculares é seu método particular."],"roast":["Sua torradeira recebeu advertência por falta de agilidade. Você lhe concede uma última fatia em período de experiência.","Você declarou guerra ao GPS por sugerir outra rota. A rotatória prepara sua defesa.","Você recorreu do resultado de um jogo de tabuleiro disputado sozinho. A comissão de apelação, também você, prepara a revanche.","Quando a máquina de café demora, você fala com ela como se fosse adversária. Ela protesta servindo descafeinado.","Uma porta emperrada ofende você pessoalmente. A placa « puxe » testemunha contra você.","Por trás da sua franqueza, a diplomacia fica presa no pedágio dos seus argumentos.","Você deu uma palestra ao sinal vermelho sobre iniciativa individual. Ele ficou verde no meio do discurso.","Você desafiou o gato para um duelo de olhares. Ele bocejou; você contestou as regras na mesma hora.","A máquina de senhas mostrou 'aguarde'. Você prepara uma palestra sobre liberdade de circulação dos números.","Você brigou com seu reflexo por uma careta involuntária. O espelho preferiu não prestar depoimento.","Sua cafeteira foi promovida a adversária oficial. Venceu o debate sem responder absolutamente nada.","Você repreendeu o GPS por uma rua interditada. Uma voz robótica sugeriu discutir diretamente com a obra."]},"roastMy":["Áries, você não é impaciente: você é uma emergência que marca compromissos consigo mesma. Aperta o botão do elevador sete vezes e acusa o prédio de não trabalhar em equipe. Quando a porta se abre, entra correndo. Queria subir apenas um andar.","Você adora ganhar, mesmo quando ninguém está jogando. Cronometra a subida da escada, ultrapassa um desconhecido e o parabeniza pela participação. O sujeito só carregava compras. O comitê olímpico rejeitou sua inscrição.","Sua sinceridade tem a delicadeza de um tambor numa biblioteca. Pedem sua opinião sobre um enfeite e você inicia um debate nacional. No fim, convenceu até o vaso a mudar de lugar. A parede quer denunciar o excesso de argumentação.","Você avança antes de pensar e depois chama isso de coragem. Um móvel bloqueia sua passagem e você tenta negociar aos gritos. O móvel não sai do lugar. Você lhe concede uma vitória por decisão contestada.","Você consegue discutir com qualquer coisa que tenha uma função. GPS, despertador e cafeteira constam da sua lista de adversários. Nenhum aceitou o combate. A torradeira pediu trégua internacional.","Seu entusiasmo contagia, mas ninguém pediu que transformasse o piquenique numa competição. Você divide as equipes, inventa placar e distribui pontos para a toalha mais bem aberta. Seus amigos se sentam para comer. Você denuncia falta de espírito esportivo.","Você detesta esperar de maneira quase artística. Três pessoas na sua frente no balcão viram um grande obstáculo geopolítico. Você prepara mentalmente um discurso sobre eficiência. Quando chega sua vez, esqueceu o que ia pedir.","Você adora assumir o comando, especialmente quando alguém já está comandando. Uma pessoa organiza o passeio; você reescreve o roteiro e anuncia uma versão « mais dinâmica ». O grupo chega cedo ao endereço errado. Você reivindica o recorde de velocidade.","Sua raiva aparece depressa e vai embora mais depressa ainda. Você protesta com força contra um comentário e, dois minutos depois, oferece um biscoito com alegria. A outra pessoa ainda tenta lembrar o motivo da briga. Seu departamento de relações públicas apagou a ata.","Você encara qualquer contradição como desafio oficial. Um amigo prefere outro filme e você defende o seu como se o futuro do cinema dependesse disso. Ele concorda só para recuperar o silêncio. Você anuncia orgulhosamente uma vitória do diálogo.","Você gosta tanto de ser o primeiro que começa a conversa antes do outro dizer oi. Sua agenda tem projetos que nem sabem que existem. Você chama de dinamismo. O escritório chama de pré-estreia permanente.","Você chega ao jantar com uma ideia brilhante para cada minuto. Os outros pretendiam conversar em paz. Você transforma a escolha da música em cerimônia de abertura. O garçom procura discretamente os juízes da competição.","Sua especialidade é tratar qualquer obstáculo como provocação pessoal. Porta fechada vira desafio, manual vira boato e desvio vira afronta. No fim você acha o caminho certo. Era o indicado pela placa desde o início.","Você declara carinho com o ímpeto de quem inaugura uma ponte. O entusiasmo é sincero, mas você já está na foto oficial. A outra pessoa ainda procura o início da frase. A ponte nem foi construída.","O sossego intriga você como aparelho sem botão de ligar. Você tentou uma pausa, depois uma atividade leve, depois planejou suas próximas pausas. Seu dia de descanso agora tem oito metas. Só falta uma: descansar."]},"taurus":{"classic":{"career":["Sua constância dá solidez aos projetos. Ainda assim, aceite rever um método quando o contexto mudar.","Quando uma proposta mexer com seus hábitos profissionais, avalie-a com calma antes de rejeitá-la de imediato.","Uma tarefa de longo prazo combina com sua perseverança. Comunique regularmente seus avanços, mesmo os discretos.","A busca por segurança influencia suas decisões. Isso pode ser uma força, desde que não feche a porta para novas possibilidades.","Diante de uma urgência coletiva, sua calma ajuda a manter os pés no chão. Saiba, porém, distinguir prudência de imobilidade.","Seu gosto pelo trabalho bem-feito merece reconhecimento. Às vezes, entregar algo concluído vale mais do que ajustar detalhes indefinidamente.","Se alguém mudar sua organização, explique do que precisa para recuperar suas referências e avançar tranquilamente.","Preferir soluções comprovadas é natural para você. Um pequeno experimento pode, contudo, enriquecer sua maneira de agir."],"love":["Sua lealdade aparece nos gestos constantes. Deixe também espaço para os desejos inesperados de quem você ama.","Quando se apega a alguém, você busca construir algo duradouro. Uma conversa aberta pode fortalecer essa confiança.","Um hábito compartilhado pode se tornar uma verdadeira linguagem de carinho. Não o confunda com obrigação.","O prazer dos momentos simples alimenta seus vínculos. Deixe a pessoa ao seu lado escolher o programa de vez em quando.","Diante de uma discordância, sua firmeza merece vir acompanhada de uma escuta sem defesa antecipada.","Sua necessidade de estabilidade pode ser expressa com ternura. Ela não exige que tudo ao redor permaneça igual.","Você demonstra muito por meio de cuidados concretos. Lembre-se também de dizer o que sente com suas próprias palavras.","Se uma relação atravessa uma nova fase, acolha-a passo a passo, sem insistir em sua forma antiga."],"wellbeing":["Sua necessidade de conforto merece respeito. Crie um ambiente acolhedor sem se isolar do mundo exterior.","Quando o ritmo acelerar, um momento tranquilo à mesa com algo de que gosta pode ajudar a reencontrar suas referências.","Uma caminhada por um caminho conhecido pode ser uma pausa preciosa, principalmente se você observar o entorno.","O prazer das rotinas ajuda no seu equilíbrio. Permita que uma pequena novidade apareça sem pressão.","Diante de tantas solicitações, dê a si mesmo o direito de recusar o que invade seu descanso.","Seu sofá favorito pode acolher uma pausa de verdade, sem telas nem listas de tarefas pendentes.","Cuidar de si também envolve prazeres simples: música suave, luz agradável e tempo sem pressa.","Se as obrigações ocuparem todo o seu dia, desacelere e retome uma atividade que traga tranquilidade."],"wisdom":["Sua perseverança vira sabedoria quando aprende a mudar de caminho.","O conforto é precioso enquanto for refúgio, não fronteira.","Uma convicção sólida não precisa fechar a porta ao diálogo.","A estabilidade também se cultiva na capacidade de adaptação.","Saber saborear o presente não significa prender o tempo.","Uma mudança escolhida pode respeitar tudo o que você já ama.","Acolher o inesperado também enriquece a doçura do cotidiano.","Avançar devagar não impede chegar longe, desde que se continue andando."],"roast":["Seu apego aos hábitos vira resistência quando uma alternativa simples parece complicação desnecessária.","Depois que você decide algo, até argumentos pertinentes têm dificuldade para encontrar espaço.","Buscar conforto acima de tudo às vezes prende você a situações que já não combinam com seus desejos.","Ao exigir garantia antes de cada tentativa, você corre o risco de nunca descobrir algo novo de que possa gostar.","O prazer das coisas boas às vezes ocupa tanto espaço que a espontaneidade fica de fora.","Por trás da calma aparente existe uma determinação que pode deixar pouco espaço para opiniões alheias.","Sua necessidade de prever tudo tranquiliza você, mas pode cansar quem prefere improvisar.","Você prefere aperfeiçoar uma rotina a admitir que outro método seria mais simples."]},"funny":{"career":["Seu escritório gira em torno de três prioridades: eficiência, cadeira confortável e proibição de mexer na sua caneca.","Quando alguém propõe mudar de programa, você pergunta se o antigo cometeu algum crime.","Uma reunião na hora do almoço é um ataque a um pilar fundamental da sua organização.","A estabilidade tranquiliza você: seu fichário favorito está ali há tanto tempo que merece uma placa comemorativa.","Diante de um método novo, você exige uma demonstração, duas semanas para pensar e a opinião do grampeador.","Esse planejamento não muda facilmente. Foi aprovado por você, o que equivale quase a uma inscrição em pedra.","Se a tarefa exige paciência, escolhem você. Se exige trocar de lugar, o processo seletivo recomeça.","Fazer um trabalho bem-feito combina com você. O difícil é acreditar que outra pessoa consiga fazê-lo de um jeito diferente.","O programa anuncia atualização. Você salva uma imagem da tela antiga para lhe proporcionar uma aposentadoria digna.","Seu almoço é tão pontual que até a cantina acerta o relógio pela sua cadeira vazia.","Sua meta profissional: emprego estável, equipe confiável e zero surpresas no nome dos arquivos.","Um colega fala em 'inovação rápida'. Você responde educadamente: 'Claro, depois de validar os últimos quinze anos'."],"love":["Sua principal linguagem do amor é dividir a sobremesa. Mas atenção: « dividir » não significa « pegar a última colherada ».","Para conquistar você, ninguém precisa prometer milagres: basta lembrar que quinta é dia de macarrão e sábado tem sobremesa para dividir.","Uma noite perfeita começa com um bom jantar e termina sem que ninguém sugira sair de novo.","Romantismo, para você, é lembrar exatamente qual é a cobertura de pizza preferida da outra pessoa.","Diante de uma mudança de planos, você mantém o sorriso. Só precisa de um tempo para superar a perda do restaurante escolhido.","Você gosta tanto desse ritual a dois que gostaria de reservar um horário fixo para ele até segunda ordem.","Seu carinho aparece nos detalhes: você sabe o prato preferido da outra pessoa. Resta uma questão delicada: o tamanho da porção.","Se alguém disser « vamos improvisar », você responde com ternura: « claro, mas em qual cronograma? ».","No jantar, você deixa escolher a música. Já a última batata frita exige uma negociação bem estruturada.","Você é tão fiel aos rituais românticos que a reserva de sexta conhece você melhor que alguns amigos.","Um convite para dividir um doce vira aula expressa de geometria sobre partes exatamente iguais.","Para demonstrar carinho, você cozinha o prato preferido da outra pessoa. Também separa uma porção de controle, só por precaução."],"wellbeing":["Seu sofá tem um lugar reservado que se ajusta aos seus hábitos melhor que algumas roupas.","Quando sai para caminhar, o trajeto naturalmente inclui uma padaria e algum lugar para se sentar.","Uma pausa relaxante só fica completa depois de aprovadas a temperatura, a luz e a textura do cobertor.","O domingo inspira uma grande ambição: mover o mínimo de objetos sem perder o controle remoto.","Diante de um convite esportivo, você propõe uma alternativa séria: apreciar uma bela paisagem sentado num banco.","Uma almofada fora de posição pode estragar o clima. Você restabelece a ordem com a seriedade de um arquiteto.","Tomar um ar, tudo bem, mas primeiro você quer saber se haverá onde sentar na volta.","Se alguém interrompe sua soneca, você abre um olho com a gravidade de um juiz interrompido em plena audiência.","Seu sofá tem uma zona de pouso perfeitamente calibrada. Os convidados a atravessam por conta e risco.","Você colocou sua manta favorita para lavar. O dia passa a operar em protocolo de 'conforto reduzido'.","Uma soneca inesperada traz felicidade. Se for interrompida, vira assunto de gravidade administrativa.","À noite, você monta o ambiente com luminária, xícara e três almofadas. A poltrona aguarda autorização do decorador."],"wisdom":["O que merece durar não precisa ter pressa para chegar.","Um bom plano é aquele que reserva um assento.","A perseverança é nobre; recusar outro restaurante há oito anos é um pouco menos.","Às vezes, a felicidade cabe num cobertor, principalmente se ninguém o pegar emprestado.","A persistência constrói pontes; de nada adianta se você se recusa a atravessar a que acabou de ficar pronta.","O tempo amadurece boas ideias. Não impede ninguém de abrir a janela para elas de vez em quando.","Diante de um prato esfriando, sua paciência perde a coroa imediatamente.","Nem tudo que é confortável precisa virar um móvel guardado para sempre.","A paciência sabe esperar a colheita, mas não planta por você.","Uma boa ideia duradoura merece raízes, não uma cerca em volta de cada uma.","Um passo lento na direção certa vale mais que um plano perfeito guardado na gaveta.","A regularidade é uma força. O calendário agradece quando você deixa uma casinha livre de vez em quando."],"roast":["Você guarda o cardápio de um restaurante por fidelidade, mesmo depois que o lugar trocou de dono três vezes.","Quando um aplicativo muda o botão principal de lugar, você pensa seriamente em enviar uma reclamação formal.","Sua cadeira favorita é tão conhecida que os convidados quase pedem licença para sentar.","A última fatia do bolo é um assunto diplomático delicado. Você prefere organizar uma votação e manter o poder de veto.","Diante de um travesseiro novo, você realiza testes rigorosos. O antigo aguarda o resultado com confiança.","Essa roupa confortável atravessou tantos domingos que praticamente faz parte da mobília.","Ao ouvir você explicar a rotina da manhã, parece que estamos conhecendo uma tradição protegida por um museu.","Se alguém propõe um atalho, você pergunta por que abandonar um caminho que sempre funcionou.","Você recusou três convites para experimentar um método novo. No quarto, propôs retomar o assunto em cinco anos.","No seu debate interior, todos votaram contra a mudança. Os argumentos favoráveis nem receberam convite.","Você assinou um acordo definitivo com um hábito. O contrato renova automaticamente e não prevê rescisão.","Alguém provou que você estava errado. Você sorriu: 'É uma perspectiva interessante, mas incorreta'."]},"piquant":{"career":["O software novo oferece três funções úteis. Você escreveu cinquenta páginas para salvar o velho botão 'imprimir'.","Você defende seu método com a devoção de um curador de museu. O programa mudou de versão, mas você não.","A mudança de lugar no escritório parece uma violação de tratado. Sua cadeira abriu uma embaixada.","Quando uma reunião propõe novidade, você exige três comprovantes e garantia de retorno ao sistema antigo.","Um procedimento que funciona é sagrado para você. Até seus defeitos ganham proteção de patrimônio histórico.","Por trás da sua calma profissional, uma placa invisível avisa « não mexam nos meus hábitos ». Os estagiários procuraram outra saída.","Atalhos despertam sua desconfiança: para que ganhar dez minutos quando se pode preservar uma tradição de quinze anos?","Seu escritório é território estável, até o biscoito deixado na mesa. Você demarcou uma fronteira em torno da caixa.","O software novo foi instalado. Você transformou o antigo atalho do teclado em patrimônio imaterial do departamento.","Você protegeu seu horário de almoço com barreiras temporais. Uma ligação urgente foi transferida para a ideia de amanhã.","Sua carreira avança em velocidade cuidadosamente homologada. As promoções têm tempo de ler todos os anexos.","O setor anuncia reestruturação. Você apresenta um dossiê sobre as vantagens da sala atual, datado da construção do prédio."],"love":["Seu romantismo se mede pelos jantares marcados no mesmo restaurante. A casa já cogita gravar suas iniciais no cardápio.","Você trata os hábitos a dois como monumentos tombados. Mudar o jantar em uma hora exige referendo.","Compartilhar parece um valor lindo até chegar a última garfada. Nesse momento, você descobre o direito à propriedade.","Quando sugerem um lugar novo, você passa o trajeto inteiro elogiando seu restaurante de sempre.","Você organizou um jantar surpresa: mesma mesa, mesmo menu, mesma sobremesa. A surpresa é a cor dos guardanapos.","Você oferece uma ternura admiravelmente constante. A última garfada, porém, é protegida por um tratado secreto.","Declarações carinhosas encantam você, mas não durante a seleção da última fatia da sobremesa.","Você é fiel aos pequenos rituais do casal. Até cadastrou a tradição de sexta-feira como evento histórico recorrente.","Você divide a vida, a agenda e os hábitos com prazer. Seu prato, porém, tem status de país independente.","Pesquisa fictícia: 98% de seus jantares românticos têm o mesmo cardápio. Os outros 2% correspondem a pratos em falta.","Você tornou a fidelidade ao jantar favorito uma prova de amor. A outra pessoa só queria provar novidades do menu.","Sua ideia de aventura a dois: mudar a ordem dos pratos sem perder o direito de escolher o restaurante."],"wellbeing":["Seu descanso tem endereço, cobertor e lugar reservado. A mobília registrou sua residência oficial.","Você defende a soneca como uma cúpula internacional. Toda interrupção exige requerimento em três vias.","O sofá conhece tanto seus hábitos que poderia substituí-lo numa reunião. Só se recusa a sair da sala.","Quando alguém sugere uma caminhada improvisada, você pergunta primeiro se os sapatos podem ficar no lugar.","Uma bebida quente traz conforto, a menos que alguém esteja usando sua xícara habitual. A outra xícara é barrada na fronteira.","Por trás do seu amor pelo conforto, uma organização militar protege a temperatura ideal do cobertor. O termostato obedece por precaução.","Domingos tranquilos são sua especialidade, desde que ninguém invente uma surpresa. O calendário está lacrado.","Seu exercício de flexibilidade consiste em trocar de almofada. Uma comissão ainda analisa o pedido.","Sua manta recebeu escritura de propriedade das suas noites. Os demais tecidos podem se candidatar, sem esperança.","Aviso oficial: a soneca é patrimônio protegido. Qualquer interrupção será analisada depois de outra soneca.","Você traçou um roteiro relaxante entre poltrona, chaleira e sofá. O trajeto é tão curto que tem metrô imaginário.","Sua almofada reserva tem outra almofada reserva. O conceito de imprevisto acabou de sair da sala."],"wisdom":["A constância é uma virtude. Transformar cada decisão antiga em monumento nacional já é menos prático.","Você não muda de opinião: permite que os outros se cansem esperando.","A persistência move montanhas. Desde que você aceite que a montanha talvez não esteja mais onde foi deixada.","Quando o mundo se move, você verifica primeiro se sua poltrona tem freios.","Um hábito não é uma lei da natureza. Você, porém, redigiu seu código civil.","Por trás da sua tranquilidade, um comitê de defesa protege a última fatia da torta.","O tempo recompensa esforços profundos. Mas nunca prometeu manter as condições iguais para sempre.","Avançar não é trair seus chinelos. Mesmo assim, você exige um documento registrado em cartório.","A perseverança é linda, exceto quando consiste em esperar o mundo voltar exatamente ao lugar anterior.","Dá para ser firme sem virar estátua em homenagem à primeira decisão.","O que dura merece atenção, não uma inauguração solene a cada aniversário.","Seu senso de continuidade é admirável. O futuro, porém, não assinou contrato para repetir o passado."],"roast":["Você rejeitou uma ideia nova antes que seu autor terminasse de respirar. A proposta foi embora com a primeira palavra intacta.","Você rejeita mudanças com tanta constância que uma etiqueta nova no mel vira crise de Estado.","O último pedaço de queijo não é comida: é um recurso estratégico sob vigilância.","Sugerem outra rota para evitar obras. Você prefere observar as obras: pelo menos conhece esse caminho.","Uma sugestão de novidade esbarra no seu olhar de porta blindada. Até a curiosidade dá meia-volta.","Por trás da sua calma lendária, um guarda vigia a posição exata do controle remoto.","Sua frase favorita é 'sempre fiz assim'. A novidade tentou mostrar documentos, mas foi barrada na entrada.","Você declarou que argumento algum mudaria sua posição. A cadeira, no entanto, tinha acabado de andar um centímetro.","Apresentam fatos novos. Você informa, com calma, que eles não foram convidados para a conclusão.","Sua opinião foi gravada no mármore antes de acabar a conversa. O escultor só tinha vindo tirar medidas.","Você defendeu um hábito ultrapassado com tanta convicção que o museu recusou a doação: difícil demais de mover.","Manual para fazer você mudar de ideia: primeiro, esperar. Segundo, reler o primeiro passo. O terceiro é segredo de Estado."]},"roastMy":["Touro, seu sofá não é mais um móvel: é uma administração territorial. Você tem lugar, cobertor e procedimento de acesso para visitantes. Alguém senta ali por engano. A comissão das almofadas decreta a expulsão imediata.","Sua teimosia parece uma porta trancada com uma segunda fechadura. Apresentam uma ideia prática e você exige provas, referências e três temporadas de testes. A ideia desiste. Você anuncia que o método atual provou mais uma vez sua eficácia.","Você adora coisas gostosas, sobretudo quando ninguém pede a última fatia. Vigia o prato tranquilamente e desloca discretamente a porção estratégica. Um amigo sugere dividir. Você descobre de repente os limites da cooperação internacional.","Você diz que está aberto a novidades. Aceita até mudar de restaurante, desde que encontre a mesma mesa, o mesmo cardápio e a mesma atmosfera. O nome diferente já parece uma aventura enorme. Seu prato pede medalha de coragem.","Seu conforto tem constituição e você é seu guardião supremo. Os chinelos esperam junto ao sofá, o cobertor está dobrado conforme o regulamento e o chá chega na hora. Um convidado abre a janela. Você convoca o conselho extraordinário dos tecidos.","Você consegue defender um hábito comum com a convicção de um advogado renomado. Alguém quer mover o controle remoto alguns centímetros e você explica toda a história do local. Dez minutos depois, a pessoa desiste. O controle agradece sua intervenção.","Você não se move devagar: respeita o ritmo oficial do conforto. Todos esperam na porta para sair e você ainda procura a almofada de viagem ideal. Lembram que é só uma caminhada. Você pergunta se haverá assentos.","Seu domingo perfeito não admite surpresas, a menos que venham por entrega. Sugerem uma atividade espontânea e você consulta o cobertor como um assessor político. O cobertor diz não. Você apresenta a decisão como consenso familiar.","Você é generoso até alguém se interessar pela sua porção. Distribui de bom grado conselhos, cobertores e indicações. Aí uma mão se aproxima dos seus biscoitos. O tratado de amizade é suspenso até segunda ordem.","Seu amor pela estabilidade faria você guardar uma poltrona velha mesmo que não combinasse mais com a decoração. Explica que ela tem história, alma e direito de permanência. Uma poltrona nova espera na porta. A antiga acaba de virar ministra da sala.","Você trata novidades como visitas que chegaram sem marcar hora. Um programa atualizado explica suas vantagens; você mostra o menu antigo com orgulho. A demonstração dura uma hora. Seu mouse continua na versão anterior.","Você entende o valor da regularidade e seus hábitos usam crachás de antiguidade. O almoço é no mesmo lugar, na mesma hora, na mesma ordem. Um dia o restaurante mudou as mesas de lugar. Você ainda conta isso como grande reforma.","Você divide tempo e afeto com generosidade até um garfo se aproximar da sua sobremesa. De repente, vira especialista em fronteiras internacionais. O doce é separado em zonas administrativas. O garfo estrangeiro tem a entrada negada.","Você sabe cuidar de si: luz suave, leitura escolhida, poltrona impecável. Mudar um objeto de lugar exige adaptação. Uma visita rearruma a sala para ajudar. Descobre que os móveis estão protegidos por um tratado de paz.","Admiram sua força tranquila e sua capacidade de seguir metas. O problema surge quando uma placa indica outro caminho melhor. Você examina a placa e permanece fiel à rota original. Chama isso de constância; o mapa chama de belo desvio."]},"gemini":{"classic":{"career":["Sua curiosidade permite conectar ideias que outras pessoas mantêm separadas. Reserve, porém, tempo para desenvolver as mais promissoras.","Quando surgem vários projetos, seu entusiasmo pode se dispersar. Defina uma prioridade antes de aceitar outra.","Uma conversa profissional pode alimentar sua criatividade. Anote decisões claras para facilitar os próximos passos.","A diversidade de tarefas estimula sua mente. Uma estrutura simples pode ajudar você a terminar o que começa.","Diante de um problema complexo, você explora espontaneamente vários ângulos. Depois, escolha uma solução e dê a ela uma chance real.","Sua habilidade para explicar as coisas ganha ainda mais valor quando você ouve atentamente as perguntas dos colegas.","Se uma nova informação contradiz sua primeira opinião, sua flexibilidade é uma vantagem. Explique também o motivo da mudança.","Multiplicar contatos amplia seus horizontes. Cultive algumas trocas profundas em vez de correr atrás de toda novidade."],"love":["Sua necessidade de conversar alimenta a cumplicidade. Acolha também os silêncios sem tentar preenchê-los imediatamente.","Quando alguém desperta sua curiosidade, você multiplica as perguntas. Deixe a conversa ser uma troca, não um interrogatório.","Uma relação dinâmica inspira você quando oferece espaço para descobrir. A constância também pode enriquecê-la.","A leveza do seu humor facilita a aproximação. Perceba quando a outra pessoa espera mais profundidade.","Diante de sentimentos contraditórios, um pouco de distância pode ajudar a separar uma curiosidade passageira de uma necessidade duradoura.","Seu gosto por novidades traz frescor aos vínculos. Não esqueça o valor dos pequenos rituais já construídos.","Se mudar de opinião, explique seu raciocínio em vez de deixar a outra pessoa adivinhar o que mudou.","Falar com sinceridade é natural para você. Ouvir sem preparar a resposta pode criar outro tipo de proximidade."],"wellbeing":["Sua mente sempre em movimento merece momentos de calma. Tente diminuir os estímulos durante uma pausa escolhida.","Quando muitas ideias se atropelam, escrever algumas linhas pode ajudar você a reencontrar um caminho.","Uma caminhada curta sem celular pode oferecer um espaço agradável para sua curiosidade.","A diversidade dos seus interesses estimula você. Reserve também um tempo para desfrutar de uma só atividade.","Diante de um dia cheio de conversas, reencontre um pouco de silêncio no seu ritmo.","Sua necessidade de descobrir coisas novas pode esperar por uma noite tranquila. Não é preciso explorar tudo imediatamente.","Se os pensamentos continuam a circular até tarde, uma rotina serena pode suavizar o fim do dia.","Fazer uma pausa longe das notificações ajuda a distinguir o que realmente interessa do que apenas distrai."],"wisdom":["Sua curiosidade ganha profundidade quando aceita permanecer.","Duas ideias opostas podem iluminar uma escolha, não substituí-la.","A palavra aproxima quando dá espaço para a resposta.","Explorar todos os caminhos não significa percorrê-los ao mesmo tempo.","Uma mente livre também sabe terminar o que escolheu.","Mudar de opinião pode ser uma força, desde que você saiba explicar por quê.","Cada novidade abre uma porta; a atenção permite habitar um cômodo.","Ouvir até o fim às vezes é a forma mais bonita de curiosidade."],"roast":["Sua curiosidade às vezes se estende tanto que os projetos mais importantes ainda esperam uma conclusão.","Quando você faz uma pergunta, muitas vezes já preparou três respostas antes de ouvir a que lhe dão.","Você muda de perspectiva com facilidade, mas pode deixar os outros sem saber qual é sua verdadeira posição.","A busca por novidades pode afastar você depressa demais daquilo que apenas começava a ficar interessante.","Diante do silêncio, você costuma acrescentar palavras onde bastaria um olhar.","Sua necessidade de comentar tudo pode cansar quem aprecia uma presença mais discreta.","Se várias possibilidades atraem você, adiar a escolha não as torna necessariamente melhores.","Iniciar mil conversas é natural para você; levar uma só até o fim às vezes exige esforço especial."]},"funny":{"career":["Seu navegador profissional tem dezessete abas abertas. Você garante saber para que serve cada uma, menos a que está tocando música.","Quando pedem uma ata da reunião, você entrega uma crônica fascinante, com personagens secundários e reviravoltas.","Um aplicativo novo encanta você por trinta minutos. Depois, descobre outro que promete exatamente a mesma coisa.","A pausa para o café serve principalmente para recolher as novidades do escritório. Sua xícara esfria, mas sua rede de contatos funciona.","Sua caixa de e-mails tem 463 mensagens não lidas. Você as dividiu em três categorias: urgente, fascinante e 'já volto'.","Seu relatório progride bem até um colega mostrar um aplicativo novo. Você abre a pasta 'só para comparar'.","Você gerencia cinco conversas profissionais ao mesmo tempo. O único esquecido é quem espera por você desde cedo na sala B.","Fazer várias tarefas ao mesmo tempo diverte você. Terminar aquela escondida sob as outras quinze é a verdadeira caça ao tesouro.","Sua caixa de entrada anuncia cem mensagens novas. Você diz 'perfeito' como se tivessem entregado uma caixa de chocolates.","Você participa de três videochamadas ao mesmo tempo. Numa delas, seu microfone acaba de parabenizar a equipe errada.","Você abriu uma pasta para organizar projetos. Ela se chama 'versão final final mesmo 4'.","Uma tarefa ocupa você, chega uma mensagem, um colega liga. No fim, você avançou bastante no relatório de uma quarta tarefa."],"love":["Você manda uma mensagem de paquera e outra para esclarecer a primeira. A terceira confirma que a primeira era romântica.","Quando perguntam onde jantar, você sugere três restaurantes, muda de ideia e descobre uma aula de cerâmica no caminho.","Uma conversa carinhosa pode desviar para vulcões, vizinhos e a melhor maneira de dobrar um lençol.","A surpresa agrada tanto você que às vezes muda os planos por conta própria e depois finge estar surpreso.","Diante de uma mensagem « estou com saudade », você começa a responder e acaba relatando os seis acontecimentos do seu dia.","Seu amor por conversar sobre tudo é encantador. A outra pessoa só aprendeu a encaixar « vou dormir » entre duas vírgulas.","Mal promete uma noite sem celular, um artigo fascinante surge como motivo perfeitamente « excepcional » para pegá-lo de novo.","Você aceitou dois convites para sair na mesma noite. A solução: sugerir uma caminhada que passe bem entre os dois endereços.","Você preparou quatro respostas para 'vamos nos ver?'. Envia a mais longa com opções coloridas de horário.","Seu flerte por mensagem funciona muito bem. Só falta explicar por que a conversa agora tem um índice.","Assim que sugerem um encontro, você já conhece três cafés. O problema é que estão em três bairros diferentes.","Você muda o programa romântico como quem troca de música. A outra pessoa pediu só uma pausa entre as faixas."],"wellbeing":["Seu cérebro abre uma nova janela mental assim que você fecha os olhos para descansar.","Quando sai para caminhar e esvaziar a cabeça, volta com doze ideias e o nome de um podcast.","Uma sessão de silêncio parece interessante, mas primeiro você gostaria de discutir seus benefícios com o grupo.","O relaxamento começa quando você larga o celular. Termina ao se perguntar o que está acontecendo em outro lugar.","Diante de uma pilha de livros, você começa quatro: sua maneira particular de respeitar cada autor.","Você liga um podcast para relaxar e acelera a reprodução. Agora até as vozes parecem tão apressadas quanto seus pensamentos.","Respirar sem pensar em nada parece simples na teoria. Sua mente já prepara uma palestra para provar o contrário.","Se oferecer a si mesmo uma noite tranquila, evite criar um grupo de mensagens para compartilhar a programação minuto a minuto.","Você tentou contemplar a paisagem em silêncio. Logo estava procurando um documentário sobre a formação das nuvens.","Uma caminhada tranquila é ótima, especialmente com dois podcasts e uma lista de assuntos para contar na volta.","Para espantar o tédio, você decidiu aprender algo calmo. Descobriu seis atividades e começou as seis.","Seu exercício de descanso é ouvir chuva. Você compara sete gravações para escolher a melhor chuva."],"wisdom":["Sua mente conhece mil caminhos; só um botão diz « concluir ».","Duas opiniões na mesma frase já formam uma mesa-redonda.","O silêncio não precisa receber legendas feitas por você.","Uma ideia nova às vezes pode esperar a antiga sair da caixa.","A curiosidade abre caminhos. Às vezes também esquece por que saiu de casa.","Mudar de opinião é permitido; avisar o resto do mundo continua elegante.","Contar tudo não é obrigatório, mesmo que você saiba os detalhes.","Ouvir é deixar uma ideia terminar a frase antes de apresentar três primas dela.","Uma resposta curta pode ser completa, ainda que você conheça a história dos antepassados dela.","O paradoxo fica mais claro quando você resiste a lhe dar um irmão gêmeo imediatamente.","Não é proibido fazer perguntas. Às vezes vale esperar uma resposta antes de fazer outras oito.","Não faltam assuntos no mundo. Ele só agradece quando uma frase chega ao ponto final."],"roast":["Você sabe tantas fofocas que o bairro poderia contratar sua newsletter semanal.","Quando diz « resumindo », seus amigos começam a procurar uma tomada para carregar o celular.","Sua lista de leitura contém artigos cujos títulos ainda fascinam você, embora já tenha esquecido o motivo.","A frase « não tenho nada para contar » dura menos, na sua boca, que um anúncio impossível de pular.","Diante da escolha de um filme, você defende uma comédia, depois um documentário e, por fim, uma série.","Seu áudio de dois minutos precisa de introdução, digressão e conclusão que anuncia um segundo áudio.","Assim que a festa termina, você já reformulou as melhores conversas para contá-las a outra pessoa.","Se alguém lhe dá a última palavra, você aproveita para começar um assunto totalmente novo.","Você ouviu uma confidência, prometeu segredo e passou a noite falando sobre 'aquela história que não posso contar'.","Você diz 'não quero espalhar fofoca' e em seguida oferece o mapa detalhado do bairro em questão.","Seu relato breve inclui a cena, o contexto, os antecedentes históricos e os bastidores do contexto.","Você narrou uma aventura com dois finais opostos. O público adorou; os protagonistas querem conferir o roteiro."]},"piquant":{"career":["Sua conversa transformou a reunião da equipe numa série de temporadas. A reunião exige resumo dos episódios anteriores.","Você apresentou três estratégias contraditórias na mesma reunião. O slide 'conclusão' acaba de pedir demissão.","Sua resposta a um e-mail ocupa doze rascunhos. A mensagem original dizia apenas 'recebido'.","Quando um colega diz « em duas palavras », você pergunta se parênteses contam. Ele já está fechando o computador.","Uma ideia nova fascina você até surgir a próxima. Os projetos abandonados fundaram um grupo de apoio administrativo.","Sua tela de trabalho parece um terminal internacional. Cada aba anuncia uma conexão, nenhuma sabe o destino final.","Você encaminhou seis mensagens a seis colegas em seis minutos. Uma sétima pessoa foi nomeada responsável por entender o assunto.","Seu talento para improvisar é notável: você muda a conclusão no meio da apresentação. O slide se recusa a acompanhar.","Últimas notícias: sua caixa de e-mails tem tantos rascunhos que abriram um endereço para responder às mensagens nunca enviadas.","Você distribuiu seis tarefas entre seis janelas. A única janela fechada foi a do arquivo essencial.","Sua videochamada tem quatro conversas paralelas. A pauta foi encaminhada para o setor de achados e perdidos.","Relatório fictício: 27 mensagens, 14 cobranças, 9 ideias novas. Progresso do projeto principal: uma bela cor de título."],"love":["Seu charme fala tão rápido que o silêncio nunca consegue se apresentar. Até um sorriso recebe comentário em áudio.","Seu charme muda de direção no meio do encontro. A reserva para dois termina com três restaurantes candidatos e nenhuma decisão.","Sua primeira mensagem era carinhosa. As cinco seguintes traziam alternativas, um parêntese e uma enquete sobre emojis.","Quando perguntam o que você realmente pensa, você oferece duas respostas opostas com o mesmo sorriso. O júri exige um árbitro.","Você escolheu um programa romântico e mudou de ideia antes de calçar os sapatos. A agenda guarda o primeiro convite como documento histórico.","Sua declaração começa com 'preciso lhe contar uma coisa'. Termina em 'e aí lembrei daquele café de terça-feira'.","Sua mensagem de boa-noite inclui um pós-escrito e outro. O celular acaba em plantão sentimental.","No meio de um passeio a dois, você sugere mudar de destino. A outra pessoa descobre que o encontro tem roteiro interativo.","Você criou uma enquete para escolher o local do encontro. Mudou as opções depois do primeiro voto; a democracia romântica pensa em desistir.","Sua mensagem carinhosa vem com duas correções e três links extras. O afeto acaba de ganhar atendimento pós-venda.","Você marcou dois encontros para o mesmo horário e alegou que os convites se complementavam. A agenda rejeitou a teoria.","Seu charme funciona como cruzamento de cinco vias. O encontro era simples; agora precisa de legenda e setas."],"wellbeing":["Você colocou um podcast relaxante em velocidade dupla. Nesse ritmo, a voz serena parece narrar um leilão.","Você resolve não fazer nada e começa a pesquisar os melhores métodos para não fazer nada. O repouso fecha o navegador.","O silêncio atrai você por oito segundos. Depois, você pergunta se ele tem alguma novidade interessante.","Quando sai para caminhar, três desvios e duas conversas improvisadas transformam o bairro numa conferência ambulante.","Uma pausa sem estímulos parece suspeita. Você consulta o cardápio de pensamentos disponíveis.","Por trás da sua energia social, um cobertor espera pacientemente. Ele desistiu de reservar horário.","As playlists tranquilas não sobrevivem à sua curiosidade. Depois de duas músicas, você investiga a história do piano.","Essa noite calma começou com um livro. Continua com sete vídeos sobre fabricação de marcadores de página.","Você instalou um aplicativo de respiração tranquila. Ele não sobreviveu à sua vontade de explorar todas as opções.","Previsão do tempo interior: agitação constante, com breves momentos de paz durante anúncios que não podem ser acelerados.","Você coloca um vídeo relaxante em velocidade tripla. A serenidade atravessa a sala correndo.","O silêncio teve sua companhia por um minuto. Depois você ligou um podcast para avaliar o desempenho dele."],"wisdom":["Sua mente tem tantas opiniões que até a votação de braço levantado leva uma semana.","Você não muda de assunto: funda outra conversa sem encerrar a anterior.","O silêncio às vezes é uma resposta. Você pediu que ele elaborasse melhor.","Quando uma ideia passa pela sua cabeça, já cruza outras três vindo na direção contrária.","Você perguntou se uma resposta podia conter o seu contrário. Respondeu sim, depois não, depois 'depende'.","Por trás de cada frase curta, você prepara um anexo. O anexo tem sua própria introdução.","Escolher fica mais simples quando paramos de convocar todos os argumentos. O quórum nunca é atingido.","Conhecer todo mundo é útil. Você também catalogou as histórias dessas pessoas por episódio.","Uma pergunta pode ser profunda. Quinze empilhadas são mais parecidas com uma escada sem patamar.","Sua lógica adora bifurcações. Às vezes visita os dois becos sem saída para comparar a decoração.","Nem toda contradição se resolve organizando uma conferência em que você interpreta todos os palestrantes.","Considerar todas as hipóteses é talento. Decidir que todas estão certas ao mesmo tempo é circo filosófico."],"roast":["Sua conversa começou com « vou ser breve ». O calendário trocou de mês durante a introdução.","Você segura duas opiniões contraditórias como dois cães na coleira. Os cães querem seguir direções opostas.","Você contou a mesma fofoca em quatro versões. As testemunhas já duvidam de ter participado do mesmo acontecimento.","Quando falta detalhe numa história, você acrescenta. As testemunhas já não reconhecem o próprio relato.","Você afirmou 'sou perfeitamente coerente' e defendeu o oposto para testar a atenção. Ninguém arriscou aplaudir.","Por trás da sua curiosidade, o botão « próximo » funciona melhor que o « concluir ».","As fofocas passam pela sua boca na velocidade de um trem expresso. A confidencialidade ainda espera na plataforma.","Sua atenção assinou todos os pacotes de distração. O fornecedor se recusa a indicar qual é o serviço principal.","Sua pequena fofoca tinha duas testemunhas e um começo modesto. Você inventou uma trama paralela; o bairro já prepara a segunda temporada.","Alguém confia a você um detalhe sigiloso. Você apresenta um estudo de caso 'totalmente anônimo', exceto pelo endereço.","Você mudou a versão três vezes durante o relato do mesmo evento. O acontecimento original se recusa a depor.","Seu 'só entre nós' já fez quatro paradas. O sigilo definitivamente viaja em outro trem."]},"roastMy":["Gêmeos, você não tem duas opiniões: dirige uma coalizão instável de ideias. Cada uma exige um ministério, derruba a anterior e anuncia reforma imediata. Você chama isso de « pensar em voz alta ». Seu cérebro pede um regimento interno.","Você conta uma história pequena com a ambição de uma saga internacional. Há prólogo, quatro personagens secundários e uma cena que exige flashback. Seus amigos esqueceram a pergunta inicial. Você anuncia que falta um detalhe essencial.","Seu navegador não tem abas: abriga uma cidade inteira. Cada janela promete uma descoberta fascinante e se recusa a sair. Você procura a página aberta de manhã. Até o buscador pede um mapa do bairro.","Você se entedia com eficiência admirável. Uma atividade empolga, depois outra, depois outra, todas ao mesmo tempo. O dia termina com vinte começos e uma lista de ideias para amanhã. Os finais dos projetos criaram uma associação de defesa.","Sua curiosidade não tem fronteiras nem botão de desligar. Pergunta como foi o fim de semana de alguém e, três minutos depois, explora a história do bairro dessa pessoa. Ela só queria falar do cinema. Sua entrevista aguarda aprovação do setor de documentação.","Você fala tão facilmente que os outros acabam balançando a cabeça para conseguir sua vez. Você interpreta isso como convite para continuar. O grupo inventa bandeirinhas para pedir a palavra. Você propõe imediatamente um debate sobre a cor delas.","Você defende uma ideia com convicção admirável e adota a contrária antes de o café acabar. Ao apontarem a mudança, explica que as duas posições se complementam. O café esfria. O dicionário procura uma definição para « concordância ».","Seu talento para fofoca deixaria um jornal local com inveja. Você sabe quem trocou a planta, por que um vizinho moveu a cadeira e a hora em que dois colegas riram. Jura não revelar nada. Começa dizendo « eu nem deveria contar ».","Você quer descobrir o mundo inteiro numa tarde. Começa uma receita, lê sobre um país distante e assiste a um tutorial de conserto de gaveta. O jantar se aproxima, a gaveta está aberta e a viagem já está reservada na imaginação. Sua agenda pede tradutor.","Sua mente pula tão rápido entre assuntos que as conversas usam capacete imaginário. Uma pergunta prática vira debate filosófico, depois lembrança de viagem, depois comparação de biscoitos. Você termina com « enfim ». Ninguém ousa pedir um resumo.","Sua mente parece um festival em que todas as palestras começam juntas. Você assiste a três, intervém na quarta e anota a quinta. Ninguém sabe qual era o tema inicial. Você chama isso de noite enriquecedora.","Você transforma um encontro simples num mapa de transporte. Sugere café, exposição e desvio até uma padaria vista na internet. A outra pessoa tenta acompanhar. O encontro agora precisa de guia turístico.","Você tem um dom para transformar fatos comuns em grandes histórias. Uma campainha quebrada vira novela, com personagens, motivos e reviravoltas. Seus amigos acompanham tudo. A campainha continua quebrada.","Seu descanso deveria permitir respirar. Você escolheu música suave, comparou cinco playlists e achou uma entrevista fascinante sobre instrumentos. Duas horas depois, a sala está quieta. Sua mente conduz uma mesa-redonda sobre o silêncio.","Você tem duas opiniões convincentes sobre quase tudo, às vezes na mesma frase. Quando pedem uma decisão, explica a importância das nuances. Acrescenta um terceiro ponto de vista para equilibrar. O júri percebe que você também é o júri."]},"cancer":{"classic":{"career":["Sua sensibilidade às necessidades da equipe ajuda você a perceber tensões discretas. Cuidado para não carregar sozinho o clima do grupo.","Quando um colega passa por um dia difícil, sua escuta pode fazer diferença. Preserve também sua própria disponibilidade.","Um comentário profissional pode afetar você por mais tempo que o esperado. Recoloque-o no contexto antes de tirar conclusões.","A lembrança de experiências passadas ilumina suas escolhas. Use-a sem deixar que uma antiga decepção impeça novas iniciativas.","Diante de uma mudança no ambiente, sua intuição capta sinais rapidamente. Confira suas impressões por meio de uma conversa direta.","Seu desejo de proteger os outros fortalece a confiança. Deixe também que cada um experimente e tome as próprias decisões.","Se um projeto coletivo é importante para você, seu compromisso tem valor. Expresse suas expectativas em vez de esperar que sejam adivinhadas.","Um ambiente acolhedor ajuda você a trabalhar com tranquilidade. Aprenda também a estabelecer limites quando pedirem atenção demais."],"love":["Seu apego profundo se manifesta em inúmeras demonstrações de carinho. Deixe espaço para as necessidades que a outra pessoa expressa.","Quando uma lembrança feliz volta, compartilhe-a como presente, não como medida para avaliar o presente.","Uma palavra infeliz pode ecoar por bastante tempo. Pedir esclarecimento às vezes é melhor que se afastar em silêncio.","A família e as pessoas próximas têm um lugar importante no seu mundo. Permita que cada um encontre o próprio espaço.","Diante de um afastamento passageiro, sua imaginação pode preencher as lacunas. Uma pergunta simples costuma esclarecer as coisas.","Sua necessidade de acolhimento merece ser dita claramente. É mais fácil oferecer carinho quando ninguém precisa adivinhá-lo.","Se você se sentir incompreendido, explique o que o afetou antes de se fechar na decepção.","Cuidar de alguém é uma bela maneira de amar. Aceite também receber cuidados sem precisar organizar tudo."],"wellbeing":["Sua sensibilidade ao ambiente torna especialmente preciosas as pausas num lugar familiar.","Quando as emoções se acumulam, um momento de calma pode ajudar você a acolhê-las sem se deixar dominar.","Uma caminhada perto de um lugar querido pode trazer uma agradável sensação de continuidade.","Às vezes, a nostalgia acompanha você com delicadeza. Aproveite as lembranças sem perder os prazeres do presente.","Diante das solicitações de quem você ama, permita-se guardar um tempo só para você.","Seu desejo de tornar a casa acolhedora pode virar um ritual reconfortante, desde que não seja uma obrigação.","Se o dia exigiu muito de você, reencontre um ritmo tranquilo e o conforto de uma noite simples.","Perguntar como os outros estão vem naturalmente. Lembre-se de perguntar também o que você deseja hoje."],"wisdom":["Sua delicadeza fica mais forte quando sabe dizer não.","O passado pode aquecer o coração sem dirigir cada escolha.","Uma emoção merece ser ouvida, não necessariamente decidir sozinha.","Proteger os outros não exige carregar os silêncios deles.","A confiança cresce quando as expectativas são ditas com clareza.","Um lar acolhedor também se constrói dando espaço a cada um.","Ouvir a intuição é valioso; confrontá-la com os fatos a torna mais justa.","Cuidar de si não diminui o amor dedicado aos outros."],"roast":["Sua memória afetiva às vezes transforma um detalhe antigo em referência permanente para julgar o presente.","Quando uma palavra machuca você, seu silêncio deixa os outros tentando adivinhar o que precisaria ser explicado.","Você cuida tanto dos próximos que às vezes esquece de perguntar se eles realmente querem ajuda.","A nostalgia pode embelezar suas lembranças a ponto de fazer o novo parecer menos acolhedor do que é.","Diante de uma distância comum, você às vezes procura um significado que não existe.","Sua necessidade de proteger o próprio universo pode gerar cautela diante de mudanças que não ameaçam seus vínculos.","Ao perceber uma tensão, você pode acabar assumindo uma responsabilidade emocional que não é sua.","Consolar os outros com delicadeza é natural; dizer do que você precisa pode exigir mais esforço."]},"funny":{"career":["Assim que um colega suspira, você aparece com uma agenda mais leve e promete revisar o relatório dele. Ele só queria trocar de cadeira.","Quando a chefia escreve « obrigado » sem ponto de exclamação, você passa a manhã analisando o entusiasmo da mensagem.","Uma foto antiga da equipe basta para você começar uma retrospectiva de despedidas, aniversários e festas de boas-vindas.","A cafeteira quebrou? Sua principal preocupação é o moral do grupo, e você organiza um núcleo de apoio na cozinha.","Diante de um estagiário novo, você prepara uma recepção tão cuidadosa que ele já sabe onde ficam os biscoitos e os lenços.","Você guarda todos os e-mails antigos da equipe 'por via das dúvidas'. Sua caixa de entrada virou uma seguradora de conversas.","Se alguém diz « tudo bem », você também escuta o suspiro escondido entre as palavras e já oferece uma conversa séria.","Cuidar do clima no trabalho combina com você. Até a planta do setor tem suas folhas novas comemoradas pela equipe.","Uma colega diz que o dia será puxado. Você já montou um rodízio para que ela não carregue os processos sozinha.","Sua caixa de e-mails guarda as mensagens de boas-vindas da equipe de cinco anos atrás. Você chama isso de 'manter o contexto'.","Um estagiário procura a sala de reunião. Você entrega mapa, nomes dos colegas e uma mensagem de incentivo.","Você distribuiu lembretes gentis para a equipe. O quadro de tarefas parece uma reunião de família bem organizada."],"love":["Seu coração arquiva lembranças com a organização de uma biblioteca nacional. O ingresso do primeiro cinema provavelmente tem uma capa protetora.","Quando chega uma mensagem sem emoji, você se pergunta se o carinho foi temporariamente suspenso para manutenção.","Uma noite romântica perfeita é rever o filme do primeiro encontro e contar tudo o que a outra pessoa esqueceu.","Sua ternura também aparece na pergunta « você comeu o suficiente? », repetida com uma convicção admirável.","Diante de um « até mais tarde », você gostaria de conhecer a definição oficial de « mais tarde » e seu nível de calor afetivo.","Esse presente feito à mão emociona tanto você que até o papel de embrulho vai para a caixa de recordações. Ele também tinha história.","Basta tocar uma música conhecida para você contar o lugar, o tempo e a emoção da primeira vez em que a ouviu.","Se alguém esquece uma data simbólica, você não diz nada. Seus olhos, porém, poderiam apresentar uma conferência inteira.","Você lembra a cor do guardanapo no primeiro encontro. A outra pessoa lembra principalmente das risadas.","Uma música antiga traz de volta o início de uma história. Você relata cardápio, previsão do tempo e trajeto de ônibus com rigor de arquivista.","Você guarda o papel de um presente carinhoso porque a fita era bonita. O presente não recebeu tanta documentação.","Você propôs recriar o primeiro jantar exatamente. O restaurante mudou de chef, mas você levou uma cópia do cardápio original."],"wellbeing":["Sua ideia de aconchego cabe num cobertor macio, bebida quente e filme que você já sabe de cor.","Você preparou uma noite tranquila em casa: luz baixa, bebida quente e poltrona reservada. As condições de hospedagem são impecáveis.","Uma caminhada diante da escola antiga inicia imediatamente um documentário interior com música melancólica.","Relaxar está ao alcance da mão, exceto quando você começa a se preocupar se todo mundo está tão relaxado quanto você.","Diante de um dia corrido, você sugere ficar em casa. O sofá recebe você como um parente de volta de uma longa viagem.","Esse pequeno álbum deveria ocupar cinco minutos. Duas horas depois, uma foto de bolo ainda emociona você.","Tirar um tempo para si parece estranho: você procura alguém para quem preparar um lanche.","Se assistir a uma animação, deixe um lenço por perto. Até um brinquedo perdido reencontrando o dono pode emocionar você.","Sua cozinha tem uma receita especial para dias corridos. Você a prepara como ritual de boas-vindas ao lar.","Seu descanso noturno começa escolhendo a manta. Essa etapa tem três rodadas classificatórias.","Você encontrou a iluminação perfeita da sala. Desde então, mover a luminária um dedo é experiência ousada.","Sua definição de passeio tranquilo: fazer compras para um jantar gostoso e voltar logo para aproveitar a casa."],"wisdom":["Sua intuição às vezes ouve uma tragédia num simples « tá bom ».","Raízes ajudam a ficar em pé, mas não proíbem o crescimento de novos galhos.","Carinho não exige preparar lanche para cada emoção.","O silêncio de alguém próximo não é necessariamente o primeiro episódio de uma tragédia.","Um refúgio protege melhor quando a porta também abre por dentro.","Proteger alguém querido não significa escolher o tamanho das asas dessa pessoa.","O amor também aparece quando você deixa alguém escolher a própria sopa.","Cuidar dos outros às vezes começa por deixá-los terminar a frase.","Uma raiz forte não escolhe por conta das folhas a direção do sol.","Dá para preservar um vínculo precioso sem controlar a agenda particular da outra pessoa.","Cuidar de um jardim também é permitir que as plantas inventem suas próprias formas.","A memória ilumina o caminho. Ela não deveria dirigir enquanto você fica olhando para trás."],"roast":["Você guardou um cartão de aniversário tão antigo que o envelope conhece sua história melhor que seus amigos.","Quando alguém responde « ok », seu cérebro já prepara três cenários sobre o que pode ter acontecido.","Você interpretou um simples 'ok' como mensagem cifrada. Três pessoas próximas já receberam suas hipóteses completas.","A música de um desenho antigo basta para anunciar que o dia será emocionante.","Um anúncio de lápis de cor arrancou uma lágrima sua. O protagonista enfim encontrou sua cor preferida.","Esse áudio de alguém querido é tão precioso que você hesita em apagá-lo, mesmo quando diz apenas « estou chegando ».","A cada reunião de família, você volta com fotos novas e uma missão pessoal: conferir se todos estão felizes.","Se alguém diz « nada de especial », você se convence de que há uma emoção escondida e abre a investigação.","Você interpretou um 'até logo' vago como declaração formal de incerteza. Seu silêncio se vestiu para a ocasião.","Um anúncio mostra um cachorro reencontrando o brinquedo. Você enxuga uma lágrima enquanto ele já brinca com outro.","Você garante que não está ofendido. O tom do seu 'claro' gelou toda a conversa do grupo.","Esqueceram você num pequeno convite coletivo. O rosto segue amável, mas suas reticências têm ar de cerimônia."]},"piquant":{"career":["Sua sensibilidade encontrou um sentido oculto num e-mail de três palavras. O remetente só queria confirmar o horário.","Você salvou seis versões antigas da ata. O servidor abriga agora uma reserva estratégica de pontos e vírgulas.","Qualquer mudança na equipe vira uma cerimônia de despedida. A cadeira transferida recebe um álbum de fotos.","Quando alguém esquece de cumprimentar você, sua mente cria uma comissão sobre respeito. A pessoa estava ao telefone.","Uma observação neutra acompanha você até a noite. Ela ganhou lugar oficial no seu diário de emoções.","Seu apoio aos colegas lembra um atendimento com assinatura ilimitada. Um simples 'obrigado' vira encerramento oficial do chamado.","Os hábitos do escritório são queridos para você. No dia em que mudam a planta de lugar, você cogita uma homenagem solene.","Sua memória profissional guarda histórias do prédio antigo. Até a impressora tinha um papel comovente.","Você monitora o ânimo dos colegas como meteorologista emocional. Alguém boceja: boletim extraordinário de apoio.","Seus e-mails antigos estão em seis pastas de segurança. Se houver pane, você reconstrói até o nascimento das vírgulas.","Sua bondade no escritório fundou um serviço informal de proteção aos colegas. As pausas têm formulário de gentileza.","Uma pessoa nova diz 'eu me viro'. Você entrega um kit de boas-vindas tão completo que inclui mapa do corredor."],"love":["Sua nostalgia guarda ingressos de cinema como documentos de Estado. A gaveta das lembranças pede ampliação.","Você interpreta um « tá bom » sem emoji como comunicado diplomático gelado. O celular desconhece a crise.","Qualquer lembrança carinhosa vira exposição permanente na sua cabeça. Os visitantes não podem tocar.","Quando alguém esquece uma data pequena, você diz não ter nada a reclamar. O silêncio acabou de enviar quatorze notificações.","Você guardou o recibo do primeiro restaurante a dois. Hoje ele tem mais anotações que um manuscrito histórico.","Por trás dos seus gestos atenciosos, uma central de vigilância verifica se o carinho foi devidamente reconhecido. O livro de registros está aberto.","As conversas antigas continuam no seu celular por afeto, você diz. O arquivista interior prepara uma classificação por década.","Esse coração oferece abrigo com prazer, mas se ofende quando ninguém nota a decoração emocional da entrada.","Seu primeiro encontro ocupa uma coleção digna de visita guiada. Até o guardanapo de papel ganhou ficha técnica.","Você guardou uma foto tremida de um jantar a dois. Diz que ela captura o clima; o fotógrafo só identifica um prato.","Suas conversas antigas têm títulos sentimentais. O celular acha que administra uma biblioteca romântica.","Você encontrou o ingresso de um passeio inesquecível e preparou uma reconstituição. A outra pessoa só havia aceitado um café."],"wellbeing":["Sua ideia de descanso é rever um filme antigo e sentir tudo exatamente como da primeira vez. Os créditos já sabem seu nome.","Sua sala foi preparada para acolher qualquer humor passageiro. Só falta um balcão de check-in para os cobertores.","O sofá entende você tão bem que é consultado antes de aceitar convites. Ele sempre vota a favor do cobertor.","Você preparou uma refeição reconfortante com a solenidade de uma cerimônia. A sopa ganhou discurso antes de ser servida.","Um dia tranquilo em casa vira peregrinação por fotos, caixas e xícaras sentimentais. A poeira assina o livro de visitas.","Por trás do desejo de aconchego, uma fortaleza de almofadas protege cada suspiro. As visitas passam por controle afetivo.","Você gosta de caminhar até um banco lembrar uma conversa de antigamente. O banco vira protagonista de uma saga.","Esse relaxamento deveria durar uma hora. Você passou quarenta minutos procurando o cobertor « que tem uma história ».","Sua noite aconchegante exige quatro mantas, bebida quente e controle de correntes de ar. A sala parece uma base polar.","O forno espalha um cheiro bom e você declara a casa oficialmente reconciliada com o mundo. O timer aplaude por educação.","Sua poltrona favorita tem luminária, xícara e manta de plantão. A cerimônia de instalação dura mais que o filme.","Avaliação da própria sala: 'Ambiente excelente, mas a manta principal não aceita sair da residência'. Cinco estrelas."],"wisdom":["Sua nostalgia pediu verba para ampliar o museu dos domingos passados. O presente espera lá fora.","As raízes alimentam o que cresce. Você às vezes as colocou no comando de todo o jardim.","Proteger seu mundo não exige instalar um controle de identidade diante de cada experiência nova.","Quando alguém diz « nada », você abre uma investigação emocional em quatro capítulos.","Uma lágrima diante de uma animação não exige entrevista coletiva. Você já prepara o dossiê.","Por trás da sua ternura, uma guardiã fiscaliza quem esqueceu de dizer « obrigado » na hora certa.","Sua memória é uma biblioteca admirável. Só ganharia deixando a sala de leitura aberta para o presente.","Cuidar dos outros não obriga você a tricotar um cronograma afetivo para cada um.","Você defende suas raízes com convicção. Mas elas não precisam de segurança particular a cada folha nova.","O apego ao passado dá profundidade. Transformá-lo no único mapa do futuro complica um pouco a navegação.","Seu cuidado é precioso, exceto quando ergue uma cerca ao redor de quem só veio cumprimentar.","Uma memória firme é bússola. Você às vezes a promoveu a ministra permanente de todos os caminhos futuros."],"roast":["Você ficou de cara fechada porque alguém respondeu 'tudo bem' num tom neutro demais. O ponto final é o principal suspeito.","Você faz bico com tanta sutileza que o bairro inteiro precisa adivinhar o motivo. A prefeitura recusa a investigação.","O último desenho animado emocionou você porque um objeto reencontrou seu dono. O objeto pediu discrição.","Um anúncio de reencontro de família emocionou você. Depois você acusou a torradeira de não compartilhar o momento.","Uma visita ao café antigo vira cerimônia histórica. O atendente só queria anotar seu pedido.","Por trás dos seus cuidados adoráveis, uma ficha invisível verifica se todos reconheceram seu esforço. Falta o carimbo.","Uma brincadeira inocente incomodou você. Três horas depois, ganhou dossiê, cronologia e duas testemunhas.","Seu silêncio ressentido deveria passar despercebido. Você apenas publicou a programação detalhada dos silêncios previstos.","Seu 'está tudo bem' vem com um silêncio tão ensaiado que merecia créditos de abertura.","Você analisou a pontuação de uma mensagem banal como detetive de romance policial. O culpado era uma tecla.","Um comercial de reencontro emocionou você. Depois acusou o diretor de surpreendê-lo com lenços imaginários.","Uma brincadeira leve desagrada você, que responde 'sem problema'. O grupo recebe um calendário de pedidos de desculpas possíveis."]},"roastMy":["Câncer, você não guarda lembranças: dirige um museu particular das emoções comuns. Um ingresso amassado, uma fita e uma lista velha de compras têm suas próprias legendas. Você explica a importância deles durante vinte minutos. A gaveta acaba de inaugurar uma bilheteria.","Você faz bico como um serviço diplomático que rompeu negociações sem explicar o motivo. Perguntam se está tudo bem e você responde « perfeitamente ». Seu silêncio então redige três comunicados. As almofadas atuam como embaixadoras da paz.","Você se emociona facilmente com animações, principalmente quando dois personagens se reencontram depois da separação. Já conhece a cena e mesmo assim prepara os lenços. Um amigo pergunta por que está vendo de novo. Você responde « pelo roteiro », e os créditos suspiram.","Seu celular tem capturas de tela carinhosas suficientes para encher uma biblioteca. Você guarda mensagens banais porque foram enviadas num dia importante. Alguém propõe fazer uma limpeza. O comitê dos arquivos declara a sugestão inadmissível.","Você cuida dos próximos com a generosidade de uma portaria aberta dia e noite. Prepara o cobertor, a bebida e o bilhete de incentivo. Ninguém repara na dobra perfeita do guardanapo. Seu departamento de gratidão apresenta reclamação.","Seu amor pelo lar vai muito além da decoração. Cada almofada tem lembrança, cada xícara tem história e cada canto do sofá tem valor sentimental. Um convidado propõe mover uma luminária. Você pede respeito ao patrimônio cultural da sala.","Você se lembra de tudo, especialmente das frases que os outros esqueceram. Uma brincadeira inofensiva de um almoço antigo volta com data e cardápio. Quem falou nem sabe do que se trata. Sua memória apresenta a ata.","Você adora noites tranquilas e gente querida em volta da mesa. Tudo é acolhedor até alguém avisar que precisa sair mais cedo. Você sorri e contempla a cadeira vazia como uma cena de cinema. A cadeira pede que desliguem a música dramática.","Sua intuição emocional detecta mudanças de humor até na pontuação. Um « obrigado » sem exclamação desencadeia uma busca por motivos. Você relê três semanas de conversa. A pessoa estava só com pouca bateria.","Você ama tanto o passado que até as latas velhas de biscoito têm direito de residência. Explica que cada uma lembra um momento especial. Não sobra espaço para os biscoitos novos. A cozinha lança um plano de urbanismo sentimental.","Sua memória afetiva reconstrói o primeiro jantar só com um cheiro vindo da cozinha. O prato volta à mesa junto com a narrativa completa. Todos escutam com carinho. O jantar de hoje espera sua vez na história.","No trabalho você protege a equipe como um faroleiro. Um colega muda de cadeira e você verifica se está tudo bem. Ele só queria ficar perto da janela. Ainda assim, você prepara uma visitinha de boas-vindas.","Sua casa é uma comissão de recepção do conforto. Você escolheu a luz, ajeitou almofadas e achou a receita ideal. Uma visita sugere sair para tomar ar. A cozinha apresenta de repente o cardápio de amanhã.","Sua sensibilidade transforma um comentário pequeno em novela silenciosa. Você diz que já superou, mas organiza as frases na ordem em que foram ditas. No dia seguinte, tudo parece tranquilo. Sua memória conserva as legendas.","Você ri de um anúncio e se emociona com o final na mesma intensidade. Depois reconta a cena a alguém, acrescentando os detalhes mais ternos. A pessoa acha que perdeu um filme grandioso. Era propaganda de caixas organizadoras."]},"leo":{"classic":{"career":["Sua vontade de brilhar pode ser uma força quando também dá visibilidade ao trabalho coletivo.","Você gosta de iniciativas que chamam atenção; reconhecer sinceramente as contribuições discretas fortalecerá sua influência.","A confiança que você transmite cria espaço para apresentar suas ideias com simplicidade.","Quando sua criatividade se expressa sem buscar aprovação imediata, ela ganha profundidade.","Um papel de destaque atrai você naturalmente; valorize também o que se constrói nos bastidores.","Por trás da sua segurança existe um compromisso verdadeiro, que merece aparecer nas atitudes.","Sua generosidade profissional pode dar ânimo a uma equipe que precisa de impulso.","A energia dedicada aos seus projetos merece uma direção clara, não reconhecimento constante."],"love":["Seu calor natural dá uma presença especial às conversas quando você escuta tanto quanto compartilha.","Você aprecia demonstrações de carinho; oferecê-las sem esperar retorno alimenta a proximidade.","A vontade de ser reconhecido nos seus vínculos ganha equilíbrio com a curiosidade pela outra pessoa.","Quando deixa de lado a necessidade de impressionar, seu carinho aparece com mais delicadeza.","Uma ternura generosa se revela nos gestos simples, longe das grandes declarações.","Por trás do seu orgulho, uma sinceridade profunda às vezes procura palavras mais discretas.","Os elogios emocionam você, mas conversas autênticas podem trazer uma alegria mais duradoura.","Seu jeito de amar ganha todo o valor quando cada pessoa tem seu espaço na relação."],"wellbeing":["Sua energia expansiva merece momentos em que você não precisa provar nada.","Você também recupera as forças na tranquilidade, longe dos olhares dos outros.","O prazer de criar apenas para si pode ser uma bela forma de desacelerar.","Quando sua agenda coloca você no centro de tudo, uma pausa silenciosa ajuda a recuperar o equilíbrio.","Uma caminhada sem objetivo oferece à sua mente um espaço sem desempenho a demonstrar.","Por trás do seu entusiasmo, a necessidade de descanso também tem legitimidade.","Momentos com pessoas queridas podem fazer bem sem que você precise animar a reunião.","Sua alegria de viver cresce quando também é acompanhada de momentos calmos, escolhidos livremente."],"wisdom":["Sua luz fica mais forte quando permite que os outros também brilhem.","Você não precisa de aplausos para ter valor.","A coragem de ser simples revela uma grandeza mais duradoura.","Quando o orgulho aprende a ouvir, transforma-se em confiança.","Uma presença sincera ilumina mais do que uma demonstração.","Por trás de toda conquista visível existe fidelidade aos pequenos gestos.","Os impulsos mais bonitos nem sempre precisam de palco.","Brilhar também significa saber dividir o espaço."],"roast":["Sua vontade de comandar pode ocupar tanto espaço que os outros mal conseguem terminar uma frase.","Você gosta de ser notado; o silêncio ao seu redor não significa necessariamente desaprovação.","A necessidade de receber elogios às vezes esconde aquilo de que você realmente se orgulha.","Quando toda conversa vira oportunidade de convencer, a espontaneidade desaparece.","Uma entrada triunfal não substitui uma presença atenciosa.","Por trás da sua generosidade, observe se a vontade de fazer o bem não está sempre procurando plateia.","Os olhares não contam tudo sobre a qualidade das suas relações.","Seu carisma não perde nada quando você abre mão da última palavra."]},"funny":{"career":["Seu escritório parece um palco: até arquivar um documento merece mais uma rodada de aplausos.","Você apresenta uma ideia na reunião com a segurança de quem anuncia uma descoberta histórica. É só um novo nome de arquivo.","O colega que elogia você vira imediatamente sua pessoa preferida no setor. O ranking muda a cada hora.","Quando pedem um voluntário, sua mão se levanta antes de terminarem a pergunta. Depois exige um microfone.","Uma assinatura simples num documento assume ares de cerimônia oficial.","Por trás da tela, você ensaia sua fala como se a diretoria fosse um júri de programa de televisão.","As vitórias coletivas deixam você tão feliz que já sugere uma foto de grupo, com você no meio.","Seu cartão de visita poderia dizer « responsável pelos momentos memoráveis ». Você já ocupa o cargo informalmente.","Comunicado: suas apresentações terão créditos finais. A planilha de Excel não sabia que tinha carreira artística.","Você parabenizou a equipe depois da reunião. Depois distribuiu fichas para todos avaliarem seu discurso de encerramento.","Segundo seus cálculos, uma reunião fica 40% mais interessante quando você fala. Os colegas querem desativar essa estatística.","'Quem dirige a reunião?' 'Oficialmente, ninguém.' Você já planejou a entrada principal e o cumprimento final."],"love":["Seu charme gosta de gestos grandiosos; até oferecer um biscoito exige discurso de apresentação.","Para um simples convite para jantar, você planejou uma entrada com música. A pessoa amada esperava macarrão, não uma estreia mundial.","Até um encontro simples merece, na sua opinião, uma entrada digna de festival. O tapete vermelho é opcional.","Quando sua cara-metade conta o dia, você ouve sinceramente e confere discretamente se ela notou sua roupa.","Uma foto a dois só fica boa depois de várias tentativas, principalmente para encontrar seu melhor sorriso.","Por trás da sua generosidade carinhosa, às vezes existe uma pequena fanfarra que não sabe a hora de parar.","Palavras carinhosas derretem você; um simples « que blusa bonita » pode alimentar sua alegria até o jantar.","Sua declaração ocupa três cartões, cada um mais romântico que o anterior. Só falta um intervalo para a outra pessoa responder.","Sua surpresa romântica inclui pétalas, playlist e cronograma. A outra pessoa só queria saber onde deixar os sapatos.","Você envia uma declaração tão grandiosa que o celular propõe publicá-la em capítulos. O primeiro acaba num coração.","Você leva flores e um pequeno discurso ao encontro. Ainda bem que o buquê não precisa de legendas.","Você imaginou um jantar à luz de velas com entrada cinematográfica. A pequena chama quase roubou a cena."],"wellbeing":["Sua manhã de descanso começa escolhendo uma roupa digna de spa de luxo. Você demora tanto que o chá esfria no camarim.","Você tenta fazer uma pausa silenciosa; dois minutos depois, considera publicar um relatório sobre a experiência.","Sua rotina de cuidados tem começo, final e música de créditos. O pote de creme é seu colega de palco mais pontual.","Uma caminhada comum vira seu desfile particular. Você anda com tanta confiança que os pombos se afastam como fotógrafos imaginários.","Uma noite sem programação parece repousante, contanto que você escolha a trilha dos créditos finais.","Por trás do desejo de ar livre, às vezes bastam sofá e cobertor à altura do seu prestígio.","Você adora momentos calmos, sobretudo quando ninguém confunde tranquilidade com ausência de admiração.","Você reservou um momento só seu. Na programação: banho relaxante, roupão majestoso e autógrafo imaginário na toalha.","Sua máscara facial transforma dez minutos de calma em preparação para uma cerimônia. Você sai do banheiro como de um camarim secreto.","Previsão do dia: clima de spa, leve névoa perfumada e grande chance de roupão usado com majestade.","Você escolheu música tranquila para a pausa. Duas faixas depois, já compôs o título do próximo ritual de beleza.","Um banho simples quase basta. Só falta dobrar as toalhas como num hotel com muito a provar."],"wisdom":["Sua modéstia às vezes chega atrasada: estava procurando uma entrada mais espetacular.","Você divide a luz de bom grado, desde que continue segurando o interruptor.","A luz ilumina sem contar a própria biografia. É uma técnica que você poderia aprender com o sol.","Quando ninguém olha, um Leão finalmente consegue terminar o café ainda quente.","Uma boa ideia não precisa do seu retrato no cartaz.","Por trás de cada discurso grandioso às vezes existe vontade de comer um biscoito.","Brilhar não é competição de intensidade. Uma vela pode ajudar sem declarar guerra ao farol.","Brilhar junto com outros evita ter de carregar toda a iluminação.","Uma luminária ilumina melhor quando aceita não ser a única da sala.","É preciso coragem para brilhar e também para deixar alguém passar na frente.","A luz de verdade não se mede por quantas pessoas viram a cabeça. O poste confirma.","A modéstia não apaga nada. Só diminui a intensidade quando os outros procuram as chaves."],"roast":["Sua entrada num ambiente merece trailer de cinema. Pena que você só veio buscar as chaves.","Você não pergunta as horas: oferece ao relógio o privilégio de lhe responder.","Sua modéstia é tão discreta que aparece em letras douradas no papel de parede do celular. A fonte está no tamanho 'real'.","Quando alguém conta uma história, você tem uma versão mais espetacular, mesmo sem ter estado lá.","Uma foto de grupo sem você no centro parece, pelos seus critérios, um erro de enquadramento.","Por trás do sorriso real, existe uma ouvidoria dedicada a elogios insuficientes.","Aniversários alheios encantam você: finalmente uma sala já decorada para sua chegada.","Sua generosidade é sincera, mas o presente às vezes vem com um programa de agradecimentos a você.","Você tentou tirar uma foto sem aparecer. O celular achou que era erro de operação.","Seu espelho agora tem uma plaquinha: 'Aqui trabalha seu fã mais fiel'. O expediente é estendido.","Quando alguém diz 'você é incrível', você responde 'em que área?'. O questionário tem três páginas.","Seu ego se inscreveu num concurso de discrição. Enviou um press release para anunciar a participação."]},"piquant":{"career":["Sua ambição não procura um cargo: procura uma sacada para saudar a empresa. O RH hesita em instalar refletores.","Você exige reconhecimento por sua participação na reunião. Moveu uma cadeira; o relatório anual virá depois.","Qualquer sucesso coletivo vira sua entrevista coletiva. Os demais são convidados a se identificar na foto.","Quando ninguém aplaude sua apresentação, você suspeita de uma falha geral do senso artístico.","Uma promoção só interessa de verdade se o título couber numa placa bastante brilhante. A mobília negocia a sobrevivência.","Por trás do seu entusiasmo de líder, cada colega descobre que é figurante sem saber. O elenco foi escolhido sem consulta.","Tarefas anônimas ofendem você: como realizar um feito sem testemunhas? A impressora agora se recusa a dar autógrafos.","Sua liderança transforma o balanço trimestral em espetáculo milionário. Os números não foram consultados sobre seu papel de figurantes.","Últimas notícias: sua equipe concluiu o projeto. Você já escreveu discurso de vitória, making of e proposta de cerimônia anual.","Você chama isso de gestão participativa. Cada colega participa sobretudo da busca por um lugar no seu cartaz de lançamento.","Seu discurso foi tão magistral que a apresentação ganhou bis. O assunto original ainda espera um slide.","Enquete interna fictícia: 98% conhecem sua última conquista. Os 2% que estavam de férias receberam carta registrada."],"love":["Sua necessidade de admiração transforma um jantar tranquilo numa premiação. O cardápio prevê a categoria « presença excepcional ».","Você oferece carinho generosamente e depois espera a cerimônia de agradecimentos. O discurso precisa citar seu nome.","Você prepara uma surpresa romântica tão encenada que a pessoa convidada recebe programa impresso. A emoção vem no primeiro ato.","Quando diz « não quero chamar atenção », você já confere se alguém ouviu o anúncio.","Uma declaração discreta parece quase suspeita. Você pergunta onde estão os fotógrafos e os violinos.","Por trás do seu charme exuberante existe um pequeno controle de reações. Todo sorriso morno é auditado.","Os gestos românticos modestos deixam você perplexo: onde instalar a cortina que se abre? O sofá exige autorização para o espetáculo.","Seu coração tem muito espaço, especialmente para um retrato seu emoldurado. A outra pessoa pode escolher a moldura.","Você não organiza um encontro romântico: produz uma superprodução sentimental. A sobremesa faz teste de elenco.","'Preparei uma surpresa.' 'Qual?' 'Três minutos de discurso antes de você descobrir.' O suspense tem sua assinatura.","Seu carinho vem com laço, violinos e fotógrafo imaginário. A outra pessoa só procura onde segurar sua mão.","Um cartão carinhoso bastava. Você escolheu pergaminho, selo e leitura solene; o carteiro virou mestre de cerimônias."],"wellbeing":["Seu descanso precisa de público. Sem admiradores para testemunhar sua serenidade, você cogita registrar uma reclamação.","Seu ritual de beleza envolve preparação, três acessórios e uma saída majestosa do banheiro. O roupão agora negocia cachê.","O sofá deveria receber uma pausa; agora abriga sua autobiografia em dez volumes. As almofadas exigem direitos autorais.","Você transformou a meditação em premiação particular. A calma venceu, mas você ficou com o troféu.","Uma caminhada solitária vira desfile diante das vitrines. Os manequins pediram o fim da concorrência.","Por trás da agenda lotada, você busca um minuto sem holofotes. Encontrou um e lhe deu seu nome.","Os banhos de tranquilidade fazem bem até você querer publicar os resultados. O júri já foi convocado.","Sua versão de autocuidado parece camarim de estrela em turnê. O hidratante viaja sob acordo de confidencialidade.","Sua rotina de cuidados saiu do momento privado e virou protocolo de palácio. O algodão usa crachá e a toalha tem título oficial.","Avaliação: 'Pausa impecável, mas o roupão só saiu do camarim na terceira entrada'. Nota geral: complicação digna da realeza.","Você não toma banho de banheira, inaugura um spa em miniatura. A espuma reservou o melhor lugar.","Manual da sua calma: preparar o ambiente, escolher acessórios, anunciar a chegada. Etapa opcional: relaxar de verdade."],"wisdom":["Seu ego não precisa de trono: já reservou a sala inteira do conselho.","Você chama isso de carisma. As paredes chamam de palestra sem intervalo.","O silêncio não critica seu talento; é uma pausa regulamentar.","Quando divide os holofotes, o departamento de milagres abre excepcionalmente.","Uma coroa invisível é só um acessório. Você exigiu seguro para a sua.","A humildade é como janela aberta. Você instalou cortinas de teatro e começou a cobrar pela vista.","Para iluminar os outros, às vezes basta recuar um passo. Você preferiu ampliar o projetor.","A luz se compartilha melhor que uma coroa. Você pôs a coroa na lâmpada e declarou o equilíbrio restaurado.","Brilhar sem ofuscar é reservar espaço para a sombra. Você instalou uma placa de 'área reservada'.","A luz não pertence a ninguém. Sua assessoria de comunicação ainda trabalha nessa descoberta.","Grandeza é saber sair de cena. Você tirou todos, menos você.","Um farol serve para guiar, não para distribuir autógrafos aos barcos. Você já prepara cartões assinados."],"roast":["Seu ego pede um assento extra à mesa. O restaurante o incluiu na reserva de grupo.","Você se diz simples: sua simplicidade tem logotipo, slogan e assessoria de imprensa.","O espelho reconhece você antes de sua chegada. Já pediu férias.","Quando um amigo consegue algo, você parabeniza e se oferece para apresentar a cerimônia. Sem convite.","Uma conversa em que você não é o centro ativa o protocolo de emergência. A central não atende mais.","Por trás da generosidade, os agradecimentos seguem um regulamento de doze páginas. Assinado por você.","As selfies viraram sua memória externa. O celular já não conhece a paisagem.","Sua humildade acabou de lançar um livro. A dedicatória ocupa a capa inteira.","Plantão especial: sua selfie ganhou status de monumento pessoal. A galeria do celular organiza visitas guiadas.","Você não procura elogios. Seria simples demais. Abriu um guichê para recebê-los, com agendamento obrigatório.","Seu ego entrou numa sala de espera. Rebatizou os assentos de 'tribuna real' e distribuiu seu retrato como senha.","O espelho relatou uma anomalia: há três dias ninguém admira seu perfil favorito. Você abriu um gabinete de crise."]},"roastMy":["Leão, você não entra num ambiente: inaugura o lugar. Confere iluminação, ângulo dos olhares e reação do público. Um almoço em família vira sua conferência anual. Os parentes pediram tradução simultânea dos elogios obrigatórios.","Você adora ser admirado, mas « parabéns » já não basta. Quer um « parabéns » fundamentado, datado e assinado por duas testemunhas. O elogio enfim chega e você contesta a redação. Seu departamento jurídico se chama « eu ».","Sua generosidade é imensa, especialmente quando há cartaz. Você oferece a sobremesa, organiza uma foto e discursa sobre gratidão. O bolo esfria sob aplausos imaginários. A confeitaria pediu discrição ao próximo benfeitor.","Você garante não gostar de chamar atenção. Curioso para quem anuncia a chegada ao grupo antes de fechar a porta. Depois de sentar, pergunta se o clima era diferente sem você. O silêncio é registrado como avaliação de cinco estrelas.","Suas selfies não registram um momento: documentam um reinado. A paisagem tentou aparecer atrás, mas você cortou esse intruso. Até o pôr do sol ficou de fundo para seu sorriso. Ele prepara recurso por concorrência desleal.","Seu ego não cabe numa reunião comum. Você exige pauta, púlpito e um minuto de ovação na abertura. O assunto era escolher os copos descartáveis. Os copos abandonaram a comissão.","Você sonha com simplicidade, desde que seja elegante e notada. Seu visual descontraído exigiu três provas e um anúncio oficial. Até seu suéter velho tem assessoria de comunicação. A lavanderia não aceita mais entrevistas.","Sua presença ilumina as festas, principalmente porque você mesmo aumenta a intensidade das lâmpadas. Conta uma história e a encena de novo com as falas certas. Seus amigos sabem o roteiro de cor. Um deles pediu dublê para as risadas.","Você recebe um elogio como uma capital recebe visita de Estado. Protocolo, sorriso, discurso de agradecimento e menção aos méritos esquecidos. A pessoa só queria dizer que sua planta é bonita. A planta reivindicou a presidência.","Seu talento para liderar é inegável; você orienta até quem sabe para onde vai. Indica a saída de uma loja e depois cobra reconhecimento pela eficiência. O segurança lhe deu uma missão simbólica. Você a transformou em coroação.","Leão, você aceitou participar de uma caça ao tesouro com amigos. Na primeira pista assumiu o comando e batizou a equipe em sua homenagem. No fim, achou o tesouro no próprio bolso. Os outros procuravam o mapa; você planejava inaugurar o museu.","Você queria organizar uma noite simples, sem espetáculo. Começou distribuindo papéis aos convidados e desenhou um fluxo de circulação ao redor da sua poltrona. Todos se sentiram bem recebidos. Menos a espontaneidade, presa no vestiário.","Um dia sem agenda serviria para você se reencontrar. Você criou uma cerimônia particular para celebrar cada avanço, do café da manhã à arrumação de um livro. Ao meio-dia já havia distribuído sete prêmios. O dia recusou a oitava categoria.","Você foi escolhido para anunciar uma boa notícia ao grupo. Sua voz virou trailer de cinema; você interrompeu a história para criar suspense. Todos esperaram a revelação com seriedade. Era um jogo de cartas novo, já incluído na sua lista de troféus.","Seu acolhimento é espetacular: você oferece uma cadeira, conta sua história e explica seu papel na decoração. O convidado se senta, impressionado. Então você tira um folheto sobre os outros móveis. O sofá mudou de casa durante a introdução."]},"virgo":{"classic":{"career":["Seu olhar atento aos detalhes ajuda a consolidar um projeto antes de apresentá-lo.","Você gosta de métodos claros; eles também podem abrir espaço para uma ideia inesperada.","A precisão que você leva a cada etapa tranquiliza quem trabalha ao seu lado.","Quando sua exigência fica excessiva, separar o essencial do acessório torna o caminho mais leve.","Uma tarefa complexa costuma ganhar coerência sob seu olhar metódico.","Por trás da sua necessidade de organização existe uma vontade genuína de ajudar.","As pequenas melhorias que você percebe podem ter grandes efeitos no trabalho coletivo.","Sua capacidade de análise ganha mais valor quando acompanhada de confiança nos outros."],"love":["Sua atenção aos detalhes permite perceber necessidades que nem sempre são expressas.","Você costuma demonstrar carinho facilitando o cotidiano de quem importa.","A vontade de fazer tudo certo pode diminuir quando você aceita o inesperado nos seus vínculos.","Quando deixa de procurar as palavras perfeitas, sua sinceridade encontra um caminho mais direto.","Uma relação também se constrói com gestos imperfeitos que se transformam em belas lembranças.","Por trás da sua reserva há escuta atenta e muita lealdade.","As nuances que você percebe na outra pessoa às vezes merecem ser acolhidas sem análise.","Sua ternura aparece plenamente quando a vontade de acertar dá espaço à espontaneidade."],"wellbeing":["Seu gosto pela ordem pode ser um recurso, desde que não transforme o descanso em tarefa.","Faz bem reservar momentos sem objetivo definido ao longo do dia.","O prazer de caminhar simplesmente, sem otimizar o trajeto, pode renovar sua atenção.","Quando tudo parece precisar de correção, um momento calmo ajuda a mudar de perspectiva.","Uma pausa longe das telas dá à sua mente exigente um pouco de flexibilidade.","Por trás do seu senso de responsabilidade, sua necessidade de tranquilidade também merece espaço.","Gestos simples, como beber água ou respirar no seu ritmo, fazem parte do equilíbrio diário.","Seu bem-estar não se mede pelo número de caixinhas marcadas."],"wisdom":["Sua precisão serve melhor à vida quando deixa espaço para ela.","Você pode cuidar de um detalhe sem querer corrigir o conjunto.","O verdadeiro equilíbrio aceita o que ainda está em construção.","Quando o método encontra a flexibilidade, o esforço fica mais leve.","Uma lista concluída não define o valor de um dia.","Por trás de cada imperfeição pode haver uma possibilidade nova.","As coisas simples não precisam ser melhoradas para serem bonitas.","Aceitar o inacabado também é uma forma de domínio."],"roast":["Sua necessidade de conferir tudo pode tornar decisões mais pesadas do que realmente são.","Você identifica diferenças minúsculas com facilidade, dando pouca trégua a quem está por perto.","A vontade de organizar tudo às vezes adia o momento de aproveitar o resultado.","Quando uma frase parece mal formulada, a correção ocupa mais espaço que a intenção.","Uma lista detalhada demais pode fazer você esquecer por que começou a escrevê-la.","Por trás da sua preocupação com eficiência, o imprevisto às vezes merece mais confiança.","Os conselhos que você dá com precisão nem sempre são pedidos com a mesma precisão.","Sua busca pelo trabalho impecável ganha quando reconhece o que já está suficientemente bom."]},"funny":{"career":["Você revisa um comunicado interno para 'conferir um detalhezinho'. Três versões depois, a pontuação está impecável e a reunião mudou de data.","Você relê o e-mail de um colega para conferir um detalhe; três vírgulas recebem avaliação completa.","Pedem que você revise um documento. Você devolve o texto, uma legenda das correções e dicas para nomear melhor as versões.","Quando alguém diz « a gente improvisa », sua agenda fecha simbolicamente todas as janelas.","Uma reunião de quinze minutos vira sua oportunidade de salvar o mundo de uma numeração errada.","Seu escritório recebe um procedimento novo. Você percebe que falta um procedimento explicando como ler o procedimento.","Suas anotações durante a ligação são tão precisas que o interlocutor gostaria de encomendar uma cópia.","Essa caneta favorita não se empresta de qualquer jeito. Foi escolhida depois de uma comparação criteriosa.","Aviso oficial: toda vírgula fora do lugar deve ser comunicada ao seu departamento. As frases começaram a andar na ponta dos pés.","Você revisou um e-mail de três linhas e acrescentou um sumário. É importante que os destinatários se localizem.","'Está pronto?' 'Quase.' Você ainda decide se 'quase' precisa de definição no manual de procedimentos.","Um procedimento novo interessa a você, sobretudo porque já identificou seis pontos em que ele poderia ficar ainda mais procedimental."],"love":["Sua declaração de carinho parece um serviço bem organizado: você lembrou do guarda-chuva e do horário do ônibus.","Você percebe imediatamente um pequeno detalhe que alguém mudou em casa. A pessoa nem sabia que havia inventário.","Você prepara um jantar a dois considerando cada preferência da outra pessoa. Falta resolver como avisar que o guardanapo está mal dobrado.","Quando ganha flores, você se emociona e logo procura o vaso mais adequado.","Uma surpresa agrada muito você, desde que tenha a gentileza de estar anotada no calendário.","Por trás do ar sério existe alguém que diz « gosto de você » consertando a porta do armário.","Sua mensagem romântica traz um carinho adorável e três informações práticas. A última indica a localização exata da surpresa.","Sua vontade de cuidar dos outros às vezes inclui uma notinha sobre como dobrar os guardanapos corretamente.","Você sabe a bebida favorita da outra pessoa, a temperatura ideal e o melhor lado da mesa. Só falta o gosto pelas surpresas.","Sua declaração começa com 'pensei em você' e continua com uma proposta detalhada para melhorar os encontros.","Você nota imediatamente uma mudança de hábito na pessoa amada. Ela só tinha mudado a xícara de lugar.","Sua cara-metade conta um pequeno problema. Você oferece ouvidos atentos e três soluções ordenadas por delicadeza."],"wellbeing":["Você organizou tão bem o canto de descanso que a almofada não ousa sair do lugar. O repouso espera autorização para sentar.","Você quer tomar um ar, mas compara três trajetos antes de escolher a caminhada mais simples.","O cobertor está perfeitamente dobrado justamente quando você deveria se acomodar debaixo dele.","Quando faz uma pausa, anota mentalmente que ela começou dois minutos depois do previsto.","Uma xícara de chá vira exercício de precisão em que até o pires respeita seu lugar.","Por trás da vontade de organizar tudo, o sofá faz um convite sem anexo.","Caminhadas fazem bem a você, principalmente quando aceita que uma folha esteja fora do lugar.","Seu conceito de tranquilidade inclui a satisfação de ver todas as notificações finalmente classificadas.","Você reorganizou as toalhas por tamanho. O banheiro parece uma loja da qual você é o único cliente.","Previsão do tempo interior: céu limpo nas prateleiras, poeira leve ao norte do aparador, intervenção prevista antes do lanche.","Para relaxar, você alinhou os sapatos do corredor. Os cadarços enfim entenderam a disciplina coletiva.","Você decretou uma noite sem faxina. Depois criou uma exceção para migalhas e outra para marcas de dedos."],"wisdom":["Um dia bonito suporta uma pequena imperfeição. O céu não revisa seus textos antes de abrir.","Você pode confiar na vida mesmo quando ela esquece o índice.","A bagunça nem sempre é urgência; às vezes, é só uma almofada fora do lugar.","Quando uma caixinha fica vazia, o universo não abre automaticamente uma investigação.","Uma vírgula fora do lugar não estraga o sabor do café.","Por trás da perfeição costuma existir uma cadeira que poderia simplesmente ser usada.","Os imprevistos não leem seus procedimentos. Que falta de educação.","O essencial às vezes aceita uma pasta chamada « ver depois ».","Um detalhe perfeito nem sempre salva uma ideia torta. O pingo do 'i' não é arquiteto.","Aceitar um pequeno erro é deixar a vida fazer uma anotação na margem sem pegar a borracha.","O mundo às vezes avança com uma vírgula fora do lugar. Ainda acha o caminho até o próximo parágrafo.","O essencial nem sempre vem etiquetado. Você precisará de paciência para reconhecê-lo."],"roast":["Seu espírito crítico nunca dorme. Até um cartaz de férias recebe sugestões de diagramação.","Sua lista de compras tem legenda, categorias e um quadradinho para imprevistos. Até o imprevisto ganhou etiqueta.","Qualquer « mais ou menos » dá vontade de pegar o nível de bolha.","Quando alguém diz « está ótimo assim », você ouve o início de uma negociação.","Você etiqueta caixas vazias para saber o que poderiam guardar. A caixa 'ideias espontâneas' foi lacrada cuidadosamente.","Por trás do sorriso educado, uma tabela de avaliação atribui notas secretas aos outros.","Sua planilha de lazer distingue 'divertido', 'muito divertido' e 'divertido com ressalvas'. O lazer aguarda o veredicto.","Seu descanso tem horários tão exatos que poderia bater ponto na entrada.","Sua agenda de fim de semana inclui 'não planejar nada'. O horário já foi reservado para conferir a agenda.","Você fez uma lista para preparar suas listas. No terceiro nível, o lápis declarou independência.","Pesquisa doméstica fictícia: 100% dos objetos têm etiqueta. O gato se recusa a informar sua categoria.","Você fez uma planilha para comparar caixas organizadoras. As caixas hesitam em ser trancadas nela."]},"piquant":{"career":["Seu perfeccionismo transformou um e-mail simples numa obra regulamentada. A saudação ainda aguarda alvará.","Você corrige as vírgulas dos colegas com a gravidade de um juiz. O teclado pediu advogado.","Você revisou tanto a apresentação de um colega que corrigiu a grafia do nome dele. A reunião começou com debate de ortografia administrativa.","Quando uma tarefa termina, você a abre de novo para verificar se merece esse status. A palavra « concluído » pediu demissão.","Um simples comunicado passou pelo seu controle de qualidade. Você achou três inconsistências e criou uma quarta etapa para documentá-las.","Por trás dos métodos impecáveis, um comitê de controle vigia outro comitê de controle. O auditor também é você.","Os prazos só são respeitáveis se incluírem margem, alerta e plano de alerta. A agenda se escondeu.","Seu olhar atento bloqueou uma reunião por causa da fonte do título. A reunião tratava de uma urgência que já passou.","Últimas notícias: sua equipe entregou um texto impecável. Você apontou uma inconsistência entre dois espaços invisíveis. A comemoração foi adiada.","Você corrige procedimentos como maestro diante de uma nota desafinada. Os músicos são fotocopiadoras conformadas.","Sua revisão de um anúncio interno demorou mais que a decisão anunciada. O anúncio perdeu a vontade de existir.","Manual da sua reunião ideal: verificar a pauta, aprovar a sintaxe, conferir títulos. Conteúdo principal: opcional."],"love":["Sua ternura se expressa por correções discretas. O buquê era bonito antes da auditoria do vaso.","Você ouve confidências como gerente de qualidade. A pessoa queria carinho, recebeu plano de melhoria.","Uma mensagem romântica emociona você até encontrar dois erros. O cupido foi convocado para reciclagem.","Quando alguém prepara uma surpresa, você pede horário, endereço e grau de preparação. O mistério cancelou a visita.","Uma noite a dois vira sucesso assim que as almofadas ficam simétricas. Os sentimentos aguardam no guarda-volumes.","Por trás da sua atenção delicada, um formulário invisível avalia a coerência dos gestos carinhosos. A opção « espontaneidade » está desativada.","Pequenos defeitos encantadores dos outros divertem você, exceto quando podem ser corrigidos em cinco etapas. O romantismo abriu um chamado.","Seu coração não está fechado: está organizado por tema, data e prioridade. A chave fica numa pasta compartilhada.","Você não observa os hábitos da outra pessoa: publica estudo comparativo. A seção 'manias adoráveis' tem 46 anexos.","Uma surpresa romântica chega com instruções de conservação e justificativa de cada detalhe. A emoção procura o botão 'modo livre'.","Você encontrou uma inconsistência numa declaração carinhosa. Parabéns, o sentimento agora está homologado conforme uma versão anterior.","'Gostou da noite?' 'Sim, mas a segunda metade precisava de estrutura melhor.' O encontro vai para o arquivo pedagógico."],"wellbeing":["Você limpou o canto de descanso com precisão de laboratório de poeira imaginária. Depois proibiu tudo que pudesse sujá-lo.","Você arruma as almofadas antes de se deitar e depois confere o alinhamento. O sofá exige um mediador.","O silêncio acalma você até perceber um relógio um pouco torto. A tranquilidade foi adiada.","Quando sai para caminhar, otimiza as ruas e compara calçadas. Até o ar fresco recebe nota.","Uma xícara quente deveria relaxar você; virou comparação entre modelos de xícara. A bebida esfriou durante a auditoria.","Por trás das boas intenções, a descontração parece uma inspeção surpresa. O cobertor está sem documentos.","Fins de semana livres preocupam você: não há caixinha indicando onde colocar o prazer. O domingo aguarda descrição de cargo.","Sua vontade de desligar é exemplar. Você só programou três lembretes para não esquecer.","Seu armário está tão organizado que as meias receberam números de setor. A meia sem par agora vive no exterior.","Avaliação do cliente: 'Limpeza impecável, impossível achar objetos fora da posição autorizada'. Você respondeu com planta em escala.","Você limpou a mesa, depois a esponja e depois o lugar onde a esponja ficava. O ciclo prossegue sozinho.","Seu ritual noturno tem quatro etapas de arrumação e uma pausa. A pausa foi adiada para não atrapalhar a arrumação."],"wisdom":["O detalhe é um convidado útil, não o dono da casa. Mesmo assim, você lhe entregou o quarto principal.","Você não procura a perfeição: persegue o defeito até a casa dos vizinhos.","O caos às vezes é só uma meia fora do lugar. Seu relatório tem vinte páginas.","Quando diz « só um detalhe », a equipe técnica evacua o prédio.","Uma vírgula não governa o mundo. Ela ainda não recebeu o comunicado.","Por trás da sua paz interior, um fiscal inspeciona a dobra das nuvens.","Errar é humano. Você pediu para revisar o formulário da humanidade.","O imprevisto não preencheu seu questionário. Você barra a entrada.","A perfeição sempre promete um último retoque. Você assinou um plano sem prazo para acabar.","O essencial não desaparece porque um detalhe sobrou. Você criou uma comissão para medir a sobra.","Um erro minúsculo pode ensinar. Você o transformou em conferência anual sobre o milímetro.","A imperfeição às vezes dá personalidade. Seu corretor automático apresentou objeção formal."],"roast":["Sua lista de prioridades tem uma seção sobre como classificar prioridades. O fichário prepara sua entrada no governo.","Você tem lista para tudo, inclusive dos motivos para parar de fazer listas. Ela está plastificada.","Um quadro minimamente torto provoca uma comissão de inquérito. O prego se declara inocente.","Quando alguém escreve uma expressão errada, você suspende mentalmente as relações diplomáticas.","Uma noite improvisada parece sabotagem logística. O jogo de tabuleiro aguarda autorização.","Por trás da sua calma aparente, um fiscal verifica se os guardanapos assinaram o livro de registro.","Os outros descansam; você avalia a qualidade do descanso e propõe correções.","Você etiquetou os potes e depois as etiquetas reservas. A etiqueta 'etiquetas' agora reina numa moldura.","Sua lista de convidados tem colunas 'simpatia prevista' e 'simpatia observada'. Os amigos viraram dados.","Você criou etiquetas para a gaveta de etiquetas. Nasceu uma categoria nova: 'crise de classificação'.","Sua planilha de controle das planilhas superou a principal. Agora prevê uma avaliação anual das próprias colunas.","Você não prepara planos: prepara o plano destinado a aprovar os próximos planos. O acaso perdeu o crachá de acesso."]},"roastMy":["Virgem, você não organiza sua casa: governa um território. Cada objeto tem endereço, função e punição se sair do lugar. Seus convidados deixam os casacos na área errada. Um comitê disciplinar se reúne antes da sobremesa.","Você corrige erros como outras pessoas cumprimentam os vizinhos. Chega uma mensagem carinhosa com pequeno deslize e você quase esquece por que se emocionou. Envia um coração e depois a versão corrigida. O teclado pede separação administrativa.","Sua lista de tarefas tem capa, capítulos e anexo dedicado às sublistas. Você marca uma caixinha com a satisfação de ter restaurado a ordem mundial. Aparecem mais duas tarefas. A lista fundou sua própria burocracia.","Você chama isso de « gostar de tudo bem-feito ». Os outros chamam de « apresentar documentação para mover uma cadeira ». Você propõe simplificar o processo com um formulário menor. Ele tem quatorze páginas.","Você analisa cada mensagem a ponto de um simples « beleza » virar enigma. Por que não « perfeito »? Por que esse ponto? Por que nesse horário? A conversa terminou, mas você acaba de abrir uma comissão parlamentar.","Sua ideia de espontaneidade é inverter a ordem de duas atividades planejadas. Você sente uma emoção enorme e logo restaura o cronograma. Até o destino recebe relatório. Ele não pediu confirmação de leitura.","Você adora ajudar, principalmente quando pode explicar o que deveria ter sido feito antes. Sua ajuda é eficaz, detalhada, documentada e acompanhada de esquema. Todos agradecem sinceramente. Depois escondem as gavetas.","Você sonha com um dia sem obrigações. Então libera a agenda, prepara a lista de atividades sem obrigações e programa um alerta para aproveitá-las. Ao meio-dia, audita a eficiência do repouso. A rede ameaça processar você.","Sua cozinha é tão bem organizada que uma colher perdida poderia gerar alerta nacional. Você encontra a colher no lugar correto, só um pouco virada. Suspeita de ação deliberada. A lava-louças pede asilo político.","Você diz, com muita seriedade, que não julga ninguém. Só observa, classifica, compara e redige mentalmente um parecer construtivo. Um amigo apenas pergunta se a apresentação foi clara. Você exige mais tempo no projetor.","Virgem, você ofereceu ajuda para organizar uma caminhada entre amigos. Preparou rota, duas alternativas e planilha de desvios. O passeio ocorreu sem incidentes, exceto uma folha que caiu na trilha. Você adicionou 'folhas inesperadas' à próxima pauta.","Você quis preparar um presente totalmente espontâneo. Comparou papéis, conferiu medidas e testou três laços. O presente ficou lindo e perfeitamente embrulhado. A surpresa chegou com seu próprio manual de instruções.","Você decidiu deixar outra pessoa cozinhar. Sorriu, observou o preparo e sugeriu uma melhoria que trouxe outras cinco. A comida ficou ótima, ninguém duvidou. A espátula incluiu 'autonomia' na lista de desejos para o ano seguinte.","Na biblioteca, você notou um livro ligeiramente torto. Endireitou-o e ajustou os vizinhos para manter o alinhamento. Dez minutos depois, toda a estante parecia inspecionada por autoridade invisível. O bibliotecário pensou numa fiscalização.","Você quis passar um dia sem avaliar nada. Resistiu a dar notas ao café, ao caminho e à música. À noite, comemorou o avanço num relatório de três páginas. A espontaneidade recebeu nota nove de dez."]},"libra":{"classic":{"career":["Seu senso de equilíbrio ajuda a enxergar melhor quando surgem opiniões opostas no trabalho.","Você sabe reunir pontos de vista diferentes; escolher uma direção clara completa esse talento.","A busca por harmonia pode apoiar seus projetos sem descartar divergências úteis.","Quando várias soluções parecem interessantes, seus critérios essenciais ajudam você a avançar.","Uma fala ponderada pode facilitar a cooperação diante de uma decisão delicada.","Por trás da sua diplomacia existe a capacidade de defender uma ideia com elegância.","As escolhas profissionais ficam mais leves quando você aceita não comparar absolutamente tudo.","Seu senso estético pode enriquecer uma apresentação bem-feita e uma visão original."],"love":["Seu desejo de harmonia favorece conversas em que todos se sentem ouvidos.","Você gosta de criar momentos bonitos; a simplicidade deles pode importar tanto quanto a aparência.","A necessidade de agradar diminui quando você expressa suas preferências com mais liberdade.","Quando uma conversa exige franqueza, sua delicadeza pode acompanhar palavras sinceras.","Uma relação equilibrada também se alimenta das diferenças que você aprende a acolher.","Por trás do seu charme discreto existe uma vontade profunda de compreender a outra pessoa.","As pequenas indecisões do cotidiano pesam menos que a qualidade da sua atenção.","Seu senso de justiça encontra na ternura uma expressão mais pessoal."],"wellbeing":["Sua busca por equilíbrio pode orientar você a um ritmo que respeite suas necessidades.","Você aprecia lugares agradáveis; um ambiente simples pode ser suficiente para acalmar.","A preocupação em agradar a todos às vezes merece ceder espaço à sua própria tranquilidade.","Quando as escolhas se multiplicam, ficar um momento longe das solicitações pode esclarecer seus desejos.","Uma caminhada por um lugar harmonioso renova sua atenção às pequenas coisas.","Por trás da sua disponibilidade para os outros, seu tempo pessoal também merece proteção.","Prazeres estéticos, música suave ou um cômodo iluminado podem acompanhar seu descanso.","Sua paz interior não exige que todas as pessoas ao redor concordem entre si."],"wisdom":["Seu equilíbrio cresce quando você ousa escolher sem certeza absoluta.","Você pode ouvir todas as vozes sem esquecer a própria.","A beleza não substitui a verdade, mas pode abrir caminho para ela.","Quando a paz exige silêncio, a franqueza merece espaço.","Uma decisão imperfeita às vezes vale mais que uma espera sem fim.","Por trás da hesitação costuma existir a vontade de acertar.","As diferenças não apagam a harmonia; dão a ela mais profundidade.","Escolher com delicadeza continua sendo uma escolha real."],"roast":["Sua necessidade de comparar pode atrasar escolhas que exigem apenas uma preferência.","Você se esforça tanto para não desagradar ninguém que sua própria opinião às vezes fica inaudível.","O desejo de um ambiente agradável pode levar você a evitar uma conversa necessária.","Quando duas opções são equivalentes, você pode gastar mais tempo pesando-as do que aproveitando-as.","Educação em excesso pode dar a impressão de que você concorda com algo que não deseja.","Por trás do seu charme, uma hesitação sincera às vezes pede mais clareza.","As opiniões de quem está perto enriquecem sua reflexão, mas não precisam decidir por você.","Seu senso de harmonia continua valioso mesmo quando uma conversa se torna desconfortável."]},"funny":{"career":["Sua reunião ideal termina quando todo mundo concorda. Portanto, pode durar até o próximo trimestre.","Antes de aprovar uma proposta, você consultou quatro colegas. O quinto vai conferir se ninguém se sentiu excluído.","A discordância entre colegas leva você a bancar o mediador; já preparou as bebidas da reconciliação.","Quando duas equipes disputam uma tarefa, você sugere um acordo tão elegante que cada uma fica com metade de um grampeador.","Uma decisão rápida parece quase uma prova esportiva para você.","Por trás do seu sorriso diplomático, doze versões do e-mail começam com « talvez ».","Sua reunião por consenso termina com votação unânime por outra reunião. Pelo menos isso não divide ninguém.","Seu talento para ouvir argumentos é enorme; o relógio já começou a apresentar o dele.","Sua frase favorita no trabalho é 'as duas ideias têm seus méritos'. O problema é que se contradizem completamente.","Pesquisa fictícia: doze colegas consultados, zero conflitos e um projeto ainda em consulta. Você chama isso de começo tranquilo.","'Você pode decidir?' 'Claro.' E sugere uma reunião para todos explicarem por que preferem não decidir.","Você desfaz discussões tensas com tanto tato que até a impressora aceita dividir folhas sem reclamar."],"love":["Seu romantismo hesita entre jantar à luz de velas e caminhada. Você reserva mentalmente as duas opções.","Você hesita entre passeio romântico e show intimista. Procurando o momento ideal, inventou a caminhada com música imaginária.","A escolha de um presente começa com uma seleção tão cuidadosa que poderia virar exposição.","Quando alguém diz « escolha onde vamos comer », você sorri com a dignidade de quem enfrenta uma prova surpresa.","Seu senso estético transforma um pequeno presente em cena de cinema. Um buquê simples vira declaração digna de trilha sonora.","Por trás do seu charme natural, um comitê silencioso discute a melhor maneira de dizer boa-noite.","Você detesta desentendimentos; consegue apresentar duas opiniões contrárias com delicadeza impressionante.","Seu charme torna adorável até uma hesitação de dez minutos sobre como dizer 'boa noite'.","Você ensaiou um convite romântico em três tons. O último ficou tão charmoso que você não quis abrir mão dos outros dois.","Uma vitrine elegante inspira uma ideia de encontro. A vitrine seguinte inspira outra melhor. O passeio vira galeria de intenções.","Você dá flores que combinam com o clima da noite. A pessoa amada só percebe que você finalmente tomou a iniciativa.","Seu charme funciona até na escolha do banco com a melhor vista. Você gosta tanto dos dois lugares que fica de pé."],"wellbeing":["Seu relaxamento começa com a escolha do clima. Três velas depois, você ainda decide a iluminação.","Você planeja caminhar e gasta dez minutos comparando dois parques igualmente encantadores.","A almofada do sofá nunca está exatamente no lugar certo. Você discute isso mentalmente com ela.","Quando um amigo pergunta o que gostaria de fazer, você responde « o que você quiser » com uma sinceridade perigosa.","Uma playlist tranquila vira uma compilação de escolhas difíceis entre músicas igualmente lindas.","Por trás da sua vontade de paz, às vezes você precisa escolher sem pedir a opinião do vaso.","Objetos bonitos relaxam você; seus olhos, porém, acabam reorganizando mentalmente a sala inteira.","A tarde ideal não teria nenhuma decisão. Só falta decidir como organizá-la.","Você rearranjou três quadros para criar um canto tranquilo. Agora a poltrona não sabe para que lado relaxar.","Sua rotina de descanso começa alinhando almofadas. A paz chega quando os dois lados do sofá assinam um tratado.","Previsão do tempo interior: clima harmonioso, risco localizado de deslocamento de vaso devido a leve desequilíbrio.","Um buquê parece ideal para suavizar a sala. Após dez testes, você acha o lugar certo: o lugar de antes."],"wisdom":["Seu equilíbrio não exige votação para cada biscoito.","Você pode gostar de duas opções e escolher uma antes de a loja fechar.","Bom gosto não precisa de doze testemunhas para existir.","Escolher uma porta significa abrir mão de visitar as outras. Você pode guardar os folhetos, não as maçanetas.","Uma opinião pessoal não desencadeia automaticamente uma conferência internacional.","Por trás de cada hesitação às vezes existe um sofá esperando.","As contradições podem coexistir, mas não precisam dirigir o ônibus.","Escolher ao acaso continua sendo escolher; o dado explicaria isso melhor que você.","Para manter o equilíbrio, às vezes é preciso avançar, não comparar todos os sapatos disponíveis.","Duas escolhas podem ser belas. O segredo é aproveitar a escolhida sem escrever cartas para a outra.","A hesitação ajuda a refletir; não deveria alugar um apartamento na sua cabeça.","Uma balança parada não prova sabedoria. Às vezes só espera que alguém retire um dos pratos."],"roast":["No restaurante, você reduziu o cardápio a três pratos. Um avanço histórico, mas o garçom já encerrou o turno.","Você evita conflitos tão bem que pede desculpas à porta quando ela atrapalha sua passagem.","O cardápio conhece você: você o lê como um romance com vários finais.","Quando perguntam sua preferência, você descreve as qualidades das duas opções e esquece a pergunta.","Uma discussão perto de você aciona seu serviço de mediação e uma distribuição de guardanapos.","Você hesita entre dois tons de tinta há tanto tempo que a parede aprendeu a gostar do branco provisório.","Você adora objetos bonitos a ponto de exigir elegância até do formato de um clipe.","Sua delicadeza é lendária: você conseguiria dizer a um espelho que ele reflete mal sem ofendê-lo.","Você comparou os menus de três restaurantes. O primeiro fechou para reformas durante sua análise.","Na loja de tintas, você hesita entre bege suave e bege sereno. O vendedor nem sabia que esses países existiam.","Seu menu ideal só tem uma opção. Você investiga se a outra foi esquecida por engano.","Você passou vinte minutos escolhendo um guarda-chuva. A chuva parou, mas a cor está quase decidida."]},"piquant":{"career":["Sua indecisão transforma escolher um grampeador numa cúpula diplomática. As delegações exigem data de encerramento.","Você consulta oito colegas antes de enviar um e-mail de três palavras. A resposta chegou antes da pergunta.","Sua diplomacia transformou uma discordância sobre procedimentos em 45 minutos de conversa. O procedimento ficou no guarda-volumes.","Quando a chefia exige uma escolha, você entrega uma tabela tão equilibrada que nem as colunas decidem.","Você quer que cada colega se sinta ouvido. Organizou consulta sobre a ordem de todas as consultas. O projeto continua na fila.","Por trás do sorriso conciliador, um departamento inteiro ainda procura saber o que você pensa. A investigação foi arquivada como « estética ».","Uma negociação com você termina tão pacificamente que ninguém sabe o que foi decidido. A ata registra só 'clima construtivo'.","Sua diplomacia é impecável: conseguiu que todos concordassem em não decidir nada. A ata agradece.","Comunicado oficial: sua equipe criou uma comissão de consenso. Ela não concorda sobre a definição de 'consenso'.","Você evita tanto os conflitos que os desacordos viram 'propostas paralelas'. A reunião termina com duas decisões incompatíveis.","Você consultou doze colegas para validar três palavras. O décimo terceiro não se sentiu representado; volta tudo ao começo.","Seu talento de mediador poderia reconciliar grampeador e papel. Pena que o relatório não foi escrito."],"love":["Seu charme funciona com todo mundo, inclusive quem só pede informação na rua. A pessoa sai com três convites hipotéticos.","Você hesita entre duas ideias de passeio, depois três, depois cinco. O calendário pediu a guarda dos fins de semana.","O jantar romântico começa com « tanto faz ». Quarenta sugestões depois, a cozinha fecha.","Você seduz com tanta delicadeza que o convite parece exposição de arte: lindo, bem iluminado e impossível de interpretar.","Uma possível discussão faz você mudar de assunto com elegância notável. Você acabou de elogiar uma luminária.","Sua indecisão amorosa transforma duas ideias de encontro numa novela de suspense. O trailer ainda não revela o local.","Você distribui charme com tanta naturalidade que seu sorriso parece campanha de lançamento. O romantismo ainda não viu o produto.","Seu coração quer um conto perfeitamente equilibrado. Os personagens ainda esperam você escolher a capa.","Você não escolhe entre duas ideias românticas. Organiza uma final imaginária em que cada possibilidade defende seu charme diante de um júri ausente.","Sua sedução parece uma galeria de luxo: tudo é belíssimo, mas é preciso seguir as setas para chegar a uma declaração real.","Você preparou um convite de rara elegância. O texto e o papel são perfeitos. A data ficou em branco para preservar as opções.","Estatística sentimental fictícia: todas as suas declarações são delicadas. Metade nunca saiu do caderno de rascunhos."],"wellbeing":["Sua busca por serenidade para diante de dois aromas de vela. O conselho das velas se recusa a tomar partido.","Você organiza uma pausa comparando almofadas por quarenta minutos. O descanso cancelou a reserva.","Escolher um banco no parque vira estudo de luz, vista e harmonia. Os pombos ocupam os dois melhores.","Quando sugerem um passeio surpresa, você pede todas as alternativas para não ofender nenhum caminho.","Uma xícara de chá relaxa você até surgir a questão da caneca. O armário abre queixa por perseguição estética.","Por trás da sua doçura lendária, duas playlists relaxantes travam uma pequena guerra civil. O silêncio vence por ausência das concorrentes.","Você sonha com férias sem programação. Já preparou uma programação para escolher as férias sem programação.","Seu momento de calma exige a concordância das cortinas, das flores e do cobertor. O gato vetou.","Sua sala exibe equilíbrio admirável. Uma planta deslocada dois centímetros desencadeou crise de decoração.","Avaliação: 'Sala linda, ambiente sereno, proibido mover uma xícara'. Os móveis confirmam a crítica sussurrando.","Você escolheu três vasos para deixar o espaço tranquilo. Agora passam o dia discutindo onde deveriam ficar.","O tapete traria suavidade. Você o nomeou responsável por reconciliar moralmente as cortinas com o sofá."],"wisdom":["Uma balança serve para pesar, não para imobilizar o mundo. Você acrescentou um terceiro prato para analisar essa nuance.","Escolher é abrir mão de outra possibilidade. Você tentou manter a renúncia como opcional.","O compromisso é admirável. Fazer as plantas votarem no jantar, nem tanto.","Quando dois caminhos se abrem, você contrata um arquiteto para construir o terceiro.","Uma decisão adiada não fica mais elegante. Só ganha outra fita de presente.","Equilíbrio não significa ficar no meio de todos os caminhos. Você instalou um banco no cruzamento.","Espelhos refletem o que existe. Você ainda pergunta qual deles tem razão.","Escolher não é uma agressão às opções restantes. Elas vão superar.","Uma escolha não feita não é perfeita. Você apenas conservou a decisão numa redoma de vidro.","Equilíbrio às vezes exige pender para um lado. Você inventou o movimento sem deslocamento.","A paz interior não é uma negociação eterna entre dois botões. Você já prepara um tratado de neutralidade.","Abrir mão de uma opção não apaga sua existência. Você ergueu um pequeno monumento em homenagem a ela."],"roast":["Sua indecisão é tão organizada que tem conselho consultivo e três suplentes.","Você estudou o menu tão longamente que o chef mudou o cardápio. Agora tem um novo problema filosófico.","O cardápio é um romance de suspense cujo final você se recusa a ler.","Quando uma briga começa, você sorri tanto que as cadeiras se sentem obrigadas a negociar.","Uma preferência pessoal atravessa sua mente. Você imediatamente a submete a consulta pública.","A escolha de uma simples cor levou você a montar um mostruário com 84 tons. O branco venceu por cansaço geral.","Você distribui tantos elogios que até o estacionamento se acha maravilhoso.","Seu conceito de urgência é decidir rapidamente adiar a decisão. A ata já está pronta.","Seu pedido no restaurante virou plebiscito. O garçom votou por seu intervalo.","Você hesitou entre dois tons de verde e criou uma terceira categoria: 'verde que respeita os dois anteriores'.","Sua incapacidade de escolher a entrada criou uma tradição gastronômica: jantar só começa depois da sobremesa.","A loja oferece cinco modelos de xícara. Você propõe uma comissão independente para avaliar os méritos; a loja está fechando."]},"roastMy":["Libra, você não escolhe restaurante: organiza uma consulta popular. Todos opinam, você cria uma tabela comparativa e acrescenta uma opção de última hora. O grupo acaba voltando para casa. Você considera que o clima permaneceu ótimo.","Sua diplomacia reconciliaria dois inimigos imaginários, mas não escolhe entre duas sobremesas. Você pondera preço, aparência, textura e humor do garçom. Ele oferece as duas para agilizar. Você pergunta se existe uma terceira opção.","Você ama a beleza a ponto de considerar uma almofada fora do lugar uma negociação fracassada. Muda a almofada e a outra parece desequilibrada. Uma hora depois, o sofá parece exposição de museu. Ninguém ainda pode sentar nele.","Você diz « não tenho preferência » com sorriso perfeito. Todos sugerem algo e você destaca prós e contras de cada ideia. Até que alguém implora que você simplesmente diga não. Você pergunta se essa recusa seria educada.","Seu charme é uma arma de paz em massa. Você elogia o atendimento, a decoração e até o recibo. O vendedor responde com gentileza e você teme ter exagerado. Uma central de mediação se forma ao redor da nota fiscal.","Você foge de brigas com habilidade quase profissional. Dois amigos discutem e você concorda com ambos com idêntica convicção. Finalmente pedem que decida. Você propõe uma pausa para o chá que durará três temporadas.","Você compara roupas como um museu preparando exposição permanente. Cada opção tem argumentos, atmosfera e público-alvo. No fim, escolhe a primeira e pergunta se era a melhor mesmo. O guarda-roupa exige indenização por consulta abusiva.","Sua busca pela justiça é tão grande que você pergunta à última fatia de bolo se prefere ser comida ou dividida. Ninguém ousa responder por ela. Você cria um sistema justo de rodízio. O bolo exige decisão urgente.","Sua vontade de agradar leva você a concordar com todos, inclusive com duas pessoas que defendem coisas opostas. Você tenta reformular as posições para torná-las compatíveis. Até o dicionário se recusa a testemunhar. Você acha a postura dele muito categórica.","Você sonha com uma vida harmoniosa, sem tensão nem decisões difíceis. Infelizmente, toda manhã começa com duas xícaras igualmente bonitas. Você fica diante do armário analisando seus méritos. A chaleira pediu transferência.","Libra, você aceitou escolher a música de uma viagem entre amigos. Preparou listas para cada humor possível e hesitou sobre a ordem. A viagem ocorreu num silêncio muito pacífico. Você chegou com uma playlist perfeita para a volta, que ninguém ousou ligar.","Você queria organizar uma troca de presentes justa. Comparou embalagens, valores simbólicos e sensibilidades, depois propôs uma divisão sem perdedores. Todos acharam delicado. No fim, os presentes se trocaram sozinhos para agilizar.","Você prometeu decidir espontaneamente antes de sair. Abriu dois armários, avaliou três roupas e refletiu sobre a impressão de cada uma. Saiu com a primeira que provou. A coragem da decisão mereceu um minuto de silêncio.","Seu senso estético levou você a reorganizar a mesa de um jogo. Tudo precisava ficar bonito, acessível e equilibrado. Os jogadores admiraram sua composição. Depois descobriram que as cartas estavam em ordem alfabética para evitar preferências.","Você mediou uma discussão entre amigos sobre uma regra de jogo. Ouviu ambos, reconheceu os argumentos e formulou uma proposta para agradar a todos. Os dois fizeram as pazes. O jogo foi cancelado por falta de regra aplicável."]},"scorpio":{"classic":{"career":["Seu olhar penetrante ajuda a perceber questões que os outros ainda não expressaram.","Você se dedica intensamente aos projetos que fazem sentido para você.","A necessidade de entender as motivações de cada pessoa pode ser uma verdadeira vantagem estratégica.","Quando oferece sua confiança, seu comprometimento dá profundidade ao trabalho coletivo.","Uma intuição forte ganha valor quando confrontada com fatos antes de orientar decisões.","Por trás da sua reserva existe uma mente persistente, capaz de atravessar dificuldades com método.","Situações complexas despertam seu desejo de investigar além das aparências.","Sua determinação rende mais quando permite que os outros avancem do próprio jeito."],"love":["Sua intensidade afetiva leva você a buscar vínculos sinceros e profundos.","Você oferece confiança com cuidado; a reciprocidade se constrói no próprio ritmo.","A necessidade de verdade nas conversas pode conviver com uma escuta delicada.","Quando uma emoção aparece, colocar sentimentos em palavras pode aproximar, em vez de afastar.","Uma relação sólida não exige conhecer todos os pensamentos da outra pessoa.","Por trás da aparente discrição existe uma grande capacidade de estar presente.","As lembranças compartilhadas alimentam seu afeto sem precisar definir o presente.","Sua fidelidade ganha sentido quando vem acompanhada de liberdade mútua."],"wellbeing":["Sua intensidade merece espaços em que nada exija resposta imediata.","Você gosta de compreender o entorno; uma caminhada também pode ser vivida sem interpretações.","A calma de um lugar familiar ajuda você a reencontrar uma sensação de firmeza.","Quando os pensamentos insistem, uma pausa longe das conversas pode dar um pouco de ar.","Uma atividade criativa oferece um caminho tranquilo para sua profundidade interior.","Por trás da sua vigilância, o prazer simples de não monitorar nada também merece existir.","Conversas sinceras com pessoas queridas podem aliviar os silêncios carregados demais.","Sua necessidade de solidão é melhor respeitada quando continua uma escolha, não um refúgio imposto."],"wisdom":["Sua força também se revela naquilo que você decide deixar ir.","Você pode buscar a verdade sem exigir conhecer absolutamente tudo.","O segredo às vezes protege; a confiança muitas vezes aproxima.","Quando a intuição se abre ao diálogo, torna-se compreensão.","Uma emoção profunda não precisa governar todas as decisões.","Por trás da desconfiança pode existir um desejo sincero de conexão.","Os silêncios mais férteis não escondem nada; oferecem descanso.","Compreender não obriga a controlar."],"roast":["Seu talento para perceber o que não foi dito pode levar você a procurar sentido onde não existe.","Você protege seu mundo interior tão bem que às vezes fica difícil entender suas intenções.","A lembrança de uma discordância ocupa muito espaço quando você a guarda sem conversar.","Quando uma resposta parece vaga, sua curiosidade pode soar como interrogatório.","Uma intuição forte nem sempre é prova, por mais convincente que pareça.","Por trás da sua vontade de entender, a necessidade de controlar tudo pode tornar as conversas cansativas.","Nem todos os segredos que você guarda precisam de outra fechadura.","Sua fidelidade às próprias impressões ganha quando dá espaço a explicações novas."]},"funny":{"career":["No escritório, você percebe um arquivo renomeado antes de todos. Três colegas descobrem que a reunião de acompanhamento virou investigação oficial.","Você investiga uma mudança no calendário como se um mistério internacional tivesse começado.","Qualquer documento confidencial recebe seu cuidado de quem protege um cofre.","Quando um colega diz « explico depois », você já abre uma pasta chamada « por que depois? ».","Um simples erro de arquivamento leva você por uma trilha que termina em três reuniões antigas.","Por trás da sua mesa tranquila, sua mente reúne pistas com a paciência de um detetive.","As conversas em voz baixa intrigam tanto você que até a planta do corredor parece suspeita.","Seu olhar atento é implacável: você sabe quem mudou sua caneta de lugar antes de ela ser devolvida.","Um colega adiou a reunião quinze minutos. Você já montou a cronologia e encontrou três possíveis motivos.","Comunicado: a senha nova da equipe não é uma charada. Você a trata como um cofre a ser aberto.","Você conhece as rotinas da sala de reuniões melhor que a agenda dela. A agenda decidiu guardar alguns segredos.","'Quem alterou esse arquivo?' 'Ninguém sabe.' Você já abriu o histórico de versões, com lanterna imaginária na mão."],"love":["Seu olhar intenso transforma a pergunta « o que vamos comer? » numa cena de suspense.","Você guarda pequenos detalhes das conversas com memória que impressionaria qualquer arquivista.","Um simples 'depois te ligo' acelera seu coração. Seu olhar fica tão intenso que o celular parece procurar esconderijo.","Quando alguém confia um segredo, você o arquiva mentalmente num cofre de várias chaves.","Você gosta de encontros misteriosos. Se a outra pessoa faz uma surpresa, seu sorriso indica que você já considerou doze cenários românticos.","Por trás do ar misterioso, você guarda com ternura a lembrança de um elogio recebido na hora certa.","Mensagens curtíssimas deixam você pensativo: « tá bom » pode conter uma trama inteira.","Seu carinho parece um romance envolvente, com um protagonista discreto que já conhece o fim do capítulo.","Seu olhar intenso transforma três segundos de conversa em cena de cinema. A pessoa só procurava o saleiro.","Você adora declarações profundas, especialmente quando começam com oito compassos de silêncio. O café esfria esperando a primeira fala.","O ciúme faz visita-relâmpago: você percebe um sorriso e depois lembra que todo mundo pode ser educado.","Você segura a mão da outra pessoa com intensidade de romance. Ela tenta descobrir discretamente se você conhece o final do livro."],"wellbeing":["Você escolhe o banco mais isolado do parque. Um pombo se aproxima e sua solidão recebe o primeiro visitante.","Você quer uma noite tranquila, mas o vizinho que moveu uma cadeira acabou de criar um mistério.","O livro escolhido para relaxar contém dez segredos. Você se sente em casa.","Uma sala com cortinas fechadas parece um refúgio. Você encontrou uma paz que o lustre nem foi convidado a comentar.","Uma xícara quente acompanha suas reflexões; ela não sabe que está sendo interrogada em silêncio.","Por trás da necessidade de ficar só, um cobertor e uma série antiga formam sua equipe de confiança.","Quebra-cabeças acalmam você, desde que ninguém esconda de propósito a última peça.","Seu relaxamento ideal não tem surpresas. Por isso, você verifica duas vezes debaixo da almofada.","Seu lugar favorito para respirar parece esconderijo de conto de fadas. Só a luminária regulável tem permissão para entrar.","Para relaxar, você fecha as cortinas e deixa o mundo lá fora. O celular recebe ordem oficial para ficar calado.","Você achou um terraço vazio para se recompor. Duas cadeiras desocupadas já dão a impressão de ter um castelo secreto.","Previsão interior: névoa tranquila, canto sombreado ideal e alta chance de responder 'estou aproveitando o silêncio' de outro cômodo."],"wisdom":["Sua intuição às vezes precisa de férias; a torradeira não é suspeita.","Você pode fazer uma pergunta sem montar uma sala de interrogatório.","Mistérios são fascinantes, mas nem todo envelope esconde uma conspiração.","Virar a página fica mais fácil quando você aceita não escrever um prefácio de catorze capítulos.","Uma confidência não exige necessariamente senha de seis dígitos.","Por trás de todo silêncio não há revelação; às vezes, alguém só está mastigando.","Transformar-se às vezes significa mudar o fim da história. Os personagens antigos podem ficar fora do novo capítulo.","Confiar não exige verificar toda hora a fechadura do cofre.","Perdoar não apaga a história; só evita relê-la a cada café da manhã.","É possível se tornar alguém novo sem fazer cerimônia de despedida para cada hábito antigo.","Uma página virada continua existindo. Só deixa de servir como marcador em todas as seguintes.","Renovar-se às vezes é abrir as janelas de um quarto que você preferia manter na sombra."],"roast":["Você ainda lembra quem mudou sua xícara de lugar numa festa do ano passado. A xícara já superou isso.","Você guarda segredos tão bem que até quem contou esquece que confiou em você.","Um simples « visualizado » sem resposta vira o primeiro capítulo de um romance de espionagem.","Quando alguém diz « não foi nada », você prepara imediatamente um mapa dos suspeitos.","Uma mágoa antiga ocupa uma caixa cuidadosamente etiquetada com data exata.","Um comentário levemente irônico volta à sua cabeça em cada reunião familiar. A pessoa o esqueceu antes da sobremesa.","É difícil surpreender você: já está interrogando as fitas do embrulho.","Você é tão discreto que até o vizinho misterioso do romance acha você fechado demais.","Sua memória guarda pequenas ofensas melhor que um calendário. A agenda perdeu uma reunião; você, nenhuma.","Você diz 'sem problema' com a serenidade de quem acaba de gravar o problema numa placa comemorativa.","Você perdoou o atraso de um amigo. Só relembra o feito sempre que um relógio bate.","Uma brincadeira desagradou você há muito tempo. O grupo mudou de assunto; você prepara o discurso final agora."]},"piquant":{"career":["Sua desconfiança transforma um café compartilhado numa operação de inteligência. O açúcar entra na ficha como possível cúmplice.","Você examina uma simples mudança de horário como transferência clandestina de poder. A agenda pede advogado.","O colega que escreveu « falamos amanhã » acaba de abrir uma investigação de doze horas. Amanhã ainda nem começou.","Quando alguma informação escapa, você monta uma equipe especial. O segredo era a escolha dos biscoitos.","Uma reunião a portas fechadas desperta seu instinto de detetive. A sala discutia manutenção de cadeiras.","Por trás da sua calma estratégica, um arquivo invisível classifica os suspiros da equipe. A copiadora ocupa o primeiro lugar.","Sua estratégia prevê três jogadas à frente, quatro hipóteses e uma saída discreta. O projeto era só renomear uma pasta.","Você estudou os movimentos da fotocopiadora como rede de inteligência. Sua missão secreta era ficar sem papel.","Você antecipou três decisões da diretoria antes do café. A diretoria só procurava uma sala com tomadas suficientes.","Sua estratégia no escritório parece operação de espionagem. A sala secreta guardava apenas canetas azuis.","Últimas notícias: um arquivo foi movido. Você mobilizou um gabinete de crise e o achou na pasta 'arquivos movidos'.","Relatório fictício de segurança: você conhece todos os segredos do setor. Só resta o mistério da utilidade das reuniões de sexta."],"love":["Sua intensidade transforma um simples « até depois » num caso delicado. A palavra « depois » fica sob vigilância.","Você afirma confiar e depois verifica se a surpresa preparada é realmente surpresa. O papel de presente pede advogado.","A mensagem sem ponto-final intriga tanto quanto a mensagem com ponto. A pontuação é convocada nos dois casos.","Quando a outra pessoa diz 'tive um bom dia', você sustenta o olhar como se ela revelasse um segredo antigo. Era só uma conversa carinhosa.","Uma observação antiga permanece arquivada na memória. Tem número de protocolo e data de revisão.","Seu ciúme transforma um sorriso ao garçom numa ópera silenciosa. Ele só queria recolher os pratos.","As confidências tocam você, mas seu ar grave imediatamente as classifica como « ultrassecreto ». O carinho espera autorização.","Seu coração adora profundidade; uma conversa sobre o tempo às vezes termina com interrogatório das nuvens.","Seu olhar daria drama a um simples pedido de pão. A pessoa na padaria achou que participava de um suspense romântico.","Você chama isso de carinho intenso. A outra pessoa atravessa um corredor de olhares sugestivos só para escolher uma xícara.","'Essa pessoa conhece você?' 'Quase nada.' Sua sobrancelha já publicou um romance inteiro sobre a resposta.","Seu ciúme chega em silêncio, como personagem misterioso no fundo do restaurante. Logo ocupa mentalmente todas as mesas."],"wellbeing":["Sua necessidade de controle transforma uma caminhada tranquila numa ronda de vigilância. Os pombos são suspeitos de coordenação.","Você busca paz num cômodo vazio e depois se pergunta por que ele está vazio. A cadeira precisa apresentar álibi.","Você reservou uma hora de solidão num quarto escuro. Qualquer raio sob a porta é tratado como visitante sem convite.","Você diz amar o silêncio e escolhe um canto tão secreto que a poltrona nem sabe que hospeda você. A tranquilidade permanece anônima.","Um chá calmante parece misteriosamente calmo demais. O saquinho é submetido a interrogatório.","Por trás do seu silêncio, hipóteses disputam a razão exata do último suspiro do vizinho. O relógio não quer testemunhar.","Dias sem imprevistos preocupam você quase mais que os outros. O calendário se esconde sob a capa.","Para recarregar as energias, você desaparece da sala. Três cômodos depois, declara a esconderijo uma zona soberana de silêncio.","Você gosta tanto de ficar só que pensa em dar um segundo quarto à solidão. O primeiro já foi classificado como confidencial.","Avaliação: 'Lindo espaço de descanso, mas o ocupante só se comunica movendo as cortinas'. Cinco estrelas para o silêncio.","Você apagou todas as luzes para ter paz. O raio sob a porta foi expulso por excesso de intimidade.","Seu cantinho de descanso tem mais mistérios que um castelo antigo. Grande segredo: uma xícara de chá e vontade de não ver ninguém."],"wisdom":["Perdoar às vezes é retirar uma pedra do caminho. Você começou exigindo uma planta detalhada da paisagem nova.","Você não procura respostas: submete o acaso a um interrogatório.","O mistério nem sempre esconde traição. Às vezes, é só uma gaveta fechada.","Mudar é parar de pintar uma porta fechada. Você encomendou uma paleta para a próxima vida dela.","Uma intuição brilhante não é automaticamente testemunha confiável. O júri exige provas.","Renascer não é repetir a mesma cena com cenário mais sombrio. Você já escolhe as cortinas novas.","Os segredos sabem se guardar sozinhos. Mesmo assim, você construiu um bunker para eles.","Confiar não significa contratar um detetive para vigiar a própria confiança.","Perdoar não é aprovar o roteiro antigo. Você exigiu os créditos completos antes de mudar de filme.","O renascimento começa quando sua versão antiga para de dirigir a próxima. Você deixou a cadeira do diretor com ela.","Transformar a vida às vezes exige abrir uma porta. Você ainda estuda o simbolismo da maçaneta.","Ninguém fica livre morando eternamente numa cena antiga. Você mudou os enfeites, mas preservou o cenário."],"roast":["Sua mágoa é tão bem arquivada que tem departamento de registros e atendimento ao público.","Você confia nas pessoas como um cofre confia numa chave perdida.","Você guardou um comentário banal por três temporadas. O autor trocou de celular; sua mágoa ainda tem o número antigo.","Quando alguém diz « surpresa », você procura imediatamente o vazamento de informação. O presente continua embalado.","Você não esquece pequenos aborrecimentos: guarda todos como edições limitadas. A prateleira das reconciliações quase não tem nada.","Uma brincadeira fora de hora entrou na coleção de contrariedades históricas. O autor já ria de outra coisa; você está no volume dois.","Os segredos adoram sua companhia: ganham placa, senha e horário de visita.","Seu perdão parece liberdade condicional. Até a cadeira movida continua sob vigilância.","Sua mágoa tem um calendário de comemorações. Um comentário sobre o tempo ganhou dia oficial de lembrança.","Você perdoou um pequeno aborrecimento e anuncia isso a cada encontro há três anos. O perdão virou seu comunicado oficial.","Você não guarda rancor, garante. Seria simples demais. É o curador voluntário de um museu de frases infelizes.","Uma brincadeira inocente envelheceu na sua memória como documento histórico. O arquivo recusou registrá-la como evento importante."]},"roastMy":["Escorpião, você não ouve uma conversa: monta um dossiê. Uma pausa, um olhar e uma vírgula esquecida viram provas. Alguém pergunta onde estão os guardanapos. Você exige o nome das testemunhas.","Sua memória das ofensas parece um arquivo nacional, mas nada ali é encerrado. Você lembra de um comentário sobre sua playlist numa terça-feira chuvosa. Quem falou nem sabe que existe um processo. O departamento do perdão está fechado para inventário.","Você diz gostar de mistérios. Na verdade, suspeita que cada mistério esconda outro mistério que esconde mais alguma coisa. Investiga uma porta fechada. Era um armário, que agora exige testemunha para recebê-lo.","Seu olhar intenso faz o garçom do café se sentir numa audiência. Ele só queria saber se você prefere sentar perto da janela. Você responde depois de observar as saídas. O garçom pediu transferência para o balcão.","Você distribui confiança com a generosidade de um cofre bancário num feriado. Para receber uma confidência, exigem-se chave, código e recomendação. Depois que o vínculo existe, você protege tudo com fidelidade impressionante. Até o peixe dourado precisa assinar acordo de confidencialidade.","Você adora entender tudo, principalmente quando ninguém esconde nada. Uma pessoa responde « sim » e você analisa tom, demora e ausência de emoji. Sua investigação conclui que existe grande segredo. Ela só quis dizer sim.","Sua calma às vezes preocupa os objetos. Você observa uma xícara derramada com a seriedade de um detetive internacional. A mesa é interrogada, o pano é suspeito e o café recusa a reconstituição. O gato recebe imunidade por falta de provas.","Você garante que virou a página. É verdade: virou e colocou marcador, além de guardar uma cópia. Três temporadas depois, um comentário parecido reabre o processo. O tribunal das lembranças se reúne a portas fechadas.","Seu amor por segredos transforma uma surpresa com bolo numa missão confidencial. Você não revela hora, lugar nem cor dos pratos. Os convidados chegam separados com instruções codificadas. O bolo pede um convite simples.","Você gosta de relações profundas, mas uma pergunta inocente logo assume importância histórica. Perguntam como foi seu dia e você responde com um silêncio cheio de significado. A pessoa espera o resto. Até o silêncio exige intérprete credenciado.","Escorpião, você participou de uma gincana em equipe. Já conhecia passagens discretas, saídas laterais e modos de contornar obstáculos. Os outros admiravam sua estratégia. Então descobriram que você procurava uma pista que nem estava no jogo.","Você decidiu ter uma noite leve com amigos. Um comentário fez sua sobrancelha subir, mas você continuou rindo. Duas semanas depois, repetiu exatamente a frase e a entonação. A festa acabou; sua memória oferecia reprise.","Seu gosto pelo sossego é tão refinado que transforma uma viagem simples em território de solidão escolhida. Você ocupa o assento mais silencioso e contempla a paisagem sem falar. Um amigo propõe um jogo. Você aceita, desde que as cartas saibam guardar segredo.","Você adora conversas sinceras, sobretudo as profundas. Alguém conta que mudou um abajur de lugar e você pergunta o que isso revela sobre suas aspirações. A pessoa reflete por um minuto. Só queria reorganizar a sala; agora o abajur é símbolo de transformação.","Você resolveu encerrar um velho aborrecimento. Escreveu tudo num papel, dobrou e guardou numa caixa como fim do capítulo. Quase poético. Depois etiquetou a caixa: 'Não abrir mais, exceto se surgir algo a esclarecer'."]},"sagittarius":{"classic":{"career":["Seu gosto pela liberdade traz ar novo a projetos que precisam sair da rotina.","Uma ideia ambiciosa às vezes merece um roteiro mais preciso para alcançar o objetivo.","Sua franqueza ganha força quando você escolhe o momento certo de expressá-la.","Quando a rotina pesa na sua motivação, busque nas tarefas uma oportunidade de aprender.","Seu entusiasmo contagiante pode ajudar a equipe a imaginar horizontes mais amplos.","Por trás da vontade de avançar depressa existe uma habilidade valiosa para ligar ideias distantes.","No trabalho, sua necessidade de autonomia funciona melhor com compromissos claramente definidos.","Explorar um novo método pode alimentar sua criatividade sem dispersar os esforços."],"love":["Sua necessidade de espaço não exclui uma presença sincera com quem importa.","Uma palavra honesta aproxima mais quando também deixa espaço para ouvir.","A espontaneidade que move você traz frescor às trocas afetivas.","Quando a vontade de ir para outro lugar aparece, compartilhar esse desejo abre uma conversa mais profunda.","Seu otimismo natural pode iluminar uma relação sem apagar emoções mais discretas.","Por trás do seu gosto por aventura, você também procura vínculos que respeitem seu impulso.","No coração de uma relação, a confiança deixa cada um respirar sem precisar se justificar o tempo todo.","Aceitar um ritmo diferente do seu pode enriquecer uma cumplicidade preciosa."],"wellbeing":["Sua energia viajante encontra equilíbrio numa caminhada sem destino imposto.","Uma pausa entre dois projetos permite que seu entusiasmo dure sem se esgotar.","A liberdade também pode assumir a forma de uma tarde sem programação.","Quando sua mente corre para amanhã, preste atenção ao que está ao redor agora.","Seu impulso de descobrir pode se satisfazer com um lugar próximo que você ainda conhece pouco.","Por trás da necessidade de movimento, uma boa noite de sono também merece espaço.","No meio de mil possibilidades, às vezes escolha a simplicidade de um momento compartilhado.","Desacelerar por vontade própria não reduz seu horizonte; dá tempo para apreciá-lo."],"wisdom":["Sua liberdade cresce quando sabe cumprir a palavra dada.","Um horizonte distante começa pela atenção ao caminho presente.","A franqueza vale mais quando deixa uma porta aberta.","Toda aventura ganha sentido quando acolhe o retorno.","Seu otimismo avança melhor com referências do que com promessas.","Explorar nem sempre significa partir; ouvir pode bastar.","O verdadeiro entusiasmo também respeita os passos de quem acompanha você.","Nada diminui tanto o mundo quanto acreditar que já o compreendeu."],"roast":["Sua sede de liberdade às vezes faz você confundir qualquer organização com uma restrição desnecessária.","Uma promessa feita com entusiasmo merece mais do que uma lembrança vaga.","A verdade sai facilmente da sua boca, mas a embalagem pode chegar sem nenhum cuidado.","Quando uma conversa fica séria, sua mente já procura outra janela para abrir.","Seu otimismo admirável às vezes esquece de consultar os detalhes práticos.","Por trás da vontade de novidade, alguns projetos só estão esperando uma conclusão.","Diante de uma programação apertada, você parece procurar a saída de emergência.","Você gosta mais de partir rumo a novas ideias do que voltar para terminar as de ontem."]},"funny":{"career":["Sua necessidade de aventura transforma o caminho entre duas mesas numa expedição. Você já batizou o corredor de « rota das descobertas ».","Uma reunião de planejamento inspira uma ideia genial: sair antes de começar. O calendário não gostou.","Sua franqueza leva você a dizer que a apresentação tem quarenta slides de sobra. Você só contou os dois primeiros.","Quando pedem um plano de ação, você apresenta um mapa-múndi. A equipe só queria mudar a impressora de lugar.","Seu entusiasmo faz você aceitar cinco projetos antes do almoço. À tarde, pensa numa nova carreira como guia turístico.","Em home office numa varanda desconhecida, você entra na reunião com fundo virtual de escritório. As gaivotas não assinaram sigilo.","Ao ouvir « procedimento », você olha instintivamente para as saídas. Até o regimento acha a reação teatral.","Explorar possibilidades fascina você: sua lista de tarefas virou catálogo de destinos imaginários.","Comunicado: sua fala na reunião deve durar cinco minutos. Você gastou quatro explicando por que a reunião deveria ser em outro lugar.","Pedem um resumo de um workshop. Você volta com plano de conferência internacional e três slogans empolgados.","Seu escritório tem um mapa de fusos horários para organizar ligações. Os colegas percebem que você muda de fuso toda semana.","'Você pode prometer um prazo razoável?' 'Claro!' Só esqueceu de perguntar de que ano estavam falando."],"love":["Sua necessidade de liberdade é tão romântica que o convite para jantar inclui a opção « destino desconhecido ».","Uma declaração de carinho surge naturalmente, logo antes da sugestão de mudar de continente no fim de semana.","Você propõe uma noite a dois com uma cláusula: qualquer um pode mudar o programa quando quiser. O romance levou tênis confortáveis.","Quando você diz « vamos improvisar », seus próximos verificam discretamente a validade dos passaportes.","Um fim de semana romântico sem programação encanta você. A outra pessoa descobre que 'sem programação' inclui não ter hora de voltar.","Sua ideia de casal firme inclui duas chaves, duas agendas e porta sempre aberta. Só faltou dizer em que direção.","No restaurante, você descreve o futuro ideal: muito espaço, nenhuma rotina e sobremesas para dividir.","Prometer uma noite sem surpresa parece razoável. Você só reservou uma atividade secreta para depois do jantar.","Você gosta de relacionamentos que deixam espaço para respirar. Reservou até um horário chamado 'espontaneidade a dois'.","Ao planejar férias em casal, sugere duas rotas separadas que se encontram na sobremesa. Estranho, mas a sobremesa é compartilhada.","A palavra 'sempre' soa encantadora até vir acompanhada de um horário fixo.","Sua declaração romântica cabe num cartão-postal: 'Escolho você'. No verso, você desenhou três trilhas alternativas."],"wellbeing":["Seu descanso ideal parece uma trilha improvisada. O sofá pede uma chance de participar.","Uma caminhada de dez minutos vira exploração de três bairros e um desvio porque « aquela rua parecia interessante ».","A soneca parece parada demais. Você sugere tirá-la num trem para fazer duas coisas de uma vez.","Quando sugerem desacelerar, você pergunta imediatamente em que direção.","Seu entusiasmo matinal leva você a abrir as janelas como quem anuncia o início de uma grande aventura.","Por trás da vontade de fugir para longe está uma verdade: talvez bastasse mudar a poltrona de lugar.","Ao descansar, você liga um vídeo sobre um país distante. Três horas depois, o roteiro da viagem está pronto.","Tomar um ar faz bem. Você volta com seis ideias de viagem e nenhuma ideia de que horas são.","Sua mala fica entreaberta 'caso seja preciso'. Dentro há garrafa d'água, blusa e vontade de atravessar a cidade a pé.","Um banco ao ar livre deveria acolher sua pausa. Você preferiu a trilha que continua depois da colina.","Você tenta um dia calmo em casa. Ao meio-dia já percorreu o bairro e cumprimentou duas estações.","Sua previsão ideal tem vento, quilômetros e uma boa desculpa para trocar de calçado."],"wisdom":["A melhor filosofia do mundo às vezes cabe numa pergunta: você terminou o que começou?","Uma promessa é uma lembrança que convém anotar antes de partir.","A verdade sai mais bonita quando não entra correndo.","Todo horizonte merece uma visita; a roupa para lavar também espera a sua vez.","Seu otimismo pode mover montanhas, mas não encontra suas chaves.","Explorar o mundo é nobre; achar o carregador também é.","A aventura às vezes começa por conferir o horário do encontro.","Nada proíbe a espontaneidade, nem mesmo uma agenda aberta.","Uma ideia grandiosa vale mais quando resiste ao primeiro detalhe pequeno.","A pessoa sábia enxerga longe. Também confere se amarrou os cadarços antes de sair.","A vida oferece muitas possibilidades. Algumas têm a discreta etiqueta 'pendente'.","Sua filosofia abre portas; confira de vez em quando se dão acesso a alguma sala."],"roast":["Você aceitou jantar, show e noite de jogos para a mesma sexta-feira. Sua agenda parece romance sem capítulo final.","Um convite com horário exato já parece autoritário demais para você.","Você descreve seus planos do fim de semana com tanta certeza que os amigos anotam 'sujeito a mudança de universo'.","Quando você promete « cinco minutinhos », todos entendem « talvez neste trimestre ».","A cada convite novo, você diz sim antes de conferir os três anteriores. Sua agenda entrou no modo ficção.","Por trás da recusa da rotina existe outra rotina bem regular: fugir da rotina.","Sua frase favorita é 'eu aviso'. O aviso saiu para fazer trilha e nunca mais deu notícias.","Sair sem saber para onde vai encanta você. Voltar sem as compras encanta bem menos os outros.","Você promete passar 'rapidinho'. O vento chegou, deixou recado e foi mais pontual.","Seus amigos já não confirmam convites: esperam para ver qual aventura vencerá a eleição da noite.","Um lanche de uma hora ganhou caminhada, visita imprevista e mensagem de desculpas para o próprio lanche.","Você esquece o local de um encontro enquanto lembra perfeitamente da ideia genial que o substituiu."]},"piquant":{"career":["Você anuncia decisões na reunião como apresentador de última hora. A ata descobre as consequências durante a impressão.","Uma orientação precisa faz você querer revolucionar o setor. Só pediram para renomear um arquivo. O arquivo pediu asilo.","A franqueza é sua especialidade: você anuncia que o projeto é absurdo antes de ler a primeira página. A página prepara resposta oficial.","Quando entregam um documento, seu entusiasmo sai imediatamente em busca de outro. O primeiro foi declarado desaparecido em missão.","Seu entusiasmo promete uma entrega grandiosa. Ao descobrir a lista de tarefas, sugere outra cerimônia de lançamento.","Você oferece home office nômade como solução para tudo. A equipe descobre que seu fuso horário é uma surpresa diária.","Ao primeiro relatório, você proclama a independência da sua mesa. Os materiais pedem referendo.","Explorar parece mais nobre que terminar. Sua pasta « ideias brilhantes » inaugurou um museu de conclusões ausentes.","Últimas notícias: você prometeu um projeto 'simples e rápido'. O escopo descobriu que essas palavras eram ficção.","Você trabalha de um trem e chama isso de flexibilidade. A internet entrou na viagem sem passagem de volta.","'O plano está aprovado?' 'Em espírito, sim.' Seu espírito esqueceu de avisar quem teria de executá-lo.","Você entra na reunião com uma verdade brutal e sai com cinco tarefas imprevistas. Sua franqueza fabrica pendências."],"love":["Sua liberdade vem sempre antes dos encontros. Até seu calendário precisa agendar hora para chegar perto de você.","Uma promessa romântica escapa com a facilidade de um discurso oficial. O departamento de compromissos procura seu endereço.","Você vê exclusividade como recurso opcional do namoro. Curiosamente, a outra pessoa quer ler as condições antes de clicar.","Quando uma relação pede um simples horário, você enxerga um tratado internacional. As negociações ainda discutem a palavra « quinta-feira ».","Você marca um encontro romântico e deixa três saídas 'por precaução'. Parece exercício de evacuação, não encontro.","Por trás do charme aventureiro existe uma cláusula em letras pequenas: disponibilidade conforme o clima e a vontade do momento.","Ao ouvir « hábito », você já imagina uma central de crise. Só estavam falando de tomar café da manhã juntos.","Prometer previsibilidade por cinco minutos custa caro para você. Seu temporizador fugiu antes do terceiro.","Seu casal ideal: muito carinho, poucas obrigações e saída de emergência decorada. Até o mapa de evacuação é romântico.","Seu grande gesto amoroso é dar uma passagem flexível. 'Não reembolsável' parece insulto pessoal.","Comunicado: seu coração aceita aproximações desde que mantenha uma autonomia excessiva até para um satélite.","Você ama o 'nós' enquanto isso nunca substitui o 'faço o que eu quiser'. De namoro virou negociação de fronteiras."],"wellbeing":["Sua incapacidade de ficar quieto transforma qualquer pausa em missão de reconhecimento. O banco público exige indenização pelo transtorno.","Um dia sem planos parece suspeito. Você cria um roteiro para conferir se continua livre.","O descanso interessa desde que aconteça em outro lugar. Sua poltrona contratou um detetive para localizar o dono.","Quando sugerem uma caminhada tranquila, você corre para a trilha mais distante. A palavra « tranquila » devolveu o crachá.","Seu descanso começa com caminhada, vira excursão e termina numa estação. O repouso perdeu a conexão.","Por trás da sua obsessão pelo longe, até uma janela aberta parece campanha de expansão territorial.","Ao deitar, você olha um mapa para « desligar a mente ». Seu travesseiro pediu passaporte.","Desacelerar contraria tanto sua reputação que você chama descanso de « exploração horizontal ». O sofá recusa o comunicado.","Sua mala tem um compartimento para decisões espontâneas. Ocupa metade da casa.","Você chama de 'pausa na natureza' uma expedição com três conexões de transporte. O banco do jardim foi rebaixado oficialmente.","Previsão interior: inquietação persistente, risco alto de desvio panorâmico. A poltrona saiu do mapa.","Você compra um guia de caminhadas tranquilas. Três páginas depois já planeja atravessar o país."],"wisdom":["Sua filosofia vê sempre o copo meio cheio. Principalmente quando esquece quem deveria enchê-lo.","Pensar grande não dispensa terminar as coisas pequenas. Sua teoria tem um portal magnífico e nenhum jardim.","Otimismo sem nuance é cartão-postal enviado de uma obra ainda interditada.","Uma certeza filosófica não é prova. Seu entusiasmo já emoldurou a conclusão.","Seu otimismo tem mapa-múndi e nenhum endereço de retorno.","Explorar sem concluir é colecionar começos em vitrines.","A aventura não foge de você: só espera a confirmação do horário.","Nada prende tanto você quanto a rejeição teatral aos horários.","Seu otimismo encontra horizonte em toda parede. Seria útil distinguir janela de cartaz.","A grandeza das ideias não se mede em pontos de exclamação. Sua filosofia, porém, tem sirene.","Você procura o sentido da vida com a confiança de um guia cujo mapa continua em branco.","A esperança é preciosa. Transformá-la em garantia é trabalho do marketing das suas convicções."],"roast":["Você confirma presença com entusiasmo espetacular. Duas horas depois, uma atividade misteriosa 'chamou' você. Os outros suspeitam que sua imaginação tenha telefone.","Uma reserva simples parece ameaça aos direitos fundamentais. O restaurante encaminhou o caso às autoridades imaginárias.","Você promete não esquecer nada desta vez. A frase já aparece em quatro convites abandonados.","Quando anuncia « estarei lá », até seu relógio cai na risada. O fuso horário pede perícia.","Sua agenda tem mais reticências que compromissos cumpridos. Os três pontinhos ganharam cargo efetivo.","Você tem uma ideia brilhante para cada sábado. A ideia do sábado anterior ainda espera na chuva, segurando um bolo inteiro.","Diante do primeiro formulário, você grita contra a ditadura administrativa. Só precisava escrever seu nome.","Partir fascina você, ficar preocupa, voltar entedia. Até seu capacho já não reconhece o patrão.","Você cancelou o jantar por 'uma oportunidade única'. Foi a terceira oportunidade única da semana. O dicionário prepara outra edição.","Seu 'deixa comigo' é lenda oral. Historiadores ainda procuram um exemplo comprovado.","Toda novidade toma o lugar do seu plano. Você não tem agenda: promove testes de elenco permanentes para o papel de sábado.","Você começa cinco aventuras e promete novidades de cada uma. O grupo de mensagens virou museu de primeiras fotos."]},"roastMy":["Sagitário, você ama tanto a liberdade que até o despertador precisa pedir autorização. Aceita três convites com entusiasmo histórico. Quando chega o dia, sai para outro lugar « por instinto ». Os convites fundaram a associação dos abandonados pela sua agenda.","Sua mala está pronta, mas sua lista de compras nunca. Você planeja uma viagem imaginária enquanto pedem que compre pão. Volta com uma história sobre caminhos alternativos. A padaria prepara comunicado de desaparecimento.","Sua franqueza entra numa conversa como caminhão de mudança sem agendamento. Você diz exatamente o que pensa e depois passa vinte minutos explicando por que isso foi corajoso. Os outros só queriam opinião sobre a toalha. A toalha exigiu direito de resposta.","Sagitário, você faz promessas com a sinceridade de um discurso histórico. Duas horas depois, descobre uma paixão nova e muda de rumo. Seus compromissos se reúnem mensalmente para tentar localizar você. Acabaram de marcar sua presença como facultativa.","Seu otimismo conseguiria anunciar « ótima notícia » diante de uma porta fechada. Você procuraria janela, caminho e oportunidade de aventura. A porta só queria que você lesse « puxe ». Uma comissão investiga seu senso prático.","Você detesta regras, especialmente as que propôs ontem. O plano do dia se resume a « seguir a inspiração ». Ao meio-dia, a inspiração foi embora sem avisar. Sua lista de tarefas agora publica calendário de desaparecimentos.","Sua necessidade de espaço transforma o menor compromisso em incidente diplomático. Pedem confirmação para um jantar e você discursa sobre independência. Ninguém quer prender você. É só uma reserva para quatro.","Você filosofa sobre o sentido da vida enquanto o forno apita. Sua palestra atravessa liberdade, destino e civilizações esquecidas. A comida espera há meia hora. Acaba de ganhar status de ouvinte involuntária.","Você adora novos começos, caminhos desconhecidos e ideias gigantescas. Terminar algo parece muito menos poético. A estante tem vinte cadernos começados e uma única caneta esgotada. A caneta pede medalha por serviços prestados.","Sagitário, sua espontaneidade tem comunicado oficial: « Nada está previsto, tudo é possível ». Você chega atrasado, sugere outro lugar e anuncia um desvio maravilhoso. Seus amigos não precisam de guia. Precisam de uma central de coordenação de deslocamentos.","Você adora anunciar aventuras grandiosas antes de achar os sapatos. No trabalho, uma reunião curta vira manifesto sobre novos horizontes. No amor, promete presença livre de qualquer compromisso. Sua única constante é o ponto de interrogação ao lado do nome nos convites.","Seu entusiasmo já reservou três atividades antes de escolherem a data. Você sugere viagem romântica em que cada um pode mudar de país. Para relaxar, pega a estrada sem conferir a distância. O GPS agora mostra 'aventura pessoal', não o horário de chegada.","Você explica a vida com a segurança de filósofo em turnê mundial. Depois esquece o aniversário do projeto cujo lançamento celebrou. Seus amigos nem se preocupam com as mudanças de planos. Trocaram seu nome por 'talvez' nos contatos.","No escritório, você diz em voz alta o que os outros nem tiveram tempo de pensar. No namoro, negocia a independência de cada domingo. Seu descanso é descobrir caminhos novos. Você prova que é possível se movimentar muito sem preencher um formulário sequer.","Você prometeu passeio calmo e preparou desvios 'opcionais'. Sua energia transforma o trajeto em epopeia e a epopeia em pretexto para outra coisa. Você tem toda uma filosofia sobre aproveitar o instante. Mas o instante de confirmar o encontro segue desaparecido."]},"capricorn":{"classic":{"career":["Sua perseverança dá aos projetos complexos uma estrutura com que todos podem contar.","Um objetivo ambicioso ganha quando é dividido em etapas realistas e compartilhadas com clareza.","Sua disciplina ajuda a distinguir o essencial das urgências passageiras.","Quando os resultados demoram, lembre-se do valor do caminho já percorrido.","Seu senso de responsabilidade inspira confiança, desde que também deixe espaço para iniciativas dos outros.","Por trás do seu jeito sério existe uma ambição profunda: construir algo duradouro.","No trabalho, delegar parte dos detalhes pode liberar sua atenção para decisões importantes.","Construir um projeto com paciência às vezes exige tanta flexibilidade quanto disciplina."],"love":["Sua reserva afetiva costuma esconder grande constância nos gestos do dia a dia.","Um vínculo sólido também se alimenta de momentos espontâneos, sem metas a cumprir.","A fidelidade aos compromissos dá profundidade às relações que importam.","Quando as palavras parecem insuficientes, um cuidado sincero pode transmitir muita coisa.","Sua necessidade de segurança pode conviver com o prazer de descobrir a outra pessoa de novo.","Por baixo da aparente discrição, suas emoções merecem um espaço que não se mede.","Na cumplicidade, nem sempre você precisa solucionar aquilo que a outra pessoa confidencia.","Compartilhar um momento sem planejamento pode aproximar você de quem aprecia sua presença."],"wellbeing":["Seu senso de dever merece pausas que não sejam tratadas como prêmios a conquistar.","Um momento de calma pode ser precioso mesmo sem produzir resultado visível.","A disciplina ajuda você, mas não exige ocupar cada minuto.","Quando sua mente antecipa a semana inteira, volte simplesmente ao ritmo da respiração.","Seu gosto por organização pode ajudar a proteger tempo para um descanso verdadeiro.","Por baixo da ambição, valorize também prazeres sem utilidade mensurável.","Entre tantos compromissos, uma caminhada sem relógio pode oferecer outra relação com o tempo.","Desacelerar não apaga sua determinação; permite que ela continue serena."],"wisdom":["Seu valor não se resume à lista das suas conquistas.","Um cume conserva o sentido quando sabemos admirar a paisagem.","A solidez de um projeto também se mede pela capacidade de evoluir.","Todo trabalho merece espaço; o descanso também.","Uma ambição pode crescer sem ocupar todo o horizonte.","Construir o futuro não obriga a perder o presente.","A confiança cresce de forma diferente do controle constante.","Nada duradouro se constrói esquecendo quem compartilha o caminho."],"roast":["Seu gosto por controle às vezes transforma pequenos imprevistos em problemas a resolver com urgência.","Um objetivo pessoal pode acabar ocupando todo o espaço reservado ao prazer de viver.","Sua disciplina funciona tão bem que se torna difícil aceitar uma simples aproximação.","Quando sugerem um passeio espontâneo, sua primeira reação é conferir o calendário.","Seu reflexo de calcular o retorno faz você avaliar um lazer como se fosse outra missão.","Sob seu ar sério, é difícil saber quando você realmente permite a si mesmo fazer uma pausa.","Diante da menor mudança de programação, você já procura quem vai atualizar a agenda.","Organizar todos os detalhes tranquiliza você, mas às vezes deixa pouco espaço para boas surpresas."]},"funny":{"career":["Seu plano de carreira já tem o próximo cargo, o seguinte e o discurso de agradecimento. Você ainda hesita sobre a cor do fichário.","Um colega sugere uma ideia espontânea. Você responde com um cronograma tão detalhado que a espontaneidade ganhou data de entrega.","A reunião começa com três metas. Você preparou uma planilha para acompanhar as metas da planilha.","Quando faltam canetas no escritório, você abre uma investigação sobre o consumo trimestral. A caneta azul se recusa a depor.","Esse relatório de atividades empolga você tanto que considera encaderná-lo para mostrar às visitas.","Debaixo da tela, os lembretes adesivos estão alinhados por prioridade. Até a palavra « urgente » tem número de ordem.","Enquanto todos comemoram o fim do projeto, você propõe uma reunião sobre melhorias na comemoração.","Planejar a carreira acalma você: o cargo que quer daqui a dez anos já está nos favoritos.","Sua ambição cabe em cinco colunas e três reuniões. Alguém escreveu 'a avaliar' na última; você organizou um workshop sobre a expressão.","Você prepara a avaliação anual com a eficiência de um lançamento espacial. O foguete só precisa de uma planilha de competências.","'Você tem planos para amanhã?' 'Para os próximos sete anos, sim.' A pergunta parecia curta demais.","Sua apresentação termina com 'próxima etapa'. Você acrescentou dez slides explicando por que essa etapa não será a última."],"love":["Seu romantismo se expressa por reserva confirmada, guarda-chuva extra e trajeto otimizado.","Uma surpresa amorosa agrada a você, desde que chegue à agenda três dias antes.","O carinho deixa você generoso: já comparou as garantias dos possíveis presentes.","Quando perguntam o que você sente, responde primeiro « é sério ». O resto vem depois da aprovação.","Um jantar à luz de velas inspira uma planilha com os melhores lugares. A sobremesa tem sua própria coluna.","Por trás da calma, você prepara uma declaração muito comovente. O documento chama « versão_final_7 ».","No começo de uma história, você já pensa na organização dos fins de semana. A outra pessoa só procurava o casaco.","Dividir seu sofá é grande prova de confiança: você até liberou um lugar no braço da poltrona.","Você demonstra carinho pensando nos detalhes do futuro. A outra pessoa descobre que já aparece na previsão de piqueniques.","Você gosta tanto da primeira conversa que escolhe mentalmente a louça dos aniversários futuros. Guardou a garantia.","Sua expressão carinhosa favorita é 'confiável'. Levou um bom tempo para escrevê-la num cartão com duas flores.","Uma declaração espontânea emociona você. Depois pergunta com ternura se a bela ideia veio para ficar."],"wellbeing":["Seu descanso começa exatamente às 14h00. Às 14h03, você verifica se está avançando conforme o planejado.","Uma caminhada sem destino parece suspeita. Você acaba medindo o progresso com um aplicativo.","A soneca atrai você, mas ainda está decidindo entre quinze e vinte minutos para otimizar o rendimento.","Quando faz uma pausa, sua lista de tarefas registra « pausa realizada » com satisfação visível.","Esse momento de relaxamento exige dois lembretes e uma caixinha marcada. A almofada só queria que você se sentasse.","Você organizou uma noite sem obrigações. Às oito, marca 'não fazer nada' com a seriedade de gerente de projetos.","No parque, você agenda três paradas contemplativas de mesma duração. Os pombos não respeitam nenhum horário.","Desacelerar exige tanto esforço que você pensa em se parabenizar no balanço semanal.","Sua estadia no campo tem um plano de descanso ilustrado. O pôr do sol ainda não se inscreveu no workshop.","Você achou um método para aproveitar as férias: cronometrar o tempo que passa sem olhar para o relógio.","A caminhada relaxante tem três etapas e uma pausa opcional. Você é o único caminhante com planilha de acompanhamento.","Sua poltrona foi reservada das quatro às quatro e vinte. Parece feliz por ter uma existência administrativa."],"wisdom":["Seu painel de indicadores não mede a qualidade de uma gargalhada.","Um domingo sem produtividade continua sendo um domingo bem aproveitado.","O que se constrói com paciência costuma durar mais que o que se inaugura com uma fita gigante.","Qualquer cume pode esperar você terminar o lanche.","Sua ambição sabe contar; sua poltrona sabe acolher.","Construir um futuro sólido não impede perder uma meia.","Ter sucesso não exige ata de reunião em cada almoço.","Nada prova que uma pausa precise apresentar comprovante.","Chega-se ao topo passo a passo. Nada impede de admirar uma flor pelo caminho.","Persistência é talento; não obriga ninguém a subir todos os degraus de toda escadaria.","A paciência constrói pontes. Só evite montar um pedágio no meio.","Até a montanha leva seu tempo. E não escreve relatórios de crescimento."],"roast":["Você calculou o preço de uma caminhada pelo número de passos gratuitos. O resultado é favorável, desde que não compre nada.","Um presente inesperado faz você sorrir. Depois pergunta se a garantia é transferível.","A frase « vamos ver no que dá » parece mais assustadora que um filme de suspense.","Quando alguém diz « aproveite o momento », você pergunta a qual período se refere a avaliação.","Seu orçamento de compras considera o preço dos biscoitos até o último centavo. O biscoito quer negociar.","Sob sua fantasia de pessoa responsável, uma criança interior ainda espera aprovação do setor financeiro.","Na festa de fim de ano, você propõe um balanço anual da diversão. Os convidados fingem não ouvir.","Na sua casa, a espontaneidade acontece apenas nos dias programados para ela.","Você sabe o preço das canetas por unidade, pacote e década. A caneta grátis ganhou seu respeito eterno.","Na feira, você compara o preço das maçãs centavo por centavo. O vendedor oferece uma calculadora como cesta.","Um desconto de três por cento ilumina seu dia. Você pensa em emoldurar o recibo.","Para você, uma boa oferta merece relato épico. Seus amigos ainda esperam o capítulo sobre os dois reais economizados."]},"piquant":{"career":["Sua ambição já tem organograma antes mesmo de ter uma ideia. As ideias agora precisam passar por entrevista.","Um colega menciona o fim de semana: você imediatamente pergunta pela taxa de produtividade. O sábado pediu demissão.","Você escreveu seu plano de cinco anos antes de conhecer a equipe. Os colegas constam no anexo 'recursos a confirmar'.","Quando recebe uma tarefa simples, você cria um comitê gestor. A tarefa exige liberdade mediante fiança.","Seu planejamento de cinco anos prevê até os improvisos. A improvisação entrou com recurso por danos à reputação.","Sob sua seriedade, a pausa para o café é despesa a ser racionalizada. O café prepara demissão voluntária.","No primeiro imprevisto, você exige um responsável. O acaso aguarda audiência com o RH.","Você gosta tanto de organizar a empresa que classificou os sorrisos por frequência de uso. A felicidade perdeu o acesso.","Seu plano de cinco anos tem quadro de honra e procedimento de emergência. O presente recebeu apenas um contrato temporário.","Você transforma uma reunião de quinze minutos em comitê estratégico. O item 'bom dia' entra na fase de consulta.","Pesquisa fictícia: cem por cento das metas já têm prazos. Os colegas ainda procuram seus nomes no organograma.","Sua ambição já planejou a cerimônia de premiação. Os resultados não chegaram, mas a pauta está impecável."],"love":["Seu romantismo começa com um estudo de viabilidade. As borboletas imaginárias precisam apresentar três referências.","Você pensa no amor como uma construção duradoura. Pena que trata o primeiro encontro como vistoria de obra.","O carinho, para você, parece uma proposta cuidadosamente negociada. O buquê pede reunião com o jurídico.","Quando sugerem um jantar inesperado, você exige uma pauta. As velas entraram em greve.","Seu coração prudente não se abre: lança uma licitação. As inscrições se encerraram na terça-feira.","Por trás da discrição sentimental, um contrato de confiança já tem doze cláusulas. A espontaneidade não atende aos requisitos.","Uma palavra carinhosa toca você. Você a guarda numa pasta 'provas de seriedade', entre a reserva do jantar e o plano quinquenal.","Dividir seu futuro parece natural. Você imprimiu a versão preliminar antes mesmo de escolher a sobremesa.","Seu jeito de amar parece a construção de um farol: sólido, prudente e um pouco excessivo para escolher um jantar.","Você fala do futuro no terceiro encontro com a gravidade de um urbanista. A outra pessoa só queria sugerir um cinema.","Seu romantismo tem cláusula de continuidade. Até as borboletas do primeiro dia receberam plano de manutenção.","'Você pensa em nós?' 'Claro, já escolhi o nome da pasta.' O carinho merecia uma abertura menos burocrática."],"wellbeing":["Seu fim de semana de descanso tem quatro etapas obrigatórias e formulário de satisfação. A almofada desistiu na etapa dois.","Uma caminhada livre parece ineficiente. Você propõe otimizar o caminho entre duas árvores. As árvores recusam a fusão.","O relaxamento chega com crachá e horário rígido. Não foi admitido sem documento de identificação.","Quando o descanso começa, você confere a programação do descanso. A tarde termina atrasada para a própria tranquilidade.","Seu domingo tranquilo tem cronograma minuto a minuto. Até o bocejo precisa confirmar presença.","Debaixo do cobertor, você verifica se está aproveitando corretamente o tempo livre. O cobertor pede licença sabática.","No primeiro momento de tédio, você cria um projeto para melhorar o descanso. O descanso saiu do grupo.","Você reservou horário para contemplar a paisagem. No terceiro minuto, suspeita que a montanha não sabe se organizar.","Você criou uma planilha para férias perfeitas. A primeira fórmula mostra 'erro: espontaneidade insuficiente'.","Sua sessão de descanso tem pauta e horário de encerramento. O silêncio decidiu não participar.","Previsão para o lazer: céu aberto, alta pressão organizacional. A soneca se esconde atrás da agenda.","Você transformou a caminhada em três tarefas verificáveis. A árvore mais antiga do parque nunca viu auditoria assim."],"wisdom":["Sua ambição sobe uma montanha e pede promoção no topo.","A paciência constrói impérios. Não transforma todo pedregulho em conselho administrativo.","A prudência abriu uma consultoria dentro da sua cabeça.","O topo deve ser conquistado, diz sua filosofia. Só esqueceu que também há paisagem durante a subida.","Você confundiu constância com a obrigação de nunca afrouxar o cadarço.","Construir o futuro é nobre; mandar contas para ele, nem tanto.","Sua espontaneidade existe: está arquivada em « incidentes inesperados ».","Construir a longo prazo é admirável. Transformar cada pausa em fundação é coisa de arquiteto muito preocupado.","O topo não é escritório com vista melhor. Sua ambição, porém, já colocou uma placa lá.","Você cultiva a paciência como um jardim e depois mede cada folha com uma régua.","O que dura merece alicerces. Não precisa cimentar o chão em volta de todo sorriso.","Sua filosofia do progresso esqueceu a alegria dos desvios. O caminho é reto, mas a história é curta."],"roast":["Sua agenda não registra aniversários: trata-os como prazos contratuais. As velas aguardam a fatura.","Você compara o preço de duas sobremesas enquanto seus amigos já escolhem o café. A conclusão é que sair de casa não compensava.","Você calcula a rentabilidade do sofá desde a compra. O sofá exige direitos pelas horas extras.","Quando alguém fala em improvisar, seu olhar convoca um comitê de emergência. O imprevisto foge pela saída de incêndio.","Seu coração discreto tem mais firewalls que a rede de um banco. Elogios são bloqueados por atividade suspeita.","Sob sua seriedade existe um gerente de qualidade que avalia até surpresas. As surpresas pediram transferência.","Você calculou o custo de cada vela antes da comemoração. O bolo foi substituído por um gráfico de economia.","Organizar a felicidade numa planilha parecia sensato. A célula « alegria » acaba de mostrar erro de fórmula.","Você compara o custo de uma noite aos possíveis bons momentos. Sem recibo, a lembrança parece pouco rentável.","Últimas notícias: você achou como economizar em presentes. Seus familiares chamam a solução de 'uma ótima explicação'.","Seu cofrinho tem outro cofrinho para as economias. O terceiro foi promovido a chefe de controle de despesas.","A palavra 'grátis' empolga você mais que uma fanfarra. Mesmo assim, confere as letras miúdas."]},"roastMy":["Capricórnio, você não sai de férias: executa um plano operacional. O trajeto, a pausa e até a soneca têm códigos de cores. Seus próximos sugerem admirar o mar. Você pergunta qual objetivo estratégico isso cumpre.","Sua ambição é tão organizada que já conhece o título da sua autobiografia. Planejou capítulos, anexos e data de publicação. Só falta a parte « momentos em que me diverti ». A editora aguarda sua disponibilidade.","Você ama segurança, números e decisões sólidas. Quando alguém propõe uma noite improvisada, calcula os custos ocultos da alegria. O grupo sai sem você. Depois, você exige relatório do incidente.","Capricórnio, seu calendário não tem espaços em branco: até os brancos estão reservados. Você marcou um horário para ser espontâneo entre dois balanços. A espontaneidade não confirmou a inscrição. Você envia o último lembrete.","Sua relação com o dinheiro parece negociação permanente com cada objeto. Uma luminária agrada, mas você calcula quantos sorrisos renderá por uso. O vendedor pede para escolher uma cor. Você exige projeção de cinco anos.","Você parece sério até assistindo a uma comédia. Analisa a construção das cenas e a gestão do tempo. Todo mundo ri. Você anota que o rendimento cômico poderia melhorar.","Seu romantismo é confiável, mas tem estrutura administrativa. Você reserva, compara, confirma e verifica horários. A pessoa ao lado diz que isso é adorável. Você pergunta se ela quer assinar recibo de confirmação.","Capricórnio, você transformou o descanso em disciplina de alto nível. Define a duração da caminhada e as metas do fim de semana. Na volta, redige um balanço. Sua cadeira pede férias longe de você.","Sua perseverança merece respeito, mas você nunca abandona uma tarefa pela metade. O problema é que também se recusa a declará-la concluída. Até a lista de compras precisa passar pela comissão. A comissão não tem tempo de fazer compras.","Você é a única pessoa que considera necessário um relatório de aniversário. Decoração aprovada, horários cumpridos, biscoitos distribuídos com exatidão. Os convidados cantam para você. Você acrescenta « entusiasmo não previsto » ao relatório final.","Você já organizou seu próximo sucesso com apresentação e três anexos. No amor, planeja coisas duradouras antes de terminar a entrada. Para relaxar, faz gráficos do tempo livre. Seus familiares apelidaram sua agenda de 'quarto membro da família'.","Capricórnio, suas metas são tão precisas que até seus improvisos futuros têm código interno. Você mostra carinho levando dois guarda-chuvas e garantia de pontualidade. No descanso, verifica se a pausa cumpre sua função. Seu travesseiro pensa em trabalhar por conta própria.","Você constrói projetos como quem ergue catedrais: lentamente e com dossiê técnico impecável. Depois se apaixona por uma ideia e oferece contrato sem prazo. Suas férias terminam com relatório de lazer. O pôr do sol ganhou selo 'conforme'.","Na sua vida, uma pequena economia vira vitória narrada em detalhes. No trabalho, você organiza cinco anos de metas. No amor, fidelidade emociona mais que surpresas grandiosas. Você é tão constante que o relógio confere as horas na sua agenda.","Seu descanso parece o plano de lançamento de um serviço novo. Você escolheu o passeio, calculou a duração e preparou o relatório de retorno. Enquanto isso, o projeto profissional avança na etapa prevista. O prazer espontâneo ficou marcado como 'ideia interessante, reavaliar'."]},"aquarius":{"classic":{"career":["Sua originalidade abre novos caminhos quando os hábitos parecem limitar as possibilidades.","Uma ideia ousada ganha alcance ao se transformar em etapas acessíveis aos outros.","A distância que você toma das convenções ajuda a questionar aquilo que parece óbvio.","Quando uma regra parece inútil, compreender sua origem pode enriquecer sua proposta de mudança.","Seu espírito independente encontra força numa colaboração em que todos têm liberdade para contribuir.","Por trás da sua visão singular existe um desejo sincero de fazer o coletivo evoluir.","No trabalho, sua capacidade de pensar de outro modo pode ajudar a destravar uma situação parada.","Compartilhar suas intuições com paciência permite que as ideias mais novas encontrem espaço."],"love":["Sua necessidade de independência pode conviver com um vínculo carinhoso e escolhido livremente.","Uma relação às vezes se alimenta de conversas inesperadas que revelam sensibilidades comuns.","Sua curiosidade pelas pessoas enriquece as trocas quando vem acompanhada de atenção presente.","Quando suas emoções ficam em segundo plano, poucas palavras simples podem tornar seu carinho mais claro.","Sua atração pelo diferente convida a descobrir a outra pessoa sem reduzi-la a hábitos.","Por trás da aparente distância, sua lealdade costuma se manifestar de formas originais.","Na cumplicidade, a autenticidade importa mais que um modelo pronto de relacionamento.","Respeitar ritmos diferentes pode criar um espaço em que todos se sintam livres e reconhecidos."],"wellbeing":["Sua mente inventiva também aprecia momentos em que nenhuma ideia nova é exigida.","Uma caminhada por um lugar familiar pode oferecer outro olhar sobre a rotina.","A liberdade de desacelerar pertence a você tanto quanto a de descobrir.","Quando os pensamentos se multiplicam, uma atividade simples pode trazer sua atenção ao presente.","Seu impulso de novidade pode se equilibrar com hábitos de descanso escolhidos livremente.","Por trás da necessidade de estímulo intelectual, a calma também tem seu lugar.","Durante um dia cheio, reservar um momento longe das telas pode fazer bem.","Acolher a solidão ou uma conversa sincera depende daquilo que realmente renova suas forças."],"wisdom":["Sua diferença ganha sentido quando acolhe a diferença dos outros.","Uma regra merece ser compreendida antes de ser substituída.","Uma novidade só é valiosa quando torna a vida mais viva.","Toda mente livre ganha quando aprende a ouvir sem se negar.","Sua independência não exige manter os outros à distância.","Pensar diferente não significa rejeitar o que funciona.","O futuro também pertence a quem cuida do presente.","Nada de original exige esquecer a simplicidade."],"roast":["Sua rejeição das convenções pode levar você a contestar hábitos que nem incomodavam de verdade.","Uma ideia brilhante às vezes fica difícil de acompanhar quando você já inventou outras três.","Sua distância emocional protege você, mas também pode deixar as pessoas próximas em dúvida.","Quando todos escolhem a mesma solução, você imediatamente procura o motivo de ela estar errada.","Seu espírito de contradição às vezes desperta antes de você ouvir a proposta.","Por trás do gosto pela originalidade, algumas ideias simples aguardam consideração.","Quando uma tendência se torna popular, seu entusiasmo parece perder parte do brilho.","Você gosta tanto de não seguir o grupo que às vezes se recusa a seguir os próprios conselhos."]},"funny":{"career":["Sua imaginação sugere substituir reuniões por um aquário conectado. A equipe só pediu uma pausa para o café.","O departamento quer simplificar a cafeteira. Você sugere que escolha as bebidas pela previsão do tempo. O café agora espera a chuva.","A chefia pede que você siga o protocolo. Educadamente, você pergunta quem autorizou o protocolo.","Quando trocam as cadeiras do escritório, você apresenta um conceito de mobília autônoma. A cadeira já está girando em círculos.","Sua mente visionária imagina o trabalho de amanhã. O de hoje continua esperando na caixa de entrada.","Por trás do seu silêncio na reunião, há um plano para reinventar o teclado. Você já eliminou a tecla « normal ».","Durante o brainstorming, você propõe substituir cadeiras por plataformas móveis. O primeiro voluntário foi parar no corredor.","Compartilhar descobertas encanta você: os colegas recebem uma palestra sobre um assunto que nem sabiam existir.","Você projetou um distribuidor de clipes por comando de voz. O setor escolheu uma tigela na mesa, bem menos tagarela.","Numa reunião, sugere substituir formulários por desenhos coletivos. A contabilidade ainda procura o campo 'total'.","A instrução diz 'use o modelo'. Você apresenta uma versão experimental completamente reinventada. A instrução estava no singular.","Você propõe um dia sem teclado para liberar a criatividade. O suporte de TI já prepara caixas de lápis."],"love":["Seu jeito de amar é único: você envia um artigo fascinante sobre águas-vivas em vez de uma mensagem comum.","Uma noite romântica inspira uma visita à exposição sobre o futuro da mobília. A outra pessoa descobre cadeiras inteligentes.","A distância vem naturalmente: você responde com entusiasmo ao grupo e esquece a mensagem particular.","Quando alguém pede um carinho espontâneo, você constrói uma máquina que distribui elogios personalizados.","Seu espírito independente gosta de vínculos sinceros, desde que o sofá tenha dois controles remotos separados.","Por trás do ar distante, você preparou uma surpresa adorável. Só exige montar um robozinho.","No restaurante, você transforma a escolha dos pratos num debate sobre o futuro da alimentação. As batatas fritas aguardam.","Dividir uma série agrada até todo mundo começar a adorá-la. Você sugere imediatamente um documentário obscuro.","Você demonstra carinho compartilhando descobertas improváveis. A mensagem 'lembrei de você' traz link sobre hábitos de polvos.","Seu encontro ideal começa com amizade longa e passeios independentes. Depois vocês se reúnem para contar como foi.","Uma noite de namoro à distância agrada tanto que você envia o desenho da sobremesa em vez de uma foto.","'A gente se vê em breve?' 'Claro, no nosso lugar de sempre.' Você falava da sala de bate-papo, não da sala de casa."],"wellbeing":["Seu descanso ideal consiste em desligar as telas. Você começa programando um aplicativo para lembrar disso.","Uma caminhada no parque vira estudo sobre hábitos sociais dos pombos. Você já tem três hipóteses.","A solidão renova suas forças, mas seu celular tem oito grupos de discussão sobre o sentido da liberdade.","Quando decide não fazer nada, inventa um método novo para não fazer nada com mais eficiência.","Sua mente inventiva transforma uma xícara de chá numa experiência sobre temperatura ideal.","Por trás da curiosidade de pesquisador, a almofada espera que você finalmente teste sua função principal.","Na hora de dormir, você tem uma ideia revolucionária. O travesseiro sugere registrar a patente amanhã.","Desacelerar parece atraente se for possível medir o efeito com um relógio inteligente. O relógio pede uma pausa.","Você comprou uma pedra conectada para aprender a desacelerar. Ela passa o dia procurando Wi-Fi.","Um aplicativo promete contar seus momentos de calma. Você passa uma hora comparando os contadores.","Sua nova experiência relaxante consiste em ouvir sons de floresta gravados por robô. O parque fica no fim da rua.","Você testa uma lâmpada que imita o amanhecer. Ela acende ao meio-dia, em sintonia perfeita com sua rotina experimental."],"wisdom":["O futuro pertence a quem ousa. Isso não obriga ninguém a reinventar as meias toda manhã.","Uma ideia para o futuro pode começar procurando o controle remoto.","Enxergar o amanhã antes dos outros é útil, desde que você não esqueça o compromisso de hoje.","Todo mundo é único; provar isso em todas as refeições é opcional.","Sua liberdade não perde nada ao aceitar uma receita que funciona.","Inovar nem sempre significa substituir a colher.","O futuro começa amanhã; a roupa suja espera desde ontem.","Nada impede fazer como os outros quando os outros têm razão.","A próxima grande descoberta pode esperar você terminar a xícara de chá.","Ver tudo de modo diferente abre a mente; olhar uma vez normalmente evita desvios desnecessários.","O futuro pertence a quem inventa. O presente agradece a quem guarda os protótipos.","Ter uma ideia avançada não significa que os outros esqueceram de consultar o calendário."],"roast":["Sua recusa à normalidade é tão regular que começa a parecer tradição familiar.","Uma ideia que funciona entedia você assim que uma segunda pessoa a adota. Logo inventa uma versão incompreensível.","A conversa é sobre o tempo. Você apresenta sua teoria das cidades flutuantes.","Quando declara « ninguém me entende », todo mundo pede que reformule o desenho explicativo.","Seu espírito rebelde escolhe o caminho mais original, mesmo quando leva ao armário de vassouras.","Por trás da postura distante, existem quarenta notificações de amigos que você adora « à distância ».","No restaurante, você pede o prato mais surpreendente. Depois, fica surpreso por ele ser surpreendente.","Sua especialidade é rejeitar rótulos. Você criou um novo: « especialista em rejeitar rótulos ».","Você dizia ter descoberto uma música desconhecida. Agora toca em toda parte e você a considera 'decepcionante'.","Você afirma 'não gosto de nada igual aos outros' enquanto escolhe uma bebida misteriosa. É água num copo triangular.","Assim que seus amigos adotam uma novidade, você diz que já ficou ultrapassada. Sua paixão vence muito rápido.","Sua roupa favorita é a que provoca perguntas. Se ninguém comenta, você explica o conceito por conta própria."]},"piquant":{"career":["Sua necessidade de ser diferente leva você a reinventar uma ferramenta que já funciona. A nova exige três treinamentos e cerimônia de inauguração.","Você substituiu a instrução do escritório por um manifesto de doze páginas. No último parágrafo, reinventou a instrução original.","A novidade atrai você enquanto ninguém a usa. Quando a equipe adota sua ideia, você a declara ultrapassada. A equipe pede mediação.","Quando a gerência entrega um procedimento, você exige o procedimento que autoriza procedimentos. O jurídico fechou as cortinas.","Sua mente visionária já trabalha na próxima década. O documento de sexta-feira acaba de comunicar seu desaparecimento.","Por trás do discurso coletivo existe uma condição: o coletivo precisa começar concordando com você. A democracia está em manutenção.","No primeiro consenso, você vira a oposição oficial. Até sua própria proposta acabou de votar contra si.","Você sugere uma cafeteira que colete ideias dos funcionários. Ela classificou seu projeto como 'complexo demais para um expresso'.","Você quer democratizar a cafeteira com votação por algoritmo. Desde então ninguém consegue um expresso sem participar de assembleia.","A chefia autoriza uma solução simples. Você publica um manifesto contra a simplicidade, com anexos e mapa revolucionário.","Seu protótipo de escritório sem pastas troca papéis por QR codes ilegíveis. A organização ficou moderna, mas não útil.","Você revoluciona um procedimento que já funciona. O resultado faz a mesma coisa, só que com três baterias para recarregar."],"love":["Sua independência reservou dois quartos emocionais, saída de emergência e acesso limitado aos sentimentos. O carinho espera o crachá.","Uma declaração de afeto incomoda menos que uma pergunta comum: « Você pensou em mim? ». Seu cérebro prepara uma palestra.","A distância afetiva dá um ar fascinante. Você só esquece que às vezes os outros preferem respostas às mensagens.","Você apresenta a amizade como ápice do romance. A outra pessoa percebe que recebeu cartão de sócio, não convite para encontro.","Para um encontro a dois, você escolhe lugares diferentes e sugere conversar à distância. A aproximação física ficou no plano premium.","Por trás do sorriso misterioso costuma existir um fato banal: você está pensando numa invenção. O romantismo não foi avisado.","Diante de um « vamos fazer como sempre », você convoca revolução doméstica. O jantar só precisava de pratos.","Compartilhar emoções parece possível por meio de uma apresentação conceitual. O coração exige uma versão sem slides.","Você reserva um lugar especial para a pessoa amada: entre 'melhor amizade' e 'conversa fascinante', a cinquenta quilômetros do cotidiano.","Você adora relações sem exigência de proximidade. O problema é que suas mensagens chegam como cartões-postais de outra galáxia.","Sua declaração tem duas frases: 'Você importa para mim'. Depois vem uma palestra inteira sobre as vantagens de morar em casas separadas.","Você trata proximidade como tema de debate teórico. A outra pessoa só pretendia segurar sua mão."],"wellbeing":["Você instalou um sensor para medir se está descansando. O aparelho registra principalmente as horas gastas configurando-o.","Uma caminhada tranquila parece convencional demais. Você faz seu trajeto habitual ao contrário. O mapa pede perícia.","Seu aparelho relaxante emite dez sons, três vibrações e um alerta de calibração. Você o desligou para ter sossego.","Quando todo mundo desliga o celular, você inventa um novo motivo para ligá-lo. O modo avião apresenta demissão.","Seu espírito futurista quer otimizar o sono com uma invenção revolucionária. A luminária sugere simplesmente ser apagada.","Por trás da sua distância, você acompanha três grupos sobre a arte de não seguir grupos. A contradição assinou um plano mensal.","Ao respirar ar fresco, você propõe um modelo teórico de ventilação para o parque. As árvores pedem confidencialidade.","Você testa um aplicativo de soneca inteligente. Ele acorda você para parabenizá-lo por ainda não ter dormido.","Sua pulseira de relaxamento tem manual mais longo que a semana. Depois de três ajustes, você relaxou ao guardá-la na gaveta.","Boletim técnico fictício: a experiência de descanso falhou por causa do fone inteligente. O fone nem pretendia descansar.","Você criou um método relaxante com sensores, alertas e painéis. Tem tudo, exceto botão 'desligar'.","Você testa uma fonte decorativa controlada à distância. Ela manda trinta notificações para anunciar que a água está correndo."],"wisdom":["Você olha tão longe para o futuro que o presente parece um anexo esquecido.","Uma ideia incompreensível não está necessariamente à frente do seu tempo.","Rebelar-se contra uma porta aberta ainda é uma entrada teatral.","Nem todo mundo copia você: algumas pessoas só compraram uma cadeira.","Sua independência rejeita vínculos, mas mantém o grupo nos favoritos.","Inovar para evitar uma orientação é construir um palácio para ela.","O futuro fascina você; o presente ainda espera resposta.","Estar à frente do seu tempo não garante saber onde fica a porta.","Você está um século à frente da época. A época, educadamente, ainda espera a demonstração.","O futuro não precisa ser complicado para ser novo. Sua bússola ainda tenta entender isso.","Uma ideia brilhante ilumina o amanhã. A sua às vezes esqueceu de instalar o interruptor.","Você prevê o amanhã com tanta certeza que o presente abriu um boletim de ausência."],"roast":["Sua diferença é tão importante que você exige certificado oficial de originalidade. O formulário é idêntico para todos.","Uma invenção banal vira « ruptura de paradigma » nas suas mãos. Você acabou de colar uma etiqueta numa caixa.","A proximidade afetiva parece suspeita. Você ama toda a humanidade, contanto que ela mantenha dois metros de conversa.","Quando os outros descobrem sua música favorita, você a abandona imediatamente. O reprodutor pede identidade estável.","Sua diferença virou marca pessoal. Assim que uma tendência alcança você, você muda de opinião antes de acabar o nome dela.","Por trás do amor às ideias malucas, há uma guerra particular contra a simplicidade. A colher se refugiou na casa dos vizinhos.","No primeiro acordo geral, você muda de lado. Suas opiniões antigas acabaram de formar uma oposição parlamentar.","Revolucionar o mundo do sofá ocupa bastante seu tempo. O sofá só queria que você encontrasse o controle remoto.","Você abandonou a paixão preferida no dia em que conquistou o primeiro admirador. É menos gosto e mais perseguição.","Sua personalidade pediu patente por não se parecer com ninguém. O pedido foi negado por falta de novidade.","Últimas notícias: a tendência que você defendia ontem ficou popular. Você já a criticou num manifesto de três páginas.","Você procura uma moda da qual ninguém ouviu falar. Quando encontra, abandona: agora existe uma testemunha."]},"roastMy":["Aquário, você não é diferente: transformou a diferença num serviço de assinatura. Rejeita gostos populares e depois os próprios gostos quando ficam populares. Sua personalidade muda de vitrine toda quinta-feira. Até a originalidade cancelou o contrato.","Sua mente inventa soluções para problemas que ninguém tem. Substitui o interruptor por aplicativo e depois o aplicativo por protótipo experimental. A sala continua escura. Você anuncia uma vitória tecnológica histórica.","Você ama todo mundo, mas a distância regulamentar. Um amigo conta seu dia, você responde com link sobre evolução das sociedades. Ele espera carinho. Você manda a atualização do link.","Aquário, você contesta regras antes de ler. Propõe um sistema livre, inovador e totalmente novo. Três páginas depois, o sistema tem dezessete regras e comitê de fiscalização. O regulamento antigo pede reabilitação.","Seu futuro está cheio de invenções fabulosas. Seu presente se resume a carregador perdido e pilha de papéis. Você explica que objetos materiais são conceito ultrapassado. Os papéis exigem arquivista.","Você reivindica independência com talento quase cerimonial. Oferecem café, você recusa porque « todo mundo faz isso ». Então prepara uma bebida idêntica num copo estranho. O café pede candidatura à normalidade.","Seu olhar distante dá a impressão de conhecer um segredo do universo. Na verdade, você pensa em instalar uma minihorta na geladeira. Alguém pergunta se está tudo bem. Você responde com palestra sobre agricultura vertical.","Aquário, você detesta classificações. Mesmo assim, criou uma tipologia completa de pessoas convencionais, ousadas e das que não entendem você. Ninguém corresponde à definição de gênio. Curiosamente, você reservou essa categoria para si.","Você acredita estar sempre cinco anos à frente da época. Propõe um projeto incompreensível, se recusa a simplificá-lo e declara os outros atrasados. O projeto não é revolucionário. É uma torradeira com interface de navegação.","Sua necessidade de novidade transforma o jantar numa conferência sobre o futuro. Você apresenta oito ideias, três protótipos e um mundo sem hábitos. Os convidados só procuram o sal. Você anuncia que o sal será descentralizado na segunda-feira.","Aquário, você projetou uma máquina para simplificar tarefas. Ela precisa de três conexões e autorização do vizinho. Nos afetos, prefere começar por uma amizade de profundidade cósmica. A máquina, assim como seus encontros, ainda espera a estreia.","Sua curiosidade inventa um futuro maravilhoso com engenhocas impensáveis. Você presenteia alguém com um aparelho conectado para desejar bom dia. Ele passa a noite instalando atualizações. Seu carinho é real, mas esqueceu o cabo.","No escritório, você quer substituir um procedimento por uma ideia revolucionária. Depois testa um aparelho para melhorar o lazer. No dia seguinte alguém adota sua descoberta e você já troca de paixão. Só você considera sucesso motivo para abandonar tudo.","Você fala do futuro como quem recebeu a programação oficial. No amor, prefere um debate intelectual a um jantar tradicional. Para descansar, experimenta um método que ninguém testou. A única coisa estável nisso é sua certeza de estar à frente.","Sua criatividade transforma cafeteira em projeto de civilização. Você precisa de espaço para amar e aparelhos para descansar. Cada moda perde o encanto quando chega aos outros. Sua mente é exposição permanente que retira as obras no dia da inauguração."]},"pisces":{"classic":{"career":["Sua imaginação pode revelar possibilidades que abordagens rígidas demais deixam de lado.","Uma intuição merece ser explorada com cuidado antes de se transformar numa decisão coletiva.","Sua sensibilidade nas conversas ajuda a compreender melhor as expectativas da equipe.","Quando várias ideias se cruzam, escolher um primeiro passo concreto pode dar vida à criatividade.","Sua capacidade de perceber o clima do ambiente permite abordar situações com delicadeza.","Por trás dos devaneios, às vezes existe um jeito singular de conectar elementos distantes.","No trabalho, estabelecer limites claros preserva sua disponibilidade para os projetos que importam.","Transformar inspiração em ação exige dar a ela um pouco de tempo e estrutura."],"love":["Sua sensibilidade permite acolher com muito coração as nuances de uma conversa.","Um cuidado discreto pode dizer tanto quanto um grande gesto romântico.","A ternura que você oferece ganha quando também escuta suas próprias necessidades.","Quando sua imaginação dispara, voltar às palavras realmente trocadas pode esclarecer as impressões.","Sua generosidade afetiva convida a criar vínculos em que cada um seja livre para ser quem é.","Por trás dos sonhos de harmonia, você pode descobrir a beleza de relações simples e sinceras.","Na cumplicidade, a confiança também cresce com perguntas feitas sem receio.","Acolher as emoções da outra pessoa não significa precisar encontrar uma solução para elas."],"wellbeing":["Sua sensibilidade aprecia lugares tranquilos onde os pensamentos podem repousar sem pressão.","Uma música suave ou um momento de silêncio pode acompanhar a vontade de recuperar seu ritmo.","Sonhar acordado tem seu lugar no dia quando também permite saborear o presente.","Quando as solicitações se multiplicam, uma pausa simples pode ajudar você a reencontrar seu espaço.","Sua imaginação fértil pode se alimentar de um caderno, uma caminhada ou uma paisagem familiar.","Por trás da atenção dedicada aos outros, reserve um momento para o que lhe dá prazer.","Ao longo do dia, uma conversa acolhedora pode oferecer uma agradável sensação de firmeza.","Respeitar sua necessidade de descanso não diminui sua generosidade."],"wisdom":["Sua sensibilidade é uma força quando também respeita seus limites.","Um sonho ganha profundidade quando encontra um gesto concreto.","A delicadeza não obriga a carregar as preocupações de todos.","Todo sentimento merece escuta, não necessariamente uma história inteira.","Uma intuição fica mais clara quando aceita algumas perguntas.","Oferecer sua presença não significa resolver toda dificuldade.","A imaginação abre portas; a realidade indica onde caminhar.","Nenhum gesto de carinho exige que você se esqueça de si pelos outros."],"roast":["Sua imaginação pode transformar uma conversa comum num roteiro muito mais complicado que os fatos.","Um pedido de ajuda, mesmo pequeno, às vezes faz você colocar as próprias necessidades de lado.","Você sonha acordado com tanta frequência que algumas tarefas práticas ainda esperam seu retorno.","Quando uma emoção surge, você às vezes entrega a ela todo o espaço disponível.","Sua vontade de compreender cada pessoa pode levar você a desculpar facilmente os erros alheios.","Por trás das belas intuições, alguns detalhes ainda merecem verificação.","Na hora de fazer uma escolha simples, sua imaginação apresenta uma enorme lista de possibilidades.","Retomar o fio da conversa fica difícil quando sua mente já partiu para outra história."]},"funny":{"career":["Sua criatividade transforma um comunicado de serviço no começo de um romance. O comunicado só pedia para fechar as janelas.","A reunião avança por três assuntos. Você volta de um quarto, que ninguém anunciou, mas sua intuição acha fascinante.","Sua gentileza leva você a ajudar três colegas ao mesmo tempo. Seu próprio documento envia um lembrete tímido.","Quando você sonha diante da tela, talvez esteja preparando um projeto genial. Ou inventando o nome de um reino.","Sua intuição anuncia uma mudança no clima da sala. A mudança era um colega que abriu um pacote de biscoitos.","Por trás da vontade de resolver tudo, você aceitou reorganizar a mesa de alguém que não pediu nada.","Uma instrução inspira uma solução criativa, depois outra, depois um desenho no guardanapo. O prazo de entrega ficou fora de quadro.","Você pressente a melhor solução antes do debate começar. Seus colegas também gostariam de conhecer as etapas intermediárias.","Sua intuição sugere uma solução na reunião. Você a anota numa folha solta que se junta à coleção de ideias desaparecidas.","A agenda marca um prazo firme. Você vê nele um convite para trabalhar num ambiente criativo.","Você prepara apresentação com desenhos bonitos e explicações sensíveis. Alguém faz a pergunta fatal: 'Por onde começamos?'","Uma reunião de acompanhamento inspira uma metáfora sobre correntes marítimas. O chefe anota 'ideias fluidas' na coluna de entregas."],"love":["Seu romantismo escreve um filme inteiro a partir de um simples « bom dia ». A pessoa só procurava o ponto de ônibus certo.","Uma canção no rádio faz lembrar algo precioso. Você já atribuiu uma trilha sonora completa à lembrança.","Sua sensibilidade percebe que a mensagem contém um ponto-final incomum. Você abre investigação sobre a pontuação.","Quando alguém empresta um guarda-chuva, o gesto emociona tanto você que pensa em escrever um poema de agradecimento.","Sua ternura transbordante alcança até as plantas da varanda. Você as parabeniza quando parecem felizes.","Por trás do olhar sonhador, uma linda cena romântica acontece. Na vida real, o garçom aguarda seu pedido.","No primeiro jantar, um olhar carinhoso basta para iniciar uma grande história na sua cabeça, com créditos. A outra pessoa ainda lê as entradas.","Dividir uma caminhada basta para você inventar uma história sobre cada janela iluminada do bairro.","Uma troca de olhares no café vira história em três atos na sua mente. O primeiro acaba antes de servirem as bebidas.","Você já escolheu mentalmente a música do primeiro encontro, que ainda nem foi proposto. O maestro espera os convites.","Um coração desenhado numa embalagem inspira uma cena romântica. O fabricante só queria vender biscoitos.","Você conta o último encontro como grande saga. A outra pessoa lembra principalmente do trajeto de ônibus."],"wellbeing":["Sua mente sai de férias enquanto você procura os chinelos. Os chinelos esperam com paciência.","Você se senta perto de um riacho e deixa a água marcar o ritmo da pausa. Seu relógio não sabe como classificar o momento.","Sua playlist relaxante começa com ondas, passa pela chuva e termina com fonte de água. O banheiro se sente ameaçado pela concorrência.","Você ouve a mesma melodia tranquila por uma hora. No fim conhece melhor o silêncio entre as notas que a própria música.","Sua vontade de cuidar dos outros faz você oferecer uma almofada à poltrona. A poltrona parecia confortável.","Por trás da tranquilidade existe uma epopeia interior. Você atravessou três reinos entre dois goles de água.","Na hora de dormir, você se lembra de uma cena emocionante de um desenho animado. O travesseiro prevê uma longa noite.","Voltar ao presente às vezes exige uma placa indicativa. Ela está ao lado das chaves que você procura há dez minutos.","Você abre a janela para ouvir a chuva. O celular sugere um aplicativo que imita exatamente o som real.","Seu momento de calma começa com música suave e termina com os pés na água. O tapete recebe a notícia resignado.","Uma fonte no parque basta para criar um instante especial. O pato ao lado parece ter reservado o mesmo espetáculo.","Você fecha os olhos ao som de uma melodia tranquila. O mundo pode esperar até a nota seguinte."],"wisdom":["Sua intuição às vezes é brilhante. Também pode confundir um sinal misterioso com a seta do banheiro.","Nem todo sinal cotidiano traz mensagem. Alguns avisos apenas indicam a saída.","O cosmos pode inspirar você; não precisa ser responsabilizado por todo barulho da geladeira.","Nem todo olhar misterioso anuncia uma história extraordinária.","Sua intuição às vezes ganha ao consultar a caixa de entrada.","Oferecer consolo não obriga a adotar a torradeira triste.","A inspiração viaja livremente; seu compromisso continua no horário marcado.","Nada prova que a nuvem tenha enviado uma mensagem pessoal a você.","A intuição é guia curioso; nem sempre substitui as placas do caminho.","Um sinal do céu não é convite para interrogar pessoalmente todas as placas da rua.","Seu instinto às vezes acerta. Também deveria aprender a ler as letras pequenas.","O acaso tem muitos talentos. Não lhe dê a tarefa de responder a todas as perguntas do dia."],"roast":["Você perdeu suas chaves enquanto ajudava três pessoas a encontrar as delas. O chaveiro pensa em abrir um serviço de atendimento.","Uma planta meio inclinada inspira uma conversa de apoio. A planta precisava de luz.","Seus devaneios levam você tão longe que o chá acaba ganhando uma história de abandono.","Quando entra numa livraria, você se apega aos personagens antes de abrir os livros.","Você ofereceu ajuda a alguém que carregava uma sacola vazia. A pessoa voltou com roteiro sugerido e seu telefone.","Você saiu para procurar uma caneta e voltou com água para um colega, conselho para outro e nenhuma lembrança da caneta.","Diante de um olhar no metrô, você inventa passado, segredo e reviravolta final. A pessoa só olhava o mapa.","Você procura os óculos por toda parte, embora estejam na mesa. Nesse intervalo, consolou alguém que nem estava triste.","Você encontrou o guarda-chuva de um amigo e perdeu o seu ao ir entregá-lo. Os objetos começaram a brincar de dança das cadeiras.","Você quis consolar um vizinho que só estava concentrado nas palavras cruzadas. Ele acabou lhe dando uma dica para resolver.","Você saiu para levar uma xícara a alguém. Voltou com três guardanapos, duas ideias de arrumação e nenhuma xícara.","Um amigo diz 'vai dar certo'. Você monta equipe de apoio, mas ele falava de uma prateleira que estava montando."]},"piquant":{"career":["Sua intuição profissional trocou o manual por uma seta desenhada a lápis. Ela aponta para o ateliê criativo, não para o projeto.","Uma observação simples inspira doze interpretações. A ata foi classificada entre as obras de ficção.","Sua gentileza leva você a resolver os problemas da equipe inteira. Seu próprio trabalho mudou oficialmente de dono.","Esperam uma decisão objetiva. Você volta com uma ideia poética e três tonalidades. A decisão saiu da pauta.","Seu faro na reunião leva você a apresentar a ideia antes de verificar os fatos. O gráfico aplaude e depois muda de valor.","Seu talento criativo oferece dez caminhos para uma tarefa simples. A agenda virou observadora sem direito a voto.","No escritório, você recolhe preocupações alheias como objetos abandonados. O setor de achados e perdidos recusou sua candidatura.","Transformar sonho em cronograma parece limitador. O calendário só queria saber se você vem na segunda-feira.","Sua intuição aprovou um projeto sem ler as notas. A planilha o registrou como 'inspiração, provas pendentes'.","Você responde à pergunta sobre prazo com desenho artístico. A data foi representada por uma onda abstrata.","Comunicado interno: sua criatividade entregou catorze propostas. Nenhuma indica o endereço do arquivo a enviar.","Você chega atrasado com uma ideia brilhante sobre gestão do tempo. O relógio decidiu não assistir à palestra."],"love":["Seu romantismo transforma um olhar de dois segundos numa saga de oito temporadas. O figurante principal ainda não sabe da filmagem.","Uma resposta curta faz você escrever um roteiro de catástrofe e depois uma continuação feliz. A mensagem só dizia « ok ».","Sua ternura faz você adotar emocionalmente cada pessoa gentil. Até o entregador entra no seu romance interior.","Quando alguém sorri por educação, sua imaginação lança um trailer. O sorriso exige direitos de imagem.","Um ponto final numa mensagem vira sinal de grande história sentimental. O ponto achava que só encerrava a frase.","Por trás das promessas de amor simples, existe uma equipe de roteiristas. Eles já programaram três reviravoltas para terça-feira.","Diante do menor silêncio, você escreve um diálogo completo na cabeça. A outra pessoa só estava preparando macarrão.","Compartilhar sentimentos é sua especialidade: você manda uma mensagem tão cheia de nuances que precisa de sumário. O ponto-final se perdeu.","Um olhar no elevador vira mural romântico na sua cabeça. A pessoa só procurava o quarto andar.","Você transforma um 'até logo' em promessa digna de grande final. A conversa original cabia num bilhete de metrô.","Seu coração já escreveu a música, o cenário e o desfecho. A outra pessoa nem recebeu convite para o primeiro ato.","Você vê símbolo amoroso numa xícara torta. O café apenas escorreu de lado, sem intenção narrativa."],"wellbeing":["Você liga sons de ondas para relaxar. Três horas depois conhece o áudio de todos os mares, mas esqueceu onde fica a pausa.","Você se senta perto da água para encontrar sossego. Fica tanto tempo que os patos acham que você faz parte da paisagem.","Sua playlist de descanso tem oito ambientes aquáticos. No nono, a caixa de som acha que administra as marés.","Quando procura calma, você começa a analisar o humor das nuvens. O céu bloqueia suas notificações.","Seu refúgio interior tem cachoeira, música suave e entrada secreta. A sala de verdade espera você voltar para sentar.","Por trás do ar tranquilo, um tribunal emocional julga uma conversa de terça-feira. A terça foi absolvida à revelia.","Na hora de dormir, sua mente inicia a versão estendida das lembranças mais comoventes. O travesseiro apresenta reclamação.","Você se deixa embalar por uma melodia tanto tempo que a próxima música marcou horário para começar.","Seu aplicativo de chuva tem trinta modos. Você ainda procura o som exato de uma terça-feira sem obrigações.","Você instalou uma fonte de mesa para criar um refúgio. Agora ela faz mais barulho que uma reunião de condomínio.","Previsão da sua tranquilidade: nuvens leves e playlist infinita. O botão de desligar está sob uma almofada.","Você procura calma no murmúrio de um riacho. O riacho não quer virar sua rádio particular."],"wisdom":["Sua intuição lê romances em mensagens de três palavras.","Um sinal do universo merece atenção. Um semáforo de pedestres verde não é revelação particular.","Compaixão não obriga a defender os direitos da almofada.","Nem todo silêncio esconde um drama: às vezes, alguém só está comendo.","Seus devaneios têm um cinema; a realidade espera seu ingresso.","Oferecer ajuda ao universo inteiro deixa sua agenda sem dono.","Sua intuição tem uma antena maravilhosa. Também capta as propagandas do destino.","Nada é mais épico que sua interpretação de um simples « obrigado ».","Seu instinto decifra mensagens ocultas por toda parte. O cosmos não oferece serviço de correspondência registrada.","Uma coincidência não é comunicado oficial do infinito. Seu caderno já planejou a coletiva de imprensa.","Você vê cada nuvem como sinal pessoal. O céu também transmite programas sem destinatário.","Sua intuição se acha assinante do jornal do universo. Às vezes confunde a previsão do tempo com o editorial."],"roast":["Você se ofereceu para melhorar o ânimo de um cacto perfeitamente tranquilo. O cacto respondeu com um silêncio muito claro.","Uma lágrima diante de uma animação parece perfeitamente razoável. Agora você prepara desculpas para um personagem secundário.","Sua compaixão faz você ajudar todo mundo, até a almofada mal posicionada. A almofada exige independência.","Alguém só procura um lenço. Você oferece discurso de conforto, plano de acompanhamento e seu último guarda-chuva.","Sua sensibilidade coleciona lembranças que ninguém sabe datar. Um guardanapo de restaurante acaba de receber status histórico.","Por trás do olhar perdido existe um diretor de cinema interior filmando sem autorização. O cotidiano prepara recurso.","Diante de um suspiro, você abre investigação sobre as emoções da sala. A cadeira confessa apenas ter rangido.","Você perdeu a agenda ajudando um vizinho a organizar a dele. Seu compromisso do dia agora consta como 'lembrança vaga'.","Você encontrou o cachorro de um vizinho e perdeu sua bolsa ao tentar oferecer água. Sua boa ação esqueceu o achados e perdidos.","Alguém diz que sabe montar o móvel sozinho. Você aparece com incentivos, parafusos extras e cerimônia de apoio.","Últimas notícias: você emprestou o carregador a quem nem precisava. Seu celular acompanha tudo com 1% de bateria.","Você quer resolver pequenos problemas do bairro inteiro. Sua própria correspondência fechada decidiu se mudar."]},"roastMy":["Peixes, uma mensagem sem emoji vira para você o início de um drama em vários atos. Você relê a pontuação, inventa uma explicação e já escolhe a música da reconciliação. A outra pessoa só estava com as mãos ocupadas. Seu roteiro acabou de perder o financiamento.","Sua imaginação não distingue um fato de um trailer. Alguém olha para você no ônibus e você inventa uma história inteira. A pessoa pergunta as horas. Você imediatamente reescreve o final.","Você quer salvar todo mundo, até quem não pediu ajuda. Oferece apoio emocional a uma planta meio inclinada. A planta endireita quando você abre a janela. Você declara vitória da sua empatia.","Peixes, você vive histórias fictícias com tanta intensidade que seu sofá conhece todos os personagens das suas séries. Defende um vilão incompreendido e consola um herói imaginário. O sofá não viu o episódio. Você faz um resumo de quarenta minutos.","Você perde as chaves, a xícara e às vezes o motivo de ter ido até outro cômodo. Procura tudo inventando uma explicação mágica. As chaves estavam no bolso. Você conclui que o destino as tinha escondido ali.","Sua intuição está sempre pronta para interpretar cada nuance. Um colega escreve « obrigado » em vez de « muito obrigado ». Você organiza mentalmente uma central de crise. O colega só estava com pressa para pegar o trem.","Você ama lembranças a ponto de transformar uma passagem de ônibus numa relíquia sentimental. Cada objeto tem história, atmosfera e data aproximada. Você se recusa a jogar um papel velho fora. O papel nem lembra de você.","Peixes, você promete descansar e então alguém conta um probleminha. Você vira conselheiro, mediador e organizador de soluções. A pessoa só queria falar do guarda-chuva. O guarda-chuva agora tem um plano de desenvolvimento pessoal.","Sua mente consegue abandonar uma conversa sem avisar e partir para construir uma cidade imaginária. Você volta com uma ideia poética, uma emoção e nenhuma resposta à pergunta inicial. Perguntam o que você quer beber. Você conta a história de uma fonte.","Você é capaz de dar importância imensa a uma nuvem que passa. Observa, imagina a viagem dela e pergunta se traz uma mensagem. A nuvem vai embora sem responder. Seu departamento de interpretação celestial abre investigação mesmo assim.","Peixes, sua criatividade transforma instruções de trabalho em passeio poético. No amor, um sorriso vira romance interior completo. Você encontra paz nos sons da água e tenta consolar uma planta perfeitamente feliz. Ela agradece continuando a ser planta.","Você entra na reunião com uma intuição e sai com oito ideias que não cabem em formulário. Uma mensagem carinhosa inspira uma grande cena de cinema. Uma música suave absorve você por horas. Sua agenda continua procurando quem deveria lê-la.","Você oferece apoio com generosidade desconcertante, inclusive a quem não pediu. Interpreta sinais cotidianos como pesquisador das estrelas. Depois esquece a xícara no caminho da sala. E a xícara nem tinha enviado pedido de socorro.","No trabalho, sua melhor ideia aparece logo depois do fim do assunto. No amor, você já escolheu a música de uma história que não começou. Para relaxar, ouve ondas. Sua rotina não está atrasada: espera acabar a trilha sonora.","Você transforma detalhes em histórias comoventes como ninguém. Depois oferece ajuda a três pessoas que só faziam compras. Seu refúgio parece um mar interior onde horários não entram. Enquanto isso, a lista de compras continua procurando seus donos."]}},"events":{"newMoon":{"classic":["A Lua nova convida você a definir uma intenção simples e acolher um começo sem exigir resultados imediatos.","Sob a Lua nova, abrir espaço para uma ideia ainda frágil pode revelar outro caminho.","Esta Lua nova simboliza uma página em branco: escolha o que deseja cultivar nela, no seu ritmo."],"funny":["Lua nova, vida nova: você já comprou um caderno novinho para anotar uma ideia de três anos atrás.","A Lua nova oferece uma página em branco. Você passa vinte minutos escolhendo a fonte do título.","Lua nova: suas resoluções voltam ao trabalho, mas esqueceram a senha."],"piquant":["A Lua nova sugere recomeçar do zero. Calma, seu método de improvisar tudo já está preparado.","Sob a Lua nova, você sonha com uma grande renovação. Até agora, mudou três ícones de lugar na tela.","A Lua nova abre uma página em branco. Seu talento é copiar nela as mesmas desculpas, agora com outra capa."]},"firstQuarter":{"classic":["O quarto crescente convida a transformar intenções em ações concretas, ajustando o rumo diante dos primeiros obstáculos.","No quarto crescente, agir pode mostrar o que precisa de reforço, não de pressa.","O quarto crescente lembra a importância de persistir com flexibilidade quando o impulso encontra a realidade."],"funny":["Quarto crescente: seus planos pedem ação. Sua agenda finge que nunca ouviu falar de você.","O quarto crescente incentiva a agir. Sua lista de tarefas ficou tão completa que precisa de um assistente próprio.","Quarto crescente: você finalmente dá o primeiro passo e descobre que era encontrar suas chaves."],"piquant":["O quarto crescente pede resultados. Seu método parece um móvel montado sem manual: muita confiança e três parafusos sobrando.","Quarto crescente: o céu convida à ação, não a uma reunião consigo mesmo sobre a possibilidade de agir.","No quarto crescente surge o primeiro obstáculo. Você o encara como uma ofensa pessoal do mobiliário."]},"fullMoon":{"classic":["A Lua cheia destaca uma etapa que amadureceu e convida a observar as emoções com clareza.","Sob a Lua cheia, o que era discreto pode ganhar espaço. Acolher essa luz ajuda a fazer um balanço.","A Lua cheia simboliza uma possível conclusão: reconhecer o caminho percorrido importa tanto quanto o próximo passo."],"funny":["Lua cheia: emoções em alta definição. Até o 'tá bom' de um colega merece uma análise detalhada.","A Lua cheia ilumina pequenas verdades. Você enfim descobre por que a gaveta não fecha: seis carregadores misteriosos.","Sob a Lua cheia, tudo parece mais intenso, inclusive o suspense de saber quem acabou com o café."],"piquant":["A Lua cheia ilumina o que você evitava. Seu plano de discrição funciona como um letreiro luminoso numa biblioteca.","Lua cheia: hora do balanço. Você chamava de estratégia; os fatos chamam de improviso com assessoria de imprensa.","A Lua cheia põe tudo às claras. Você esperava um momento sublime; seu histórico de decisões agendou uma sessão privada."]},"lastQuarter":{"classic":["O quarto minguante convida a separar o que ainda merece sua atenção e deixar o resto ir embora.","No quarto minguante, rever uma etapa pode aliviar compromissos que já perderam a utilidade.","O quarto minguante simboliza um momento de reflexão: simplificar prioridades abre espaço para o que vem depois."],"funny":["Quarto minguante: o céu sugere uma faxina. Sua caixa de e-mails pede imediatamente mais prazo.","O quarto minguante convida a desapegar. Você apaga uma foto tremida e espera aplausos.","Quarto minguante: você finalmente arruma uma gaveta e acha a lista de tudo que ainda precisava organizar."],"piquant":["O quarto minguante pede uma limpeza interior. Suas desculpas estão por cor, mas as decisões seguem sob o tapete.","Quarto minguante: hora de largar os excessos. Sua coleção de 'vai que preciso' já quer um galpão.","A Lua minguante convida a simplificar. Você continua negociando com um hábito que só cria complicações."]},"moonInSign":{"classic":["A Lua atravessa seu signo e convida você a ouvir as emoções sem deixar que decidam tudo por você.","Com a Lua no seu signo, a intuição pode ganhar espaço. Procure distingui-la das impressões passageiras.","A passagem da Lua pelo seu signo destaca simbolicamente o que você sente, oferecendo tempo para compreender melhor."],"funny":["A Lua atravessa seu signo. Você percebe o clima de uma sala antes de notar que entrou na sala errada.","Com a Lua no seu signo, suas emoções aumentam o volume. Até escolher uma xícara vira questão de princípios.","A Lua passa pelo seu signo: você sente algo estranho e então percebe que é só a cadeira rangendo."],"piquant":["A Lua atravessa seu signo e amplia suas impressões. Sua intuição já escreveu um relatório sem consultar os fatos.","Com a Lua no seu signo, cada detalhe vira mensagem. Até a luz do roteador parece enviar um comunicado secreto.","A Lua visita seu signo. Seu mundo interior convoca uma coletiva de imprensa para anunciar um aborrecimento minúsculo."]},"sunInSign":{"classic":["O Sol atravessa seu signo: um período para refletir sobre o que motiva você e o impulso que deseja dar aos projetos.","Sua temporada solar ilumina simbolicamente sua trajetória. Reconhecer avanços pode fortalecer uma confiança serena.","Com o Sol no seu signo, o desejo de renovação convida a conciliar a vontade de brilhar com suas necessidades profundas."],"funny":["O Sol atravessa seu signo. Você entra na sala como se fosse começar a trilha sonora; era só o micro-ondas.","É sua temporada solar: você planeja uma grande reflexão pessoal, começando pelo novo papel de parede do celular.","O Sol está no seu signo. Seu aniversário se aproxima ou passou há pouco; sua agenda quer uma cerimônia de abertura."],"piquant":["O Sol atravessa seu signo e põe você simbolicamente no centro. O programa da sua cerimônia já foi distribuído.","Sua temporada solar inspira uma reflexão; seu ego reservou o salão inteiro para apresentar gráficos triunfais.","Com o Sol no seu signo, você quer irradiar luz. Não precisa transformar toda conversa numa palestra chamada 'Eu, a epopeia'."]},"venusInSign":{"classic":["Vênus atravessa seu signo e convida a cultivar prazeres simples, gestos elegantes e trocas de qualidade.","Com Vênus no seu signo, o gosto pelo belo pode inspirar a forma como você vive e compartilha o cotidiano.","A passagem de Vênus pelo seu signo destaca a delicadeza e a harmonia, sem forçar aproximações."],"funny":["Vênus atravessa seu signo. Você acende uma vela para uma noite refinada; ela ilumina a pilha de roupa para dobrar.","Vênus está no seu signo: você entra na loja só para olhar e sai com uma almofada que 'muda todo o ambiente'.","Com Vênus no seu signo, desperta o gosto pelo belo. Você passa mais tempo arrumando o lanche do que comendo."],"piquant":["Vênus atravessa seu signo e refina seus gostos. Seu senso estético é tão exigente que até uma planta falsa passa por entrevista.","Vênus está no seu signo. Você quer harmonia perfeita; pena que suas prioridades moram numa república forçada.","Com Vênus no seu signo, você procura charme em tudo. Até suas chaves exigem fotos com iluminação suave."]},"marsInSign":{"classic":["Marte atravessa seu signo: a vontade de agir pode aumentar. Escolher uma direção ajuda a usar essa energia com cuidado.","Quando Marte passa pelo seu signo, a iniciativa ganha destaque simbólico. A paciência segue aliada da ousadia.","Marte no seu signo convida a afirmar sua vontade sem esquecer o ritmo dos outros. É melhor manter o impulso sob controle."],"funny":["Marte atravessa seu signo. Você quer resolver tudo agora, até a ordem das notificações na tela.","Com Marte no seu signo, você encara a lista de tarefas como competição. A caneta pediu um juiz.","Marte passa pelo seu signo: você responde 'estou chegando' antes mesmo de descobrir o endereço."],"piquant":["Marte atravessa seu signo. Sua paciência cabe num envelope, e você já perdeu o envelope.","Com Marte no seu signo, cada atraso vira disputa de autoridade. Nem o semáforo vermelho reconhece seu posto.","Marte no seu signo dá impulso. Você avança como reunião sem pauta: rápido, barulhento e sem saber por quê."]},"jupiterInSign":{"classic":["Júpiter atravessa seu signo e convida a ampliar horizontes. A confiança pode crescer quando vem acompanhada de discernimento.","A passagem de Júpiter pelo seu signo simboliza expansão: explorar possibilidades sem prometer sucesso.","Júpiter no seu signo incentiva ambições generosas. O senso de medida pode ajudá-las a ganhar força."],"funny":["Júpiter atravessa seu signo. Você quer aprender três idiomas, lançar um projeto e arrumar o porão antes de domingo.","Júpiter está no seu signo: suas ideias crescem. O quadro branco pede uma segunda parede.","Com Júpiter no seu signo, você pensa grande. Até a lista de compras tem uma seção de 'visão estratégica'."],"piquant":["Júpiter atravessa seu signo e amplia suas ambições. Seu senso de medida comprou passagem só de ida para outra galáxia.","Júpiter no seu signo aumenta sua confiança. Você apresenta um rascunho de duas linhas como plano diretor de um império.","Com Júpiter no seu signo, tudo parece possível. Até sua procrastinação planeja expansão internacional."]},"saturnInSign":{"classic":["Saturno atravessa seu signo e convida a construir com método. Esforços constantes podem dar mais solidez às escolhas.","A passagem de Saturno pelo seu signo destaca responsabilidades escolhidas e o valor dos compromissos duradouros.","Com Saturno no seu signo, definir limites pode favorecer uma maturidade serena, sem exigir perfeição."],"funny":["Saturno atravessa seu signo. Você abre uma pasta para organizar a vida; ela contém o inventário das outras pastas.","Com Saturno no seu signo, chegam as responsabilidades. Sua agenda já exige assinatura em cada compromisso.","Saturno está no seu signo. Você segue as regras com orgulho até descobrir que ninguém conhece a regra sete."],"piquant":["Saturno atravessa seu signo: a disciplina entra em cena. Sua agenda agora tem mais autoridade que você.","Saturno no seu signo pede constância. Você escreveu doze páginas de regras para adiar a primeira tarefa.","Saturno atravessa seu signo. Às vezes você confunde maturidade com controle de qualidade de uma caminhada."]},"venusRx":{"classic":["Vênus retrógrada convida a reavaliar gostos, sentimentos e a maneira como você valoriza seus vínculos.","O movimento retrógrado de Vênus evoca simbolicamente lembranças afetivas, sem confundi-las com o presente.","Quando Vênus parece retroceder, refletir sobre desejos pode revelar prazeres mais alinhados aos seus valores."],"funny":["Vênus retrógrada: você acha uma playlist antiga e cada música quer uma ata oficial das suas escolhas passadas.","Vênus retrógrada leva você a rever favoritos antigos. Lá está uma decoração que você jurava detestar.","Durante Vênus retrógrada, você relê uma mensagem antiga e agradece ao celular por nunca tê-la enviado."],"piquant":["Vênus retrógrada ressuscita seus gostos antigos. Você chama de nostalgia; o histórico de buscas chama de provas.","Vênus retrógrada convida a rever critérios. Sua lista de exigências já parece o regulamento de um palácio vazio.","Vênus retrógrada põe o passado na vitrine. Você corre até lá como se as más ideias estivessem em promoção."]},"marsRx":{"classic":["Marte retrógrado sugere rever o uso da sua energia. Um desvio pensado pode ser mais útil que uma ação forçada.","Quando Marte parece retroceder, os impulsos desacelerados ajudam a distinguir urgência real de impaciência.","O movimento retrógrado de Marte convida a ajustar objetivos e encontrar formas de agir com mais moderação."],"funny":["Marte retrógrado: você aperta três vezes o botão do elevador. Ele ainda não leu sua agenda.","Marte retrógrado freia seu impulso. Você decide correr atrás das ideias; elas pedem uma reunião de alinhamento.","Marte retrógrado: até a impressora parece pensar em cada página. Você prepara um discurso motivacional."],"piquant":["Marte retrógrado reduz o ritmo. Sua estratégia é empurrar com força uma porta que diz 'puxe'.","Durante Marte retrógrado, a impaciência assume o volante. Pena que a orientação ficou em casa.","Marte retrógrado convida a rever o plano. Você quer acelerar como maestro que critica o metrônomo por marcar o tempo certo."]},"jupiterRx":{"classic":["Júpiter retrógrado convida a avaliar ambições pelo que realmente importa. O crescimento também pode ser interior.","Quando Júpiter parece retroceder, rever um projeto pode revelar recursos que os resultados imediatos escondem.","O movimento retrógrado de Júpiter favorece simbolicamente a reflexão sobre suas convicções e projetos de expansão."],"funny":["Júpiter retrógrado: seu grande plano de expansão vira uma visita às pastas esquecidas. Tem até uma chamada 'organizar'.","Júpiter retrógrado convida a explorar seu mundo interior. Você abre um diário e encontra um plano de limpeza abandonado.","Durante Júpiter retrógrado, você revê metas. O projeto 'conquistar o mundo' finalmente perde a prioridade máxima."],"piquant":["Júpiter retrógrado reduz o espetáculo. Sua ambição era um dirigível; os detalhes revelaram a corda que o prendia.","Júpiter retrógrado pede reflexão antes do crescimento. Seu ego já encomendou um letreiro para um projeto imaginário.","Júpiter retrógrado traz os projetos de volta à terra. Seu plano monumental cabia num guardanapo, que também tinha ressalvas."]},"saturnRx":{"classic":["Saturno retrógrado sugere rever as regras que você segue. Algumas ajudam, outras merecem evoluir.","Quando Saturno parece retroceder, o sentido dos compromissos pode importar mais que a quantidade deles.","O movimento retrógrado de Saturno convida a separar a responsabilidade escolhida das obrigações mantidas por hábito."],"funny":["Saturno retrógrado: você relê suas regras e descobre uma cláusula que proíbe diversão antes de terminar tudo.","Saturno retrógrado convida a rever compromissos. Você encontra a promessa solene de limpar o teclado toda terça-feira.","Durante Saturno retrógrado, você audita sua disciplina. Até sua planilha de controle quer férias."],"piquant":["Saturno retrógrado põe suas regras em revisão. Você ergueu uma fortaleza de normas e perdeu a planta da saída.","Saturno retrógrado pergunta por que você segue suas próprias regras. O regulamento exige autorização para responder.","Saturno retrógrado questiona seus compromissos. Você coleciona responsabilidades como troféus e estranha o peso da prateleira."]},"eclipseSolar":{"classic":["Um eclipse solar se aproxima: na tradição, simboliza o fim de um ciclo e a possibilidade de recomeçar.","Perto do eclipse solar, uma mudança de perspectiva pode levar você a questionar um hábito antigo.","O próximo eclipse solar evoca simbolicamente uma transição. Acolher imprevistos pode abrir novos caminhos."],"funny":["Um eclipse solar se aproxima. Você também planeja uma grande mudança: arrastar o sofá quinze centímetros.","O eclipse solar está chegando: o universo prepara algo raro, e você ainda procura o controle remoto.","Um eclipse solar se anuncia. Você proclama um novo capítulo; o primeiro episódio é encontrar suas meias."],"piquant":["O eclipse solar se aproxima e evoca uma virada. Você quer mudar de vida mantendo os mesmos hábitos: ousado.","Um eclipse solar está chegando. Seu plano de renovação é tão vago que um rascunho de rascunho parece detalhado.","O eclipse solar lembra que o cenário pode mudar. Você quer um grande sinal, mas ignora o óbvio há semanas."]},"eclipseLunar":{"classic":["Um eclipse lunar se aproxima e simboliza um capítulo a observar com mais clareza, sem presumir seu desfecho.","Perto do eclipse lunar, emoções antigas podem pedir reconhecimento e compreensão.","O próximo eclipse lunar convida simbolicamente a encerrar uma etapa com delicadeza e abrir espaço a novas referências."],"funny":["O eclipse lunar se aproxima. Você decide virar a página, mas passa uma hora escolhendo o marcador de livro.","Um eclipse lunar se anuncia: suas emoções preparam um grande desabafo. Você ainda procura a caixa onde guardou tudo.","Perto do eclipse lunar, você revê lembranças. A gaveta de recibos se recusa a testemunhar."],"piquant":["O eclipse lunar se aproxima e convida a encerrar um capítulo. Você prefere acrescentar cinquenta páginas para dar a última palavra.","Um eclipse lunar se aproxima. Seus não ditos reservaram salão, crachás e palestra; sua sinceridade não foi convidada.","O eclipse lunar ilumina simbolicamente suas emoções. Você constrói um labirinto para elas e ainda vende o mapa."]},"meteors":{"classic":["As {shower} cruzam o céu e lembram como o encanto pode caber num instante de atenção.","Durante as {shower}, olhar para o céu noturno convida a desacelerar e apreciar a beleza do momento.","As {shower} iluminam a noite por instantes. Sua passagem pode despertar desejos simples, sem prometer realizá-los."],"funny":["As {shower} passam pelo céu. Você prepara um pedido maravilhoso e esquece a parte principal na hora de falar.","Para ver as {shower}, você se acomoda. Seu vizinho escolhe esse momento para testar as luzes do jardim.","As {shower} oferecem um espetáculo noturno. Você procura um meteoro, mas o aplicativo do tempo quer cinco atualizações."],"piquant":["As {shower} cruzam a noite. Até os meteoros ganham impulso; você ainda negocia com o botão 'mais tarde'.","As {shower} deixam rastros luminosos. Seus pedidos são tão detalhados que precisariam de uma comissão avaliadora.","Durante as {shower}, você espera um grande sinal. O céu oferece meteoros; você prefere uma notificação sem importância."]}}});
